  function renderSiteLock(unavailable = false) {
    ensureSiteLockStyles();
    closeModal();
    const app = document.querySelector('.app');
    app?.classList.add('site-locked-mode');
    document.querySelector('#headerAction').style.display = 'none';
    document.querySelector('#crumb').textContent = unavailable ? 'Kapcsolat ellenőrzése' : 'Portál zárolva';
    document.querySelector('#content').innerHTML = `<section class="site-lock-card"><div class="site-lock-mark">${unavailable?'!':'🔒'}</div><div class="eyebrow">HUNOR · CSAPATPORTÁL</div><h1>${unavailable?'A portál állapota nem ellenőrizhető':'A portál ideiglenesen zárolva van'}</h1><p>${unavailable?'A biztonsági állapotot most nem sikerült lekérdezni. A tartalom védelme érdekében próbáld újra néhány pillanat múlva.':'A hozzáférést az adminisztrátor ideiglenesen korlátozta. A portál a feloldás után lesz újra elérhető.'}</p>${unavailable?'<button class="pill-btn" onclick="checkSiteLockNow()">Újrapróbálás</button>':'<button class="pill-btn" onclick="openAuth(\'login\')">Admin belépés</button>'}</section>`;
  }

  async function forceNonAdminOut() {
    sessionRevision++;
    stopChatUnread();
    await stopPresence();
    stopTeamChatRealtime();
    try { await sb.auth.signOut({scope:'local'}); } catch (error) { console.error('A helyi munkamenet lezárása nem sikerült.', error); }
    user = null; guest = false; localStorage.removeItem('hunor_user');
    renderSiteLock(false);
  }

  window.checkSiteLockNow = function() {
    if (siteLockCheck) return siteLockCheck;
    siteLockCheck = checkSiteLockOnce().finally(() => { siteLockCheck = null; });
    return siteLockCheck;
  };
  async function checkSiteLockOnce() {
    try {
      await readSiteLockState();
      if (siteLocked && !user?.isAdmin) return forceNonAdminOut();
      if (!siteLocked && document.querySelector('.site-locked-mode')) {
        document.querySelector('.app')?.classList.remove('site-locked-mode');
        // A failed status request is not a sign-out. Revalidate the stored
        // session and server-side role before restoring the protected screen.
        await window.retryHunorSession();
      }
    } catch (error) {
      console.error('Nem sikerült ellenőrizni a portál zárolását.', error);
      siteLockUnavailable = true;
      if (!user?.isAdmin) renderSiteLock(true);
    }
  };

  function startSiteLockPolling() {
    if (siteLockPoll) clearInterval(siteLockPoll);
    siteLockPoll = setInterval(() => {if(document.visibilityState==='visible')window.checkSiteLockNow();}, 15000);
    document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') window.checkSiteLockNow(); });
  }


  async function fetchAllEvents() {
    const rows = [];
    // Continue past the Data API row limit so both years are complete.
    for (let offset = 0;;) {
      const { data, error } = await sb.from('events').select('*')
        .order('starts_at', { ascending: true }).order('id', { ascending: true })
        .range(offset, offset + 499);
      if (error) throw error;
      if (!data?.length) break;
      rows.push(...data); offset += data.length;if(data.length<500)break;
    }
    return rows;
  }

  window.syncExconFromSupabase = async function() {
    try {
      const localExcon = read('excon_evaluations', []);
      const { data: remoteExcon, error: exconErr } = await sb.from('excon_evaluations').select('*').order('created_at', { ascending: false });
      if (!exconErr && Array.isArray(remoteExcon)) {
        const remapEv = id => (!id || id === 'default' || id === 'daecad36-acba-4568-b94a-472076b04467' || !/^[0-9a-f-]{36}$/i.test(id)) ? '57cc70be-38e0-41ab-a1c5-49b54d3062d2' : id;
        const makeKey = x => `${(x.evaluator_name || '').trim().toLowerCase()}|${(x.checkpoint_code || '').trim().toLowerCase()}|${remapEv(x.event_id) || ''}`;
        const remoteKeys = new Set(remoteExcon.map(makeKey));
        const toUpload = [];
        const seenUpload = new Set();
        for (const item of localExcon) {
          if (!item || !item.evaluator_name || !item.checkpoint_code) continue;
          const k = makeKey(item);
          if (!remoteKeys.has(k) && !seenUpload.has(k)) {
            seenUpload.add(k);
            toUpload.push({
              evaluator_name: item.evaluator_name,
              checkpoint_code: item.checkpoint_code,
              event_id: remapEv(item.event_id),
              score: Number(item.score),
              comment: item.comment || ''
            });
          }
        }
        if (toUpload.length > 0) {
          const { data: inserted, error: upErr } = await sb.from('excon_evaluations').insert(toUpload).select('*');
          if (!upErr && Array.isArray(inserted)) {
            remoteExcon.unshift(...inserted);
          } else if (upErr) {
            console.warn('Batch EXCON feltöltés hiba, egyenkénti próba:', upErr);
            for (const row of toUpload) {
              const safeScore = [-1, 0, 1, 2].includes(row.score) ? row.score : -1;
              let r1 = await sb.from('excon_evaluations').insert({ ...row, score: safeScore }).select('*');
              if (r1.error && row.event_id) {
                r1 = await sb.from('excon_evaluations').insert({ ...row, event_id: null, score: safeScore }).select('*');
              }
              if (!r1.error && Array.isArray(r1.data)) remoteExcon.unshift(...r1.data);
            }
          }
        }
        const mergedMap = new Map();
        remoteExcon.forEach(r => mergedMap.set(makeKey(r), r));
        localExcon.forEach(l => {
          const k = makeKey(l);
          if (!mergedMap.has(k)) mergedMap.set(k, l);
        });
        save('excon_evaluations', Array.from(mergedMap.values()));
      }
    } catch (e) {
      console.warn('excon_evaluations sync nem sikerült:', e);
    }
    try {
      const localPart = read('participant_evaluations', []);
      const { data: remotePart, error: partErr } = await sb.from('participant_evaluations').select('*').order('created_at', { ascending: false });
      if (!partErr && Array.isArray(remotePart)) {
        const pKey = x => `${x.form_type || ''}|${x.anon_token || ''}|${x.event_id || ''}`;
        const remotePKeys = new Set(remotePart.map(pKey));
        const toUploadP = [];
        for (const item of localPart) {
          if (!item || !item.form_type || !item.anon_token) continue;
          const k = pKey(item);
          if (!remotePKeys.has(k)) {
            remotePKeys.add(k);
            toUploadP.push({
              event_id: (item.event_id && /^[0-9a-f-]{36}$/i.test(item.event_id)) ? item.event_id : null,
              form_type: item.form_type,
              anon_token: item.anon_token,
              responses: item.responses || {}
            });
          }
        }
        if (toUploadP.length > 0) {
          const { data: insertedP } = await sb.from('participant_evaluations').insert(toUploadP).select('*');
          if (Array.isArray(insertedP)) remotePart.unshift(...insertedP);
        }
        const mergedP = new Map();
        remotePart.forEach(r => mergedP.set(pKey(r), r));
        localPart.forEach(l => {
          const k = pKey(l);
          if (!mergedP.has(k)) mergedP.set(k, l);
        });
        save('participant_evaluations', Array.from(mergedP.values()));
      }
    } catch (e) {
      console.warn('participant_evaluations sync nem sikerült:', e);
    }
    try {
      const { data: conclRows, error: conclErr } = await sb.from('event_conclusions').select('*');
      if (!conclErr && Array.isArray(conclRows)) {
        for (const row of conclRows) {
          if (!row?.event_id) continue;
          let attachments = [];
          if (row.recommendations) {
            try {
              const parsed = JSON.parse(row.recommendations);
              if (Array.isArray(parsed?.attachments)) attachments = parsed.attachments;
            } catch (_) {}
          }
          const localPrev = read('concl_' + row.event_id, null) || {};
          const localAtts = Array.isArray(localPrev.attachments) ? localPrev.attachments : [];
          const mergedAttMap = new Map();
          attachments.forEach(a => { if (a?.id) mergedAttMap.set(a.id, a); });
          localAtts.forEach(a => { if (a?.id && !mergedAttMap.has(a.id)) mergedAttMap.set(a.id, a); });
          save('concl_' + row.event_id, {
            conclusion: row.conclusion_text || localPrev.conclusion || '',
            strengths: row.strengths || localPrev.strengths || '',
            improvements: row.improvements || localPrev.improvements || '',
            attachments: Array.from(mergedAttMap.values()),
            author: row.author_name || localPrev.author || '',
            date: row.updated_at ? new Date(row.updated_at).toLocaleDateString('hu-HU') : (localPrev.date || '')
          });
        }
      }
    } catch (e) {
      console.warn('event_conclusions sync nem sikerült:', e);
    }
  };

  async function loadPageData(page) {
    if(page==='home') await loadNews();
    await refreshNavigationCounts();
    if (page === 'profile') { await loadMyProfile(); return; }
    if (page === 'logistics') { await loadLogistics(); return; }
    if (user?.membershipStatus === 'approved' && page === 'home') {
      window.myAlertabilityUnset=null;
      const { data: approvedProfiles, error: profilesError } = await sb.from('profiles').select('id').eq('membership_status', 'approved');
      if (profilesError) throw profilesError;
      const memberIds = (approvedProfiles || []).map(profile => profile.id);
      let alertabilityRows = [];
      if (memberIds.length) {
        const { data, error } = await sb.from('member_alertability').select('member_id,is_alertable').in('member_id', memberIds);
        if (error) throw error;
        alertabilityRows = data || [];
      }
      window.myAlertabilityUnset = !alertabilityRows.some(row=>row.member_id===user.id && typeof row.is_alertable==='boolean');
      window.alertabilityOverviewCounts = {
        yes: alertabilityRows.filter(row => row.is_alertable === true).length,
        no: alertabilityRows.filter(row => row.is_alertable === false).length,
        unset: Math.max(0, memberIds.length - alertabilityRows.filter(row=>typeof row.is_alertable==='boolean').length)
      };
    }
    if (page === 'landing' || page === 'home' || page === 'events' || page === 'videos') {
      const { data, error } = await rxFetchPublicResources();
      if (error) throw error;
      publicItems = await mapPublicResources(data || []);
    }
    if (page === 'landing' || page === 'events' || page === 'pending' || page === 'dashboard' || page === 'excon') {
      const rows = await fetchAllEvents();
      guestEvents.splice(0, guestEvents.length, ...rows.filter(x => x.visibility === 'public').map(mapEvent));
      events = user?.membershipStatus === 'approved' ? rows.map(mapEvent) : guestEvents.slice();
    }
    if (user?.membershipStatus === 'approved' && ['videos','education','approvals'].includes(page)) {
      const { data: resourceRows, error: resourceError } = await sb.from('resources').select('*, profiles!resources_created_by_fkey(name)').in('visibility',page==='education'?['members']:page==='approvals'?['members','public']:['public']).order('created_at', { ascending: false });
      if (resourceError) throw resourceError;
      if(page!=='education')publicItems = await mapPublicResources((resourceRows || []).filter(x => x.visibility === 'public'));
      materials = (resourceRows || []).filter(HunorKnowledgeCore.isVisibleMaterial).map(mapResource);
      if (page === 'education') {
        await pfEducationLinks(materials);
      }
    }
    if (user?.membershipStatus === 'approved' && ['home','calendar','events','videos','dashboard','excon'].includes(page)) {
      if (!['events','dashboard','excon'].includes(page)) events = (await fetchAllEvents()).map(mapEvent);
      const ids = events.map(x => x.id).filter(Boolean);
      let participantRows = [];
      if (ids.length) {
        const { data, error: participantError } = await sb.from('event_participants').select('event_id,member_id,response,participation_role,profiles(name)').in('event_id', ids);
        if (participantError) console.error('Nem sikerült betölteni az események jelentkezéseit.', participantError);
        else participantRows = data || [];
      }
      for (const event of events) {
        const rows = participantRows.filter(x => x.event_id === event.id && x.response === 'going');
        event.registrationCount = rows.length;
        event.myResponse = participantRows.find(x => x.event_id === event.id && x.member_id === user.id)?.response || null;
        event.myParticipationRole=participantRows.find(x=>x.event_id===event.id&&x.member_id===user.id)?.participation_role||null;
        event.registrants = rows.map(x => x.profiles?.name || 'Csapattag'); const exconNames = rows.filter(x => x.participation_role === 'excon').map(x => x.profiles?.name).filter(Boolean); event.exconRegistrants = exconNames; event.participantRegistrants = rows.filter(x => x.participation_role !== 'excon').map(x => x.profiles?.name).filter(Boolean); if (exconNames.length && window.syncExconApplicantsFromEvent) window.syncExconApplicantsFromEvent(event.id, exconNames);
      }
    }
    if (user?.membershipStatus === 'approved' && page === 'forum') {
      const { data, error } = await sb.from('forum_posts').select('*, profiles(name)').order('created_at', { ascending: false });
      if (error) throw error;
      posts = (data || []).map(x => ({ id: x.id, title: x.title, body: x.content, author: x.profiles?.name || 'Csapattag', ago: new Date(x.created_at).toLocaleString('hu-HU'), replies: 0, icon: '✳' }));
    }
    if (user?.membershipStatus === 'approved' && page === 'chat') {
      const { data, error } = await sb.from('team_chat_messages').select('id,author_id,content,created_at,profiles(name)').order('created_at', { ascending: false }).order('id',{ascending:false}).limit(100);
      if (error) throw error;
      chatMessages = (data || []).reverse();
    }
    if (user?.membershipStatus === 'approved' && (page === 'members' || page === 'dashboard' || page === 'excon')) {
      const { data: rows, error } = await sb.from('profiles').select('id,name,rank,workplace,county,position,phone,email,avatar_path,notes').eq('membership_status','approved').order('name');
      if (error) throw error;
      const ids = (rows || []).map(x => x.id);
      const [{ data: skillRows }, { data: roleRows }, { data: alertabilityRows, error: alertabilityError },{data:expiryRows,error:expiryError}] = await Promise.all([
        ids.length ? sb.from('skills').select('member_id,name').in('member_id', ids) : Promise.resolve({data:[]}),
        ids.length ? sb.from('member_roles').select('member_id,role,granted_roles,permissions_version,can_upload_education,can_manage_logistics,can_edit_news,can_access_excon').in('member_id', ids) : Promise.resolve({data:[]}),
        ids.length ? sb.from('member_alertability').select('member_id,is_alertable,updated_at').in('member_id', ids) : Promise.resolve({data:[],error:null}),deReadMembers(ids)
      ]);
      if (alertabilityError) throw alertabilityError;
      const skillsById = Object.groupBy ? Object.groupBy(skillRows || [], x => x.member_id) : null;
      await pfMemberPhotos(rows||[]);
      members.splice(0, members.length, ...(rows || []).map((x, i) => ({
        id: x.id, name: x.name, initial: initials(x.name || '?'), color: ['av1','av2','av3','av4'][i % 4],
        documentExpiries:(expiryRows||[]).find(d=>d.member_id===x.id)||null,documentExpiryError:Boolean(expiryError),photoUrl: x.avatar_url || '', avatarPath: x.avatar_path || '', notes:x.notes||'',
        role: x.position || 'Tag', permissionRole: (roleRows || []).find(r => r.member_id === x.id)?.role || 'member',
        grantedRoles:(roleRows||[]).find(r=>r.member_id===x.id)?.granted_roles||[(roleRows||[]).find(r=>r.member_id===x.id)?.role||'member'],
        permissionVersion:(roleRows||[]).find(r=>r.member_id===x.id)?.permissions_version||1,
        canUploadEducation: Boolean((roleRows || []).find(r => r.member_id === x.id)?.can_upload_education),
        canManageLogistics: Boolean((roleRows || []).find(r => r.member_id === x.id)?.can_manage_logistics),
        canEditNews: Boolean((roleRows || []).find(r => r.member_id === x.id)?.can_edit_news),
        canAccessExcon: Boolean((roleRows || []).find(r => r.member_id === x.id)?.can_access_excon),
        email: x.email, phone: x.phone, serviceLocation: x.workplace,county:x.county,
        alertable: (alertabilityRows || []).find(r => r.member_id === x.id)?.is_alertable ?? null,
        alertabilityUpdatedAt: (alertabilityRows || []).find(r => r.member_id === x.id)?.updated_at || null,
        skills: skillsById ? (skillsById[x.id] || []).map(s => s.name) : (skillRows || []).filter(s => s.member_id === x.id).map(s => s.name)
      })));
    }
    if (page === 'dashboard' || page === 'excon' || page === 'evaluations') {
      await window.syncExconFromSupabase();
    }
    if (user?.isAdmin && page === 'approvals') {
      const { data, error } = await sb.from('profiles').select('id,name,phone,email,workplace,county,position,requested_skills,created_at').eq('membership_status','pending').order('created_at');
      if (error) throw error;
      pending = data || [];window.hunorNavCounts.approvals=pending.length;renderApprovalCount();
    }
  }

  function mapEvent(row) {
    const date = new Date(row.starts_at);
    const endDate = row.ends_at ? new Date(row.ends_at) : new Date(date.getTime() + 60 * 60 * 1000);
    const dateInputValue = d => [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
    const event = { id: row.id, startsAt:row.starts_at, endsAt:row.ends_at||endDate.toISOString(), title: row.title, date: dateInputValue(date), time: date.toLocaleTimeString('hu-HU',{hour:'2-digit',minute:'2-digit'}), endDate: dateInputValue(endDate), endTime: endDate.toLocaleTimeString('hu-HU',{hour:'2-digit',minute:'2-digit'}), place: row.location || '', eventType:row.event_type, kind: eventName[row.event_type] || eventName.other, visibility: row.visibility, description: row.description || '' };
    event.tone = row.event_type === 'alert' ? 'blue' : row.event_type === 'demonstration' ? 'orange' : '';
    return event;
  }
  function eventTimeRange(event) {
    if (!event.endTime) return event.time;
    return event.endDate && event.endDate !== event.date
      ? `${event.time} – ${event.endDate} ${event.endTime}`
      : `${event.time}–${event.endTime}`;
  }
  function mapResource(row) {
    const labels = { article: 'Cikk', video: 'Videó', image: 'Kép', document: 'Dokumentum', link: 'Hivatkozás' };
    return { id: row.id, uploaderName: row.profiles?.name || 'Nem elérhető', title: row.title, description: row.description || '', url: row.url || '', filePath: row.file_path || '', fileName: row.file_name || '', fileUrl: '', educationCategory: row.education_category || '', date: new Date(row.created_at).toLocaleDateString('hu-HU'), entryType: labels[row.resource_type] || row.resource_type, kind: labels[row.resource_type] || row.resource_type, visibility: row.visibility };
  }
  async function mapPublicResources(rows) { return mapArticleResources(rows); }

  function showPending() {
    const rejected = user?.membershipStatus === 'rejected';
    return `<div class="page-title"><div><div class="eyebrow">HUNOR TAGSÁGI KÉRELEM</div><h1>${rejected ? 'A kérelmedet elutasítottuk' : 'Jóváhagyásra vár'}</h1><p>${rejected ? 'Ha kérdésed van, keresd az adminisztrátort.' : 'A fiókod elkészült. A zárt csapattartalmak az admin jóváhagyása után nyílnak meg.'}</p></div></div><div class="panel"><p>Bejelentkezve: <b>${esc(user?.email || '')}</b></p><button class="secondary" onclick="logoutHunor()">Kilépés</button></div>`;
  }

  window.setPage = async function(p) {
    if(!idleSync())return;
    const routeActor=user?.id||null;
    try {
      await readSiteLockState();
    } catch (error) {
      console.error('Nem sikerült ellenőrizni a portál zárolását.', error);
      siteLockUnavailable = true;
      if (!user?.isAdmin) renderSiteLock(true);
      return;
    }
    if (siteLocked && !user?.isAdmin) {
      await forceNonAdminOut();
      return;
    }
    document.querySelector('.app')?.classList.remove('site-locked-mode');
    syncPresence();
    if (!guest && !user && p !== 'landing') p = 'landing';
    if (guest && !['events','videos','dashboard','excon','evaluations'].includes(p)) p = 'events';
    if (user && !user.isAdmin && user.membershipStatus !== 'approved' && p !== 'pending') p = 'pending';
    knowledgeView?.destroy();knowledgeView=null;
    knowledgeEnsureNav();
    if(await knowledgeOpenRoute(p))return;
    stEnsureNav();
    ensureExconNav();
    ensureTeamChatNavItem();
    syncChatUnread();
    ensurePublicVideosNavItem();
    const chatNavItem = document.querySelector('#navTeamChat');
    if (chatNavItem) chatNavItem.style.display = user?.membershipStatus === 'approved' ? '' : 'none';
    const videosNavItem = document.querySelector('#navPublicVideos');
    if (videosNavItem) videosNavItem.style.display = guest || user?.membershipStatus === 'approved' ? '' : 'none';
    if (user?.membershipStatus === 'approved') ensureTeamChatStyles();
    try { await loadPageData(p); }
    catch (error) {
      console.error('HUNOR adatbetöltési hiba', error);
      if (p === 'logistics') {
        page=p; document.querySelector('#crumb').textContent='Logisztika'; document.querySelector('#headerAction').style.display='none';
        content.innerHTML='<div class="panel"><h1>Logisztika</h1><p>A logisztikai adatok nem tölthetők be.</p><button class="pill-btn" onclick="setPage(\'logistics\')">Újrapróbálás</button></div>';
        history.replaceState(null,'','#logistics'); return;
      }
      if (p === 'profile') {
        page=p; document.querySelector('#crumb').textContent='Profilom'; document.querySelector('#headerAction').style.display='none';
        content.innerHTML='<div class="panel"><h1>Profilom</h1><p>A profil betöltése nem sikerült.</p><button class="pill-btn" onclick="setPage(\'profile\')">Újrapróbálás</button></div>';
        history.replaceState(null,'','#profile'); return;
      }
      if (p === 'events') {
        page = p;
        document.querySelectorAll('#nav button').forEach(b => b.classList.toggle('active', b.dataset.page === p));
        document.querySelector('#crumb').textContent = 'Események';
        document.querySelector('#headerAction').style.display = 'none';
        content.innerHTML = '<div class="page-title"><h1>Események</h1></div><div class="panel"><p>Az eseményeket most nem sikerült betölteni. Próbáld újra.</p><button class="pill-btn" onclick="setPage(\'events\')">Újrapróbálás</button></div>';
        history.replaceState(null, '', '#events');
        return;
      }
    }
    if(routeActor&&routeActor!==user?.id)return;
    if (p === 'staffing') {
      if (guest || user?.membershipStatus !== 'approved') return window.setPage(user ? 'pending' : 'landing');
      stopTeamChatRealtime();
      page='staffing';document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
      document.querySelector('#crumb').textContent='Állománytábla';document.querySelector('#headerAction').style.display='none';
      await stLoadPage();
      if(page==='staffing'&&user?.id===routeActor){history.replaceState(null,'','#staffing');window.scrollTo(0,0);}
      return;
    }
    if (p === 'excon') {
      stopTeamChatRealtime();
      const {data:allowed,error}=await sb.rpc('hunor_excon_access');
      if(routeActor!==user?.id)return;
      if(error || !allowed){notify('Az EXCON fülhöz EXCON tag engedély szükséges.');return window.setPage('home');}
      page='excon';document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
      document.querySelector('#crumb').textContent='EXCON';document.querySelector('#headerAction').style.display='none';
      await exLoadPage();
      history.replaceState(null,'','#excon');window.scrollTo(0,0);return;
    }
    if (p === 'pending') {
      page = p;
      document.querySelectorAll('#nav button').forEach(b => b.classList.remove('active'));
      document.querySelector('#crumb').textContent = 'Jóváhagyás';
      document.querySelector('#headerAction').style.display = 'none';
      content.innerHTML = showPending();
      history.replaceState(null,'','#pending');
      return;
    }
    if (p === 'videos') {
      stopTeamChatRealtime();
      page = p;
      document.querySelectorAll('#nav button').forEach(b => b.classList.toggle('active', b.dataset.page === p));
      document.querySelector('#crumb').textContent = 'Videók';
      document.querySelector('#headerAction').style.display = 'none';
      content.innerHTML = window.videoLibraryPage();
      history.replaceState(null,'','#videos');
      window.scrollTo(0,0);
      return;
    }
    if (p === 'members') ensureMemberPhotoStyles();
    if (p === 'education') ensureEducationFolderStyles();
    if (p === 'chat') {
      if (user?.membershipStatus !== 'approved') return window.setPage('landing');
      stopTeamChatRealtime();
      page = 'chat';
      ensureTeamChatStyles();
      document.querySelectorAll('#nav button').forEach(b => b.classList.toggle('active', b.dataset.page === 'chat'));
      document.querySelector('#crumb').textContent = 'Csapat chat';
      document.querySelector('#headerAction').style.display = 'none';
      content.innerHTML = teamChatPage();
      history.replaceState(null,'','#chat');
      window.scrollTo(0,0);
      renderTeamChatMessages();
      bindTeamChatForm();
      startTeamChatRealtime();
      return;
    }
    stopTeamChatRealtime();
    originalSetPage(p);
    syncNewsPolling();
    if (p === 'home') content.querySelector('.progress-wrap')?.remove();
    ensureEventRowStyles();
    if (user?.membershipStatus === 'approved' && ['home','calendar','events'].includes(p)) decorateEventRows();
  };

