  async function loadMyProfile() {
    if (user?.membershipStatus !== 'approved') throw new Error('Jóváhagyott tagság szükséges.');
    const [{data:profile,error:profileError},{data:skills,error:skillsError},{data:availability,error:availabilityError}] = await Promise.all([
      sb.from('profiles').select('id,name,email,phone,workplace,county,position,rank,notes,avatar_path').eq('id',user.id).single(),
      sb.from('skills').select('name').eq('member_id',user.id).order('name'),
      sb.from('member_alertability').select('is_alertable,updated_at').eq('member_id',user.id).maybeSingle()
    ]);
    if (profileError || skillsError || availabilityError) throw profileError || skillsError || availabilityError;
    let photoUrl = '';
    if (profile.avatar_path) {
      const {data,error} = await sb.storage.from(MEMBER_PHOTO_BUCKET).createSignedUrl(profile.avatar_path,300);
      if (error) console.error('A profilképet most nem sikerült betölteni.',error);
      else photoUrl = data.signedUrl;
    }
    const [{data:privateDetails,error:privateDetailsError},{data:documentControl,error:documentControlError}]=await Promise.all([sb.from('member_private_details').select('*').eq('member_id',user.id).maybeSingle(),sb.from('member_document_controls').select('alertability_locked,passport_override_for,review_note').eq('member_id',user.id).maybeSingle()]);
    if(privateDetailsError||documentControlError)throw new Error('A kiegészítő profiladatok nem tölthetők be.');
    myProfile = {...profile,...(privateDetails||{}),county:privateDetails?.county||profile.county||'',documentControl,photoUrl,alertable:availability?.is_alertable ?? null};
    k9DogsDraft=(myProfile.k9_dogs||[]).map(d=>({...d}));
    window.myAlertabilityUnset = myProfile.alertable === null;
    profileSkillsDraft = (skills || []).map(s=>s.name);
    Object.assign(user,{name:profile.name,phone:profile.phone||'',serviceLocation:profile.workplace||'',role:profile.position||'Tag',skills:profileSkillsDraft.slice()});
    document.querySelector('#sideName').textContent = user.name;
    const avatar = document.querySelector('#sideAvatar');
    if (avatar) avatar.innerHTML = photoUrl ? `<img src="${esc(photoUrl)}" alt="">` : esc(initials(user.name));
  }

  window.profilePage = function() {
    const p = myProfile;
    if (!p || p.id !== user?.id) return '<div class="panel"><h1>Profilom</h1><p>A profil még nem töltődött be.</p><button class="pill-btn" onclick="setPage(\'profile\')">Újrapróbálás</button></div>';
    return `<div class="page-title"><div><div class="eyebrow">HUNOR · SAJÁT ADATOK</div><h1>Profilom</h1><p>Általános adatok, egészségügyi információk, iratok és személyes méretek.</p></div></div>
    <div class="profile-layout"><section class="panel profile-photo-panel"><div class="profile-photo" id="profilePhotoPreview">${p.photoUrl?`<img src="${esc(p.photoUrl)}" alt="${esc(p.name)} profilképe">`:`<span>${esc(initials(p.name))}</span>`}</div><h2>${esc(p.name)}</h2><p>${esc(user.permissionLabel||'Csapattag')}</p><label class="secondary profile-photo-picker" for="myProfilePhoto">${p.avatar_path?'Profilkép cseréje':'Profilkép feltöltése'}</label><input id="myProfilePhoto" type="file" accept="image/jpeg,image/png,image/webp" class="visually-hidden" onchange="uploadMyProfilePhoto(this)"><small>JPG, PNG vagy WebP · legfeljebb 5 MB</small><p id="profilePhotoStatus" class="profile-status" role="status"></p><button type="button" class="secondary" onclick="openPasswordReset()">Jelszó visszaállítása e-mailben</button></section>
    <form id="myProfileForm" class="panel profile-form" onsubmit="saveMyProfile(event)" autocomplete="off">${personalProfileTabs()}<div id="personal-panel-general" class="personal-profile-panel" role="tabpanel" aria-labelledby="personal-tab-general" ${personalProfileTab!=='general'?'hidden':''}><h2>Általános adatok</h2><div class="profile-fields">
    <div class="field"><label for="myProfileName">Teljes név</label><input id="myProfileName" name="name" required maxlength="120" autocomplete="name" value="${esc(p.name)}"></div>
    <div class="field"><label for="myProfileRank">Rendfokozat</label><input id="myProfileRank" name="rank" maxlength="100" value="${esc(p.rank||'')}"></div>
    <div class="field"><label for="myProfilePhone">Telefonszám</label><input id="myProfilePhone" name="phone" type="tel" maxlength="40" autocomplete="tel" value="${esc(p.phone||'')}"></div>
    <div class="field"><label for="myProfileEmail">Kapcsolattartási e-mail</label><input id="myProfileEmail" name="email" type="email" maxlength="254" autocomplete="email" value="${esc(p.email||user.email||'')}"></div>
    <div class="field"><label for="myProfileCounty">Megye</label><input id="myProfileCounty" name="county" required minlength="2" maxlength="160" value="${esc(p.county||'')}"></div><div class="field"><label for="myProfileWorkplace">Szolgálati hely</label><input id="myProfileWorkplace" name="workplace" maxlength="160" value="${esc(p.workplace||'')}"></div>
    <div class="field"><label for="myProfilePosition">Beosztás a HUNOR-ban</label><input id="myProfilePosition" name="position" maxlength="100" list="hunorPositions" value="${esc(p.position||'')}"><datalist id="hunorPositions">${positions.map(v=>`<option value="${esc(v)}">`).join('')}</datalist></div></div>
    ${personalGeneralFields(p)}<p class="profile-help">Belépési e-mail-cím: ${esc(user.email)}. A kapcsolattartási címet a tagnévsorban használjuk.</p>
    <section class="profile-section"><h2>Riaszthatóság</h2><label class="field" for="myProfileAlertability">Jelenlegi állapot<select id="myProfileAlertability" name="alertable"><option value="" disabled ${p.alertable===null?'selected':''}>Nincs beállítva</option><option value="true" ${p.alertable===true?'selected':''}>Riasztható vagyok</option><option value="false" ${p.alertable===false?'selected':''}>Most nem vagyok riasztható</option></select></label><p class="profile-help">A mentett állapot a tagnévsorban és a riasztási beosztás készítésekor is megjelenik.</p></section>
    <section class="profile-section"><h2>Képességek</h2><div id="myProfileSkills" class="profile-skills">${profileSkillChips()}</div><div class="profile-skill-entry"><label class="visually-hidden" for="myProfileSkillInput">Új képesség</label><input id="myProfileSkillInput" maxlength="80" placeholder="Pl. elsősegély, K9, műszaki mentés" onkeydown="if(event.key==='Enter'){event.preventDefault();addMyProfileSkill()}"><button type="button" class="secondary" onclick="addMyProfileSkill()">＋ Hozzáadás</button></div><small class="profile-help">Legfeljebb 30 képesség. Mentés előtt a × gombbal eltávolíthatod őket.</small></section>
    <section class="profile-section"><h2>Megjegyzés</h2><label class="visually-hidden" for="myProfileNotes">Megjegyzés a profilhoz</label><textarea id="myProfileNotes" name="notes" rows="5" maxlength="2000" placeholder="További hasznos információ a csapattársaknak…">${esc(p.notes||'')}</textarea><p class="profile-help">A megjegyzést minden jóváhagyott csapattag láthatja.</p></section>
    ${personalExtraPanels(p)}<div class="profile-save-row"><button type="submit" class="pill-btn" id="myProfileSave">Változtatások mentése</button><span id="profileSaveStatus" role="status"></span></div></form></div>`;
  };
  function profileSkillChips() {
    return profileSkillsDraft.length ? profileSkillsDraft.map((s,i)=>`<span class="profile-skill-chip">${esc(s)}<button type="button" aria-label="${esc(s)} eltávolítása" onclick="removeMyProfileSkill(${i})">×</button></span>`).join('') : '<small>Még nincs hozzáadott képesség.</small>';
  }
  window.addMyProfileSkill = function() {
    const input = document.querySelector('#myProfileSkillInput');
    const value = input?.value.trim();
    if (!value) return true;
    if (value.length > 80) { notify('Egy képesség legfeljebb 80 karakter lehet.'); return false; }
    if (profileSkillsDraft.some(s=>s.toLocaleLowerCase('hu')===value.toLocaleLowerCase('hu'))) { input.value=''; return true; }
    if (profileSkillsDraft.length >= 30) { notify('Legfeljebb 30 képességet adhatsz hozzá.'); return false; }
    profileSkillsDraft.push(value); input.value='';
    document.querySelector('#myProfileSkills').innerHTML = profileSkillChips();
    input.focus(); return true;
  };
  window.removeMyProfileSkill = i => {
    if (profileSaving || !Number.isInteger(i) || i<0 || i>=profileSkillsDraft.length) return;
    profileSkillsDraft.splice(i,1);
    document.querySelector('#myProfileSkills').innerHTML = profileSkillChips();
  };
  window.saveMyProfile = async function(event) {
    event.preventDefault();
    if (user?.membershipStatus !== 'approved' || profileSaving || profilePhotoUploading) return;
    if (!window.addMyProfileSkill()) return;
    const k9Payload=collectK9ForSave();if(!k9Payload)return;
    const form = event.currentTarget, fields = Object.fromEntries(new FormData(form));const vaccinations=mdCollectVaccines(form);if(!vaccinations)return;
    if (!fields.name.trim()) return notify('Add meg a teljes neved.');
    const status = document.querySelector('#profileSaveStatus');
    profileSaving = true;
    form.querySelectorAll('input,textarea,select,button').forEach(el=>el.disabled=true);
    status.textContent = 'Mentés…';
    try {
      const {error} = await sb.rpc('hunor_save_k9_profile',{p_name:fields.name.trim(),p_email:fields.email.trim(),p_phone:fields.phone.trim(),p_workplace:fields.workplace.trim(),p_position:fields.position.trim(),p_rank:fields.rank.trim(),p_skills:profileSkillsDraft.slice(),p_notes:fields.notes,p_alertable:fields.alertable==='true'?true:fields.alertable==='false'?false:null,p_details:{...Object.fromEntries(privateProfileFields.map(k=>[k,fields[k]??''])),vaccinations},p_documents:{driving_licence_number:fields.driving_licence_number||'',identity_card_number:fields.identity_card_number||''},p_k9_handler:k9Payload.handler,p_k9_dogs:k9Payload.dogs});
      if (error) throw error;
      try { await loadMyProfile(); } catch(refreshError) { console.error('A profil mentve, a frissítés nem sikerült.',refreshError); }
      Object.assign(user,{skills:profileSkillsDraft.slice()});
      try { localStorage.setItem('hunor_user',JSON.stringify(user)); } catch {}
      status.textContent = 'A változtatások mentve.';
      if(document.querySelector('.profile-photo-panel h2')) document.querySelector('.profile-photo-panel h2').textContent = user.name;
      notify('A profilod minden adatlapja mentve.');
    } catch(error) { status.textContent='A mentés nem sikerült. Az adataid a mezőkben megmaradtak.'; tellError(error,'Nem sikerült menteni a profilt.'); }
    finally { profileSaving=false; form.querySelectorAll('input,textarea,select,button').forEach(el=>el.disabled=false);mdPaintLocks(); }
  };
  window.uploadMyProfilePhoto = async function(input) {
    if (user?.membershipStatus !== 'approved' || !myProfile || myProfile.id !== user.id || profilePhotoUploading || profileSaving) return;
    const file=input.files?.[0]; if (!file) return;
    const status=document.querySelector('#profilePhotoStatus');
    if (!['image/jpeg','image/png','image/webp'].includes(file.type) || file.size>5*1024*1024) { input.value=''; return notify('JPG, PNG vagy WebP képet válassz, legfeljebb 5 MB méretben.'); }
    profilePhotoUploading=true; input.disabled=true; document.querySelector('#myProfileSave').disabled=true; status.textContent='Kép feltöltése…';
    const ownerId=user.id, oldPath=myProfile.avatar_path, extension=file.type==='image/jpeg'?'jpg':file.type.split('/')[1];
    const path=`${ownerId}/${crypto.randomUUID()}.${extension}`;
    let uploaded=false, linked=false;
    try {
      if (typeof createImageBitmap==='function') { const bitmap=await createImageBitmap(file); bitmap.close(); }
      const {error:uploadError}=await sb.storage.from(MEMBER_PHOTO_BUCKET).upload(path,file,{contentType:file.type,cacheControl:'3600',upsert:false});
      if (uploadError) throw uploadError; uploaded=true;
      const {data:updated,error:updateError}=await sb.from('profiles').update({avatar_path:path}).eq('id',ownerId).select('id').single();
      if (updateError || !updated) throw updateError || new Error('A profilkép nem rendelhető a profilodhoz.');
      linked=true; myProfile.avatar_path=path;
      const {data:signed,error:signedError}=await sb.storage.from(MEMBER_PHOTO_BUCKET).createSignedUrl(path,300);
      if (!signedError && signed) {
        myProfile.photoUrl=signed.signedUrl;
        if(document.querySelector('#profilePhotoPreview')) document.querySelector('#profilePhotoPreview').innerHTML=`<img src="${esc(signed.signedUrl)}" alt="Profilképed">`;
        document.querySelector('#sideAvatar').innerHTML=`<img src="${esc(signed.signedUrl)}" alt="">`;
      }
      if (oldPath && oldPath!==path && oldPath.startsWith(ownerId+'/')) {
        const {error}=await sb.storage.from(MEMBER_PHOTO_BUCKET).remove([oldPath]);
        if (error) console.error('A régi profilkép eltávolítása nem sikerült.',error);
      }
      status.textContent=signedError?'A kép mentve. Az előnézethez frissítsd a profilt.':'A profilképed frissült.';
      if(document.querySelector('.profile-photo-picker')) document.querySelector('.profile-photo-picker').textContent='Profilkép cseréje';
    } catch(error) {
      if (uploaded && !linked) await sb.storage.from(MEMBER_PHOTO_BUCKET).remove([path]);
      status.textContent='A profilkép feltöltése nem sikerült.'; tellError(error,'Nem sikerült feltölteni a profilképet.');
    } finally { profilePhotoUploading=false; input.value=''; input.disabled=false; const save=document.querySelector('#myProfileSave'); if(save)save.disabled=false; }
  };

  function renderPresenceWidget() {
    const widget=document.querySelector('#onlineTeam');
    if (!widget) return;
    const visible=Boolean(user?.isAdmin && !guest);
    widget.hidden=!visible;
    if (!visible) { widget.replaceChildren(); return; }
    widget.innerHTML=`<div class="mini-head"><span>A csapatunk</span><span class="online-dot" aria-hidden="true"></span></div><b class="online-total">${presenceError?'–':presenceRows.length} ${presenceError?'':'fő online'}</b>${presenceError?'<small role="status">Az online lista most nem érhető el.</small>':`<ul class="online-members">${presenceRows.map(row=>`<li><span class="online-initial">${esc(initials(row.name||'Csapattag'))}</span><span>${esc(row.name||'Csapattag')}</span></li>`).join('')||'<li>Most nincs aktív csapattag.</li>'}</ul><small>Csak adminnak · aktív, belépett tagok<br>Frissül 20 másodpercenként</small>`}`;
  }
  async function refreshPresence() {
    if (presenceInFlight) return presenceInFlight;
    const actor=user?.id, session=presenceSession;
    if (!actor || guest || user.membershipStatus!=='approved' || (siteLocked && !user.isAdmin) || document.visibilityState!=='visible') return;
    presenceInFlight=(async()=>{
      const {error}=await sb.rpc('hunor_presence_ping',{p_session:session,p_active:true});
      if (error) throw error;
      if (user?.id!==actor || guest) return;
      if (user.isAdmin) {
        const {data,error:listError}=await sb.rpc('hunor_online_members');
        if (listError) throw listError;
        if (user?.id!==actor || !user.isAdmin || guest) return;
        presenceRows=data||[];
      }
      presenceError=false; renderPresenceWidget();
    })().catch(error=>{console.error('Az online állapot frissítése nem sikerült.',error);presenceError=true;presenceRows=[];renderPresenceWidget();}).finally(()=>{presenceInFlight=null;});
    return presenceInFlight;
  }
  function syncPresence() {
    const active=Boolean(user?.membershipStatus==='approved' && !guest && (!siteLocked || user.isAdmin));
    if (!active) { stopPresence(); renderPresenceWidget(); return; }
    if (presenceUserId!==user.id) {
      stopPresence(); presenceSession=crypto.randomUUID(); presenceUserId=user.id;
      presenceRows=[]; presenceError=false;
      refreshPresence();
      presenceTimer=setInterval(refreshPresence,20000);
    }
    renderPresenceWidget();
  }
  async function stopPresence() {
    const hadPresence=Boolean(presenceUserId), session=presenceSession; presenceUserId=null;
    if (presenceTimer) clearInterval(presenceTimer); presenceTimer=null;
    presenceRows=[];
    if (hadPresence) {
      try { await presenceInFlight; await sb.rpc('hunor_presence_ping',{p_session:session,p_active:false}); }
      catch(error) { console.error('Az online állapot lezárása nem sikerült.',error); }
    }
  }
  document.addEventListener('visibilitychange',()=>{
    if (document.visibilityState==='visible') { syncPresence(); refreshPresence(); }
    else if (presenceUserId) { stopPresence(); }
  });
  window.addEventListener('pagehide',()=>{
    // Browsers may cancel a request at close; server-side expiry is the fallback.
    if (presenceUserId) sb.rpc('hunor_presence_ping',{p_session:presenceSession,p_active:false}).then(()=>{}).catch(()=>{});
  });

  function ensureExconNav(){let b=document.querySelector("#nav [data-page=\"excon\"]");b?.remove();}
  function renderParticipationGroups(event,people){
    const row=p=>`<div class="event-attendee"><span><b>${esc(p.profiles?.name||'Csapattag')}</b>${p.profiles?.position?`<small>${esc(p.profiles.position)}</small>`:''}</span>${user?.isAdmin&&event.eventType==='exercise'?`<label class="participation-admin"><span class="sr-only">${esc(p.profiles?.name)} besorolása</span><select aria-label="${esc(p.profiles?.name)} besorolása" onchange="changeParticipationRole('${event.id}','${p.member_id}',this)"><option value="excon" ${p.participation_role==='excon'?'selected':''}>EXCON</option><option value="participant" ${p.participation_role!=='excon'?'selected':''}>Résztvevő</option></select></label>`:''}</div>`;
    if(event.eventType!=='exercise')return people.length?`<div class="event-attendee-list">${people.map(row).join('')}</div>`:'<div class="empty">Még senki nem jelentkezett.</div>';
    return `<div class="exercise-groups">${[['excon','EXCON'],['participant','Résztvevők']].map(([role,label])=>{const list=people.filter(p=>(p.participation_role||'participant')===role);return `<section class="exercise-group ${role}"><h4>${label}<span>${list.length}</span></h4><div class="event-attendee-list">${list.length?list.map(row).join(''):'<p class="log-help">Még nincs jelentkező.</p>'}</div></section>`;}).join('')}</div>`;
  }
  window.changeParticipationRole=async(eventId,memberId,input)=>{
    if(!user?.isAdmin)return;input.disabled=true;
    const {error}=await sb.from('event_participants').update({participation_role:input.value}).eq('event_id',eventId).eq('member_id',memberId);
    if(error){tellError(error,'A besorolás nem menthető.');await window.openEventDetails(eventId);return;}
    const event=events.find(e=>e.id===eventId),body=document.querySelector('#eventDetailsBody');
    if(event&&body)await renderEventDetails(event,body);notify('A jelentkező besorolását módosítottuk.');
  };
  const logNullable=value=>value===null||value===undefined||String(value).trim()===''?null:Number(value);
  function logWeightSummary(rows){const unknown=rows.filter(a=>a.total_kg===null).length;return logNumber(rows.reduce((n,a)=>n+Number(a.total_kg),0))+' kg'+(unknown?' + '+unknown+' ismeretlen tömeg':'');}
  function logCrateColor(a){return a.category==='medical'?'#37b77c':a.category==='k9'?'#3987e8':a.category==='command'?'#ed8a32':a.category==='lighting'?'#e9eef5':['camp','tents','bathing'].includes(a.category)?'#202832':'#edc84a';}
  function logCrateGraphic(a){const color=logCrateColor(a);return `<svg class="log-crate-art" viewBox="0 0 120 86" role="img" aria-label="${esc(logCategories[a.category]||'Felszerelés')} láda" style="--crate:${color}"><path d="M12 28 29 11h65l15 17-12 46H21z" fill="var(--crate)" stroke="#8393a3" stroke-width="2"/><path d="M12 28h97M30 12v16m63-16v16M22 40v22m76-22v22M37 33v36m45-36v36" stroke="#071321" stroke-opacity=".45" stroke-width="4"/><rect x="48" y="41" width="24" height="12" rx="3" fill="#0b1728" stroke="#93a4b8"/><path d="M52 45h16" stroke="#acb8c8" stroke-width="2"/><rect x="20" y="25" width="14" height="10" rx="2" fill="#102034"/><rect x="87" y="25" width="14" height="10" rx="2" fill="#102034"/><path d="M28 78h64" stroke="#000" stroke-opacity=".18" stroke-width="5" stroke-linecap="round"/></svg>`;}
  function logCrateLegend(){return `<div class="crate-legend" aria-label="Ládák színjelölése">${[['medical','Medic'],['search','Mentő'],['camp','Tábor'],['lighting','Világítás'],['k9','K9'],['command','Törzs']].map(([category,label])=>`<span><i style="background:${logCrateColor({category})}"></i>${label}</span>`).join('')}</div>`;}
  function logManifestMetadata(a){if(!a.source_metadata?.file)return '';const m=a.source_metadata;return `<details class="log-source-details"><summary>Excel-forrás és importadatok</summary><p>${esc(m.file)} · ${(m.sheets||[]).map(esc).join(', ')}</p>${m.price_rows?.length?`<p>Árlap: ${m.price_rows.map(p=>`${esc(p.row)}. sor${p.value_huf!==null?' · '+logNumber(p.value_huf)+' Ft':''}`).join(' / ')}</p>`:''}${m.conflicts?`<p class="log-warning">Eltérő forrásadatok miatt néhány méret vagy tömeg megerősítésre vár.</p><pre>${esc(JSON.stringify(m.conflicts,null,2))}</pre>`:''}<p class="log-help">A tárolóhely az import során javasolt besorolás. A forrás összes eredeti eszközadata megmaradt a nyilvántartásban.</p></details>`;}

  const logCategories={camp:'Tábori felszerelések',tents:'Tábori felszerelések › Sátrak',bathing:'Tábori felszerelések › Fürdető',shoring:'Shoring',rope:'Alpin',search:'Kutató felszerelések',recon:'Felderítés',command:'Törzs',medical:'Egészségügy',communications:'Híradás',lighting:'Világítás és energia',k9:'K9',other:'Egyéb'};
  const logKinds={warehouse:'Központi raktár',rack:'Polc',bin:'Tárolóhely',vehicle:'Jármű',site:'Helyszín'};
  const logVehicleTypes={car:'Személyautó',van:'Kisbusz',bus:'Autóbusz',truck:'Teherautó',aircraft:'Repülő',trailer:'Utánfutó',other:'Egyéb'};
  const logConditions={ready:'Bevethető',repair:'Javításra vár',incomplete:'Hiányos'};
  const logActions={created:'Felvéve',updated:'Adatok módosítva',reviewed:'Készlet felülvizsgálva',moved:'Átrakodás',archived:'Archiválva',restored:'Visszaállítva'};
  let logistics={locations:[],assets:[],people:[],history:[]};
  let logView='warehouse',logLocation=null,logSearch='',logCategory='',logArchived=false,logBusy=false,logDraft=[];
  const logSelected=new Set();
  const canManageLogistics=()=>Boolean(user?.membershipStatus==='approved' && (user.isAdmin||user.canManageLogistics));
  const logNumber=n=>n===null||n===undefined||n===''?'—':Number(n).toLocaleString('hu-HU',{maximumFractionDigits:2});
  const logLoc=id=>logistics.locations.find(l=>l.id===id);
  const logPerson=id=>logistics.people.find(p=>p.id===id)?.name||'Már nem aktív csapattag';
  const logAssets=id=>logistics.assets.filter(a=>a.active && (!id||a.location_id===id));
  function logPath(id) {const parts=[];let l=logLoc(id),guard=0;while(l&&guard++<4){parts.unshift(l.code+' · '+l.name);l=logLoc(l.parent_id);}return parts.join(' / ');}
  function logDue(a) {const d=new Date(a.reviewed_at),day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+6);const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,last));return d;}
  function logOptions(obj,value) {return Object.entries(obj).map(([key,label])=>`<option value="${key}" ${key===value?'selected':''}>${esc(label)}</option>`).join('');}
  function logPlaceOptions(value,{exclude=null,kinds=null}={}) {return logistics.locations.filter(l=>l.active&&l.id!==exclude&&(!kinds||kinds.includes(l.kind))).map(l=>`<option value="${l.id}" ${l.id===value?'selected':''}>${esc(logPath(l.id))}</option>`).join('');}
  function logField(name,label,value='',type='text',extra='') {return `<label class="log-field">${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${extra}></label>`;}
  async function loadLogistics() {
    if(user?.membershipStatus!=='approved') throw new Error('Jóváhagyott tagság szükséges.');
    const actor=user.id;
    const results=await Promise.all([
      logFetchAll('logistics_locations','code'),logFetchAll('logistics_assets','code'),
      sb.from('profiles').select('id,name').eq('membership_status','approved').order('name'),
      sb.from('logistics_history').select('id,asset_id,action,from_label,to_label,actor_name,note,created_at').order('created_at',{ascending:false}).limit(200),
      sb.from('member_roles').select('can_manage_logistics').eq('member_id',actor).single(),
      logFetchAll('logistics_pallets','code'),logFetchAll('logistics_pallet_items','asset_id'),
      logFetchAll('logistics_pallet_home_items','asset_id'),logFetchAll('logistics_missions','id'),logFetchAll('logistics_mission_items','mission_id'),logFetchAll('logistics_floor_items','id')
    ]);
    for(const r of results)if(r.error)throw r.error;
    if(user?.id!==actor)throw new Error('A belépett felhasználó megváltozott.');
    logistics={locations:results[0].data||[],assets:results[1].data||[],people:results[2].data||[],history:results[3].data||[]};
    user.canManageLogistics=Boolean(results[4].data.can_manage_logistics);
    vwPallets=results[5].data||[];vwItems=results[6].data||[];
    wfHomes=results[7].data||[];wfMissions=results[8].data||[];wfLines=results[9].data||[];f5Items=results[10].data||[];
    if(!logLoc(logLocation)?.active)logLocation=logistics.locations.find(l=>l.kind==='warehouse')?.id||null;
    logSelected.clear();
  }
  async function logFetchAll(table,order){const rows=[];for(let offset=0;;offset+=500){let query=sb.from(table).select('*').order(order);if(table==='logistics_mission_items')query=query.order('asset_id');const {data,error}=await query.range(offset,offset+499);if(error)throw error;rows.push(...data);if(data.length<500)break;}return {data:rows};}
  function renderLogistics(){if(page==='logistics')content.innerHTML=window.logisticsPage();}
  window.logSetView=v=>{if(!['warehouse','assets','transport','history'].includes(v))return;logView=v;logSelected.clear();if(v==='warehouse'&&['site','vehicle'].includes(logLoc(logLocation)?.kind))logLocation=logistics.locations.find(l=>l.kind==='warehouse')?.id;if(v==='transport'&&!['site','vehicle'].includes(logLoc(logLocation)?.kind))logLocation=logistics.locations.find(l=>l.active&&['vehicle','site'].includes(l.kind))?.id||null;renderLogistics();};
  window.logOpenLocation=id=>{logLocation=id;logSelected.clear();renderLogistics();};
  window.logFilter=()=>{logSearch=document.querySelector('#logSearch')?.value||'';logCategory=document.querySelector('#logCategory')?.value||'';logArchived=Boolean(document.querySelector('#logArchived')?.checked);logSelected.clear();const list=document.querySelector('#logAssetList');if(list)list.innerHTML=logAssetTable(logView==='assets'?null:logLocation);logUpdateSelection();};
  window.logToggleAsset=(id,checked)=>{if(checked)logSelected.add(id);else logSelected.delete(id);logUpdateSelection();};
  function logUpdateSelection(){const b=document.querySelector('#logMoveSelected');if(b){b.textContent=`Kijelöltek áthelyezése (${logSelected.size})`;b.disabled=!logSelected.size;}}
  window.logisticsPage=function(){
    const active=logistics.assets.filter(a=>a.active),warehouse=logistics.locations.find(l=>l.kind==='warehouse');
    const inWarehouse=a=>{let l=logLoc(a.location_id);for(let i=0;l&&i<4;i++){if(l.kind==='warehouse')return true;l=logLoc(l.parent_id);}return false;};
    const overdue=active.filter(a=>a.source_metadata?.physical_review_pending||logDue(a)<new Date()).length;
    return `<div class="page-title"><div><div class="eyebrow">HUNOR · LOGISZTIKAI KEZELŐPLATFORM</div><h1>Logisztika</h1><p>Központi raktár, állandó készletek és követhető szállítás.</p></div><span class="log-access">${canManageLogistics()?'Logisztikai adminisztrátor':'Megtekintési jogosultság'}</span></div>
    <div class="log-kpis"><div><small>Ládák és önálló eszközök</small><b>${active.length}</b></div><div><small>Raktárban</small><b>${active.filter(inWarehouse).length}</b></div><div><small>Járművön / helyszínen</small><b>${active.filter(a=>!inWarehouse(a)).length}</b></div><div class="${overdue?'log-attention':''}"><small>Ellenőrzésre váró készletek</small><b>${overdue}</b></div></div>
    ${logGlobalSearchBox()}<nav class="log-tabs" aria-label="Logisztikai nézetek">${[['warehouse','▦ Raktártérkép'],['assets','▣ Ládák és eszközök'],['transport','⇄ Járművek és helyszínek'],['history','◷ Mozgási napló']].map(([id,label])=>`<button class="${logView===id?'active':''}" onclick="logSetView('${id}')">${label}</button>`).join('')}<button onclick="setPage('logistics')" class="log-refresh">↻ Frissítés</button></nav>
    ${logView==='history'?`<section class="panel"><h2>Mozgási és készletnapló</h2><p class="log-help">A legutóbbi 200 változás. Egy eszköz előzményei az adatlapján érhetők el.</p>${logHistoryRows(logistics.history)}</section>`:
      logView==='assets'?`<section class="panel">${logAssetHeader('Teljes eszközjegyzék')}<div id="logAssetList">${logAssetTable(null)}</div></section>`:
      `${logView==='warehouse'?`<section class="panel log-map"><div class="panel-head"><h2>Raktár · polcok · tárolóhelyek</h2>${canManageLogistics()?`<button class="secondary" onclick="logEditLocation('rack')">＋ Polc</button>`:''}</div>${logCrateLegend()}<p class="log-help">Válassz polcot vagy tárolóhelyet a benne tárolt készlet megtekintéséhez. Az importált polcrend javaslat: a tényleges raktári helyekkel egyeztetendő. A rajz nem méretarányos.</p><button class="log-location-tile log-root ${logLocation===warehouse?.id?'selected':''}" onclick="logOpenLocation('${warehouse?.id}')"><b>▦ ${esc(warehouse?.name||'Központi raktár')}</b><small>Beérkezési / kiadási terület · ${logAssets(warehouse?.id).length} egység</small></button><div class="log-racks">${logistics.locations.filter(l=>l.active&&l.kind==='rack').map(r=>`<article class="log-rack"><button class="log-rack-heading ${logLocation===r.id?'selected':''}" onclick="logOpenLocation('${r.id}')"><b>${esc(r.code)}</b><span>${esc(r.name)}</span><small>${logAssets(r.id).length} egység közvetlenül a polcon</small></button><div class="log-bins">${logistics.locations.filter(b=>b.active&&b.parent_id===r.id).map(b=>`<button class="log-location-tile ${logLocation===b.id?'selected':''}" onclick="logOpenLocation('${b.id}')"><b>${esc(b.code)}</b><small>${esc(b.name)}</small><span>${logAssets(b.id).length} egység · ${logWeightSummary(logAssets(b.id))}</span><span class="log-crate-strip">${logAssets(b.id).slice(0,6).map(a=>`<em class="crate-mini" style="--crate:${logCrateColor(a)}">${logCrateGraphic(a)}${esc(a.code)}</em>`).join('')}${logAssets(b.id).length>6?`<em>+${logAssets(b.id).length-6}</em>`:''}</span></button>`).join('')||'<p class="log-help">Még nincs tárolóhely.</p>'}</div>${canManageLogistics()?`<button class="text-btn" onclick="logEditLocation('bin',null,'${r.id}')">＋ Tárolóhely</button>`:''}</article>`).join('')||'<div class="log-empty">A raktár még üres. Elsőként hozz létre polcokat, majd tárolóhelyeket.</div>'}</div></section>`:logTransportCards()}
      ${logLocationPanel()}${logArchivedLocations()}`}`;
  };
  function logTransportCards(){return `<section class="panel"><div class="panel-head"><h2>Szállítóeszközök és célhelyek</h2><div class="log-buttons">${canManageLogistics()?`<button class="secondary" onclick="logEditLocation('vehicle')">＋ Jármű</button><button class="secondary" onclick="logEditLocation('site')">＋ Helyszín</button>`:''}</div></div><div class="log-transports">${logistics.locations.filter(l=>l.active&&['vehicle','site'].includes(l.kind)).map(l=>{const cargo=logAssets(l.id),kg=cargo.reduce((n,a)=>n+Number(a.total_kg),0)+vwPallets.filter(p=>p.location_id===l.id).reduce((n,p)=>n+Number(p.tare_kg||0),0),used=kg+Number(l.people_weight_kg||0),ratio=l.payload_kg>0?Math.min(100,100*used/Number(l.payload_kg)):0;return `<button class="log-transport ${logLocation===l.id?'selected':''}" onclick="logOpenLocation('${l.id}')"><span class="log-transport-icon">${l.kind==='site'?'⚑':l.vehicle_type==='aircraft'?'✈':l.vehicle_type==='truck'?'▰':'⇄'}</span><b>${esc(l.name)}</b><small>${esc(l.kind==='site'?l.code:(l.registration+' · '+logVehicleTypes[l.vehicle_type]))}</small><span>${cargo.length} egység · ${logNumber(kg)} kg rakomány</span>${l.kind==='vehicle'?`<span class="log-meter"><i style="width:${ratio}%"></i></span><small>${l.payload_kg===null?'Teherbírás nincs megadva':`${logNumber(used)} / ${logNumber(l.payload_kg)} kg összes terhelés`}</small><small>${l.passenger_ids.length} fő${l.seats!==null?' / '+l.seats+' férőhely':''}${l.blue_light?' · Kéklámpás':''}</small>`:''}</button>`;}).join('')||'<div class="log-empty">Még nincs jármű vagy műveleti helyszín.</div>'}</div></section>`;}
  function logLocationPanel(){const l=logLoc(logLocation);if(!l)return '';return `<section class="panel log-location-detail"><div class="panel-head"><div><div class="eyebrow">${esc(logKinds[l.kind])}</div><h2>${esc(l.name)}</h2><p class="log-help">${esc(logPath(l.id))}</p></div>${canManageLogistics()?`<button class="secondary" onclick="logEditLocation('${l.kind}','${l.id}')">Hely adatainak szerkesztése</button>`:''}</div>${l.notes?`<p class="log-note">${esc(l.notes)}</p>`:''}${l.kind==='vehicle'?`<div class="log-vehicle-facts"><div><small>Rendszám / lajstromjel</small><b>${esc(l.registration)}</b></div><div><small>Sofőr / szállításfelelős</small><b>${l.driver_id?esc(logPerson(l.driver_id)):'Nincs megadva'}</b></div><div><small>Teherbírás</small><b>${l.payload_kg===null?'Nincs megadva':logNumber(l.payload_kg)+' kg'}</b></div><div><small>Raktér (h × sz × m)</small><b>${[l.cargo_length_cm,l.cargo_width_cm,l.cargo_height_cm].every(v=>v!==null)?[l.cargo_length_cm,l.cargo_width_cm,l.cargo_height_cm].map(logNumber).join(' × ')+' cm':'Nincs teljesen megadva'}</b></div></div><p class="log-help">Utasok, a sofőrrel együtt (${l.passenger_ids.length}${l.seats!==null?' / '+l.seats:''} fő): ${l.passenger_ids.length?l.passenger_ids.map(id=>esc(logPerson(id))).join(', '):'Nincsenek hozzárendelve.'}</p><p class="log-help">${l.blue_light?'Kéklámpával rendelkezik.':'Nincs kéklámpa.'} Utasok és személyes csomagok megadott tömege: ${logNumber(l.people_weight_kg)} kg.</p>${l.passenger_ids.length&&!Number(l.people_weight_kg)?'<p class="log-warning">Az utasok tömege még nincs megadva; a terhelési összesítés nem teljes.</p>':''}${l.payload_kg===null?'<p class="log-warning">A teherbírás megadásáig a tömeghatár nem ellenőrizhető.</p>':''}<p class="log-help">A térfogat- és méretellenőrzés becslés. A rakodási elrendezést, ajtónyílást és a szállítási előírásokat külön ellenőrizni kell.</p>`:''}${logAssetHeader('Itt tárolt / szállított készlet')}<div id="logAssetList">${logAssetTable(l.id)}</div></section>`;}
  function logAssetHeader(title){return `<div class="panel-head"><h2>${title}</h2><div class="log-buttons"><button class="secondary" onclick="logExportManifest()">↓ Rakodási lista</button>${canManageLogistics()?`<button class="secondary" id="logMoveSelected" onclick="logMoveDialog()" disabled>Kijelöltek áthelyezése (0)</button><button class="pill-btn" onclick="logEditAsset()">＋ Láda / eszköz</button>`:''}</div></div><div class="log-filters"><input id="logSearch" aria-label="Láda vagy eszköz keresése" placeholder="Azonosító, név vagy tartalom…" value="${esc(logSearch)}" oninput="logFilter()"><select id="logCategory" aria-label="Kategória" onchange="logFilter()"><option value="">Minden kategória</option>${logOptions(logCategories,logCategory)}</select><label><input id="logArchived" type="checkbox" onchange="logFilter()" ${logArchived?'checked':''}> Archiváltak is</label></div>`;}
  function logAssetTable(location){const rows=logistics.assets.filter(a=>(logArchived||a.active)&&(!location||a.location_id===location)&&(!logCategory||a.category===logCategory||(logCategory==='camp'&&['tents','bathing'].includes(a.category)))&&(!logSearch||[a.code,a.name,...(a.contents||[]).map(i=>i.name)].join(' ').toLocaleLowerCase('hu').includes(logSearch.toLocaleLowerCase('hu'))));return rows.length?`<div class="log-table-wrap"><table class="log-table"><thead><tr>${canManageLogistics()?'<th>Kijelölés</th>':''}<th>Láda / eszköz</th><th>Kategória</th><th>Méret · tömeg</th><th>Hely / állapot</th><th>Adatlap</th></tr></thead><tbody>${rows.map(a=>`<tr>${canManageLogistics()?`<td><input type="checkbox" aria-label="${esc(a.code)} kijelölése" onchange="logToggleAsset('${a.id}',this.checked)" ${logSelected.has(a.id)?'checked':''} ${!a.active?'disabled':''}></td>`:''}<td>${logCrateGraphic(a)}<b>${esc(a.code)}</b><span>${esc(a.name)}</span><small>${a.kind==='crate'?'Láda':'Önálló eszköz'} · ${(a.contents||[]).length} tartalmi tétel${!a.active?a.source_metadata?.sheets?.[0]==='Láda árak - Chest price'?' · Árlap · megerősítésre vár':' · Archivált':''}</small></td><td>${esc(logCategories[a.category])}</td><td>${[a.length_cm,a.width_cm,a.height_cm].map(logNumber).join(' × ')} cm<span><b>${logNumber(a.total_kg)} kg</b></span></td><td><span>${esc(vwAssetPath(a))}</span><span class="log-condition ${a.condition!=='ready'?'log-warning':''}">${esc(logConditions[a.condition])}</span>${a.source_metadata?.physical_review_pending?'<small class="log-warning">Importált készlet · helyszíni ellenőrzésre vár</small>':logDue(a)<new Date()?'<small class="log-warning">Féléves felülvizsgálat esedékes</small>':''}</td><td><button class="secondary" onclick="logAssetDetail('${a.id}')">Megnyitás →</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="log-empty">Ebben a nézetben nincs láda vagy eszköz.</div>';}
  function logHistoryRows(rows){return rows.length?`<ol class="log-history">${rows.map(h=>`<li><span class="log-history-dot"></span><div><b>${esc(logActions[h.action]||h.action)} · ${esc(logistics.assets.find(a=>a.id===h.asset_id)?.code||'Eszköz')}</b><small>${esc(new Date(h.created_at).toLocaleString('hu-HU',{timeZone:'Europe/Budapest'}))} · ${esc(h.actor_name)}</small>${h.from_label?`<p>${esc(h.from_label)} → ${esc(h.to_label||'')}</p>`:`<p>${esc(h.to_label||'')}</p>`}${h.note?`<p class="log-note">${esc(h.note)}</p>`:''}<button class="text-btn" onclick="logHistorySnapshot('${h.id}')">Rögzített készlet megtekintése</button></div></li>`).join('')}</ol>`:'<div class="log-empty">Még nincs rögzített változás.</div>';}
  function logModal(title,body){openModal(`<div class="log-modal"><div class="panel-head"><h2>${title}</h2><button class="secondary" type="button" onclick="closeModal()" aria-label="Bezárás">×</button></div>${body}</div>`);}
  function logContentsTable(items){return items?.length?`<div class="log-table-wrap"><table class="log-table"><thead><tr><th>Eszköz / adatok</th><th>Mennyiség</th><th>Egységtömeg</th><th>Össztömeg</th></tr></thead><tbody>${items.map(i=>`<tr><td><b>${esc(i.name)}</b>${i.english_name?`<small>${esc(i.english_name)}</small>`:''}${i.manufacturer?`<span>${esc(i.manufacturer)}</span>`:''}${i.serial_number?`<small>Gyári szám / azonosító: ${esc(i.serial_number)}</small>`:''}${i.notes?`<small>${esc(i.notes)}</small>`:''}${i.deficit?`<small class="log-warning">Hiány: ${esc(i.deficit)}</small>`:''}${i.source_sheet?`<small class="log-source">Forrás: ${esc(i.source_sheet)} · ${esc(i.source_row)}. sor</small>`:''}</td><td>${i.quantity===null?'Nincs megadva':logNumber(i.quantity)} ${esc(i.unit||'db')}${i.quantity_original&&i.quantity===null?`<small>Eredeti érték: ${esc(i.quantity_original)}</small>`:''}</td><td>${i.unit_kg===null?'Nincs megadva':logNumber(i.unit_kg)+' kg'}</td><td>${i.quantity===null||i.unit_kg===null?'—':logNumber(Number(i.quantity)*Number(i.unit_kg))+' kg'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="log-help">Tartalomjegyzék nincs megadva; az árlap adatai megerősítésre várhatnak.</p>';}

  window.logAssetDetail=async id=>{const a=logistics.assets.find(x=>x.id===id);if(!a)return;logModal(`${esc(a.code)} · ${esc(a.name)}`,`<div class="crate-detail-hero">${logCrateGraphic(a)}<p>${esc(logCategories[a.category])} · ${esc(vwAssetPath(a))}</p></div><div class="log-vehicle-facts"><div><small>Méretek</small><b>${[a.length_cm,a.width_cm,a.height_cm].map(logNumber).join(' × ')} cm</b></div><div><small>${a.kind==='crate'?'Üres láda':'Saját'} tömege</small><b>${logNumber(a.tare_kg)} kg</b></div><div><small>${a.measured_kg!==null&&a.measured_kg!==undefined?'Megadott teljes tömeg':'Számított teljes tömeg'}</small><b>${logNumber(a.total_kg)} kg</b></div><div><small>Állapot</small><b>${esc(logConditions[a.condition])}</b></div></div><h3>Állandó készlet</h3>${logContentsTable(a.contents)}${logManifestMetadata(a)}<p class="log-note">${esc(a.notes)}</p><p class="log-help">${a.source_metadata?.physical_review_pending?'Az importált készlet helyszíni ellenőrzésre vár. Nyilvántartásba vétel: ':'Utolsó felülvizsgálat: '}${new Date(a.reviewed_at).toLocaleDateString('hu-HU')} · Következő: ${logDue(a).toLocaleDateString('hu-HU')} · Verzió: ${a.version}</p>${canManageLogistics()?`<div class="log-buttons"><button class="pill-btn" onclick="logEditAsset('${id}')">Adatok / készlet szerkesztése</button>${a.active?`<button class="secondary" onclick="logMoveDialog('${id}')">Áthelyezés</button><button class="secondary" onclick="logMarkReviewed('${id}')">Készlet ellenőrizve</button>`:''}<button class="secondary" onclick="logArchiveAsset('${id}')">${a.active?'Archiválás':a.source_metadata?.sheets?.length===1&&a.source_metadata.sheets[0]==='Láda árak - Chest price'?'Készletként jóváhagyás':'Visszaállítás'}</button></div>`:''}<h3>Előzmények</h3><div id="logAssetHistory" data-asset="${id}">Betöltés…</div>`);const rows=[];let failed=false;for(let offset=0;;offset+=500){const {data,error}=await sb.from('logistics_history').select('id,asset_id,action,from_label,to_label,actor_name,note,created_at').eq('asset_id',id).order('created_at',{ascending:false}).order('id').range(offset,offset+499);if(error){failed=true;break;}rows.push(...data);if(data.length<500)break;}const el=document.querySelector('#logAssetHistory');if(el?.dataset.asset===id)el.innerHTML=failed?'<p>Az előzmények most nem érhetők el.</p>':logHistoryRows(rows);};
  window.logHistorySnapshot=async id=>{const {data,error}=await sb.from('logistics_history').select('snapshot,actor_name,created_at,note').eq('id',id).single();if(error)return tellError(error,'Az előzmény nem tölthető be.');const a=data.snapshot;logModal('Rögzített készletállapot',`<h3>${esc(a.code)} · ${esc(a.name)}</h3><p>${esc(new Date(data.created_at).toLocaleString('hu-HU'))} · ${esc(data.actor_name)}</p><p>${logNumber(a.total_kg)} kg · ${[a.length_cm,a.width_cm,a.height_cm].map(logNumber).join(' × ')} cm</p>${logContentsTable(a.contents)}<p class="log-note">${esc(a.notes||'')}</p><p class="log-note">${esc(data.note)}</p>`);};
  async function logRun(form,work,success){if(!canManageLogistics())return notify('Logisztikai adminisztrátori jogosultság szükséges.');if(logBusy)return;logBusy=true;const button=form?.querySelector('[type="submit"]'),status=form?.querySelector('[role="status"]');if(button)button.disabled=true;if(status)status.textContent='Mentés…';let saved=false;try{await work();saved=true;await loadLogistics();closeModal();renderLogistics();notify(success);}catch(error){console.error(error);const message=saved?'A változás mentve, de a nézet frissítése nem sikerült. Nyisd meg újra a Logisztika fület.':error?.code==='23505'?'Ez az azonosító vagy rendszám már szerepel. Válassz egyedit.':error?.message||'A mentés nem sikerült.';if(status)status.textContent=message;else notify(message);}finally{logBusy=false;if(button&&!saved)button.disabled=false;}}
  window.logEditLocation=function(kind,id=null,parent=null){if(!canManageLogistics())return;const l=logLoc(id)||{kind,parent_id:parent,passenger_ids:[],people_weight_kg:0,blue_light:false};logModal(`${id?'Szerkesztés':'Új'} · ${esc(logKinds[kind])}`,`<form id="logLocationForm" onsubmit="logSaveLocation(event,'${kind}',${id?`'${id}'`:'null'})"><div class="log-form-grid">${logField('code','Egyedi azonosító',l.code,'text','required maxlength="40"')}${logField('name','Elnevezés',l.name,'text','required maxlength="160"')}${['rack','bin'].includes(kind)?`<label class="log-field">${kind==='rack'?'Raktár':'Polc'}<select name="parent_id" required>${logPlaceOptions(l.parent_id,{kinds:[kind==='rack'?'warehouse':'rack']})}</select></label>`:''}${kind==='vehicle'?`<label class="log-field">Jármű típusa<select name="vehicle_type">${logOptions(logVehicleTypes,l.vehicle_type||'truck')}</select></label>${logField('registration','Rendszám / lajstromjel',l.registration,'text','required maxlength="40"')}${logField('payload_kg','Teherbírás (kg)',l.payload_kg,'number','min="0" max="1000000000" step="0.01"')}${logField('seats','Férőhely (sofőrrel együtt)',l.seats,'number','min="0" max="300" step="1"')}<label class="log-field">Sofőr / szállításfelelős<select name="driver_id"><option value="">Nincs kijelölve</option>${logistics.people.map(p=>`<option value="${p.id}" ${l.driver_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${logField('people_weight_kg','Utasok + személyes csomagok össztömege (kg)',l.people_weight_kg,'number','min="0" max="1000000000" step="0.01"')}${logField('cargo_length_cm','Raktér hossza (cm)',l.cargo_length_cm,'number','min="0.001" max="100000" step="0.01"')}${logField('cargo_width_cm','Raktér szélessége (cm)',l.cargo_width_cm,'number','min="0.001" max="100000" step="0.01"')}${logField('cargo_height_cm','Raktér magassága (cm)',l.cargo_height_cm,'number','min="0.001" max="100000" step="0.01"')}<label class="log-checkbox"><input name="blue_light" type="checkbox" ${l.blue_light?'checked':''}> Van kéklámpája</label><fieldset class="log-crew"><legend>Utaslista · a sofőr automatikusan beleszámít</legend>${logistics.people.map(p=>`<label><input type="checkbox" name="passengers" value="${p.id}" ${l.passenger_ids.includes(p.id)?'checked':''}> ${esc(p.name)}</label>`).join('')||'<p>Nincs jóváhagyott tag.</p>'}</fieldset><p class="log-help log-full">Az utasok és csomagjaik össztömegét külön add meg. A raktér mindhárom méretét töltsd ki, hogy ellenőrizhető legyen. Egy személy egyszerre egy aktív járműhöz rendelhető.</p>`:''}</div><label class="log-field">${kind==='site'?'Cím, helyszín és megjegyzés':'Megjegyzés'}<textarea name="notes" rows="3" maxlength="2000">${esc(l.notes||'')}</textarea></label><div class="log-buttons"><button class="pill-btn" type="submit">Mentés</button>${id&&kind!=='warehouse'?`<button type="button" class="secondary" onclick="logArchiveLocation('${id}')">Archiválás</button>`:''}<span role="status"></span></div></form>`);};
  window.logSaveLocation=async function(event,kind,id){event.preventDefault();const form=event.currentTarget,f=new FormData(form),value=k=>String(f.get(k)||'').trim(),number=k=>value(k)===''?null:Number(value(k));const payload={kind,code:value('code'),name:value('name'),parent_id:['rack','bin'].includes(kind)?value('parent_id'):null,notes:value('notes')};if(kind==='vehicle'){Object.assign(payload,{vehicle_type:value('vehicle_type'),registration:value('registration').toUpperCase(),driver_id:value('driver_id')||null,passenger_ids:f.getAll('passengers'),payload_kg:number('payload_kg'),seats:number('seats'),people_weight_kg:number('people_weight_kg')||0,blue_light:f.has('blue_light'),cargo_length_cm:number('cargo_length_cm'),cargo_width_cm:number('cargo_width_cm'),cargo_height_cm:number('cargo_height_cm')});const dims=[payload.cargo_length_cm,payload.cargo_width_cm,payload.cargo_height_cm];if(dims.some(x=>x!==null)&&dims.some(x=>x===null))return notify('A raktér mindhárom méretét add meg, vagy hagyd üresen mindet.');}await logRun(form,async()=>{let query=id?sb.from('logistics_locations').update(payload).eq('id',id).eq('updated_at',logLoc(id).updated_at):sb.from('logistics_locations').insert(payload);const {data,error}=await query.select('id').maybeSingle();if(error)throw error;if(!data)throw new Error('A hely adatai időközben megváltoztak. Frissítsd a nézetet.');logLocation=data.id;},'A hely adatai mentve.');};
  window.logArchiveLocation=async id=>{if(!confirm('Archiválod ezt az üres helyet? A korábbi naplóbejegyzések megmaradnak.'))return;await logRun(document.querySelector('#logLocationForm'),async()=>{const {data,error}=await sb.from('logistics_locations').update({active:false}).eq('id',id).eq('updated_at',logLoc(id).updated_at).select('id').maybeSingle();if(error)throw error;if(!data)throw new Error('A hely adatai időközben megváltoztak.');},'A hely archiválva.');};
  window.logEditAsset=function(id=null){if(!canManageLogistics())return;const a=logistics.assets.find(x=>x.id===id)||{kind:'crate',category:'camp',location_id:logLocation,condition:'ready',tare_kg:0};logDraft=(a.contents||[]).map(i=>({...i}));logModal(`${id?'Készlet és adatok szerkesztése':'Új láda / önálló eszköz'}`,`<form id="logAssetForm" onsubmit="logSaveAsset(event,${id?`'${id}'`:'null'})"><div class="log-form-grid"><label class="log-field">Típus<select name="kind" ${id?'disabled':''}><option value="crate" ${a.kind==='crate'?'selected':''}>Sorszámozott láda</option><option value="equipment" ${a.kind==='equipment'?'selected':''}>Önálló eszköz</option></select></label>${logField('code','Egyedi sorszám / azonosító',a.code,'text','required maxlength="50"')}${logField('name','Elnevezés',a.name,'text','required maxlength="160"')}<label class="log-field">Kategória<select name="category">${logOptions(logCategories,a.category)}</select></label>${logField('length_cm','Hossz (cm)',a.length_cm,'number','min="0.001" max="100000" step="0.01"')}${logField('width_cm','Szélesség (cm)',a.width_cm,'number','min="0.001" max="100000" step="0.01"')}${logField('height_cm','Magasság (cm)',a.height_cm,'number','min="0.001" max="100000" step="0.01"')}${logField('stack_limit','Megengedett rétegszám, ezt a ládát is beleszámítva',a.stack_limit??1,'number','required min="1" max="10" step="1"')}${logField('max_top_load_kg','Megengedett ráterhelés (kg), ha ismert',a.max_top_load_kg,'number','min="0" max="1000000" step="0.01"')}${logField('tare_kg','Üres láda / saját eszköz tömege (kg)',a.tare_kg,'number','min="0" max="1000000000" step="0.01"')}${logField('measured_kg','Megadott / mért teljes tömeg (kg)',a.measured_kg,'number','min="0" max="1000000000" step="0.01"')}<label class="log-field">Tárolási hely${id?`<input value="${esc(vwAssetPath(a))}" disabled><small>Áthelyezéshez az átrakodás funkciót használd.</small>`:`<select name="location_id" required>${logPlaceOptions(a.location_id)}</select>`}</label><label class="log-field">Állapot<select name="condition">${logOptions(logConditions,a.condition)}</select></label></div><h3>Állandó tartalomjegyzék</h3><p class="log-help">A láda rendszeres készlete. A megadott teljes tömeg elsőbbséget élvez; üresen hagyva az üres láda és a tételek tömegéből számolunk. A hiányzó értékeket hagyd üresen. Tartalommódosítás után ellenőrizd újra a megadott teljes tömeget. A tartalom változása új készletverzióként megmarad; a következő felülvizsgálat hat hónap múlva esedékes.</p><div id="logContentsEditor"></div><button type="button" class="secondary" onclick="logAddItem()">＋ Tartalmi tétel</button><label class="log-field">Megjegyzés<textarea name="notes" rows="3" maxlength="2000">${esc(a.notes||'')}</textarea></label><div class="log-buttons"><button class="pill-btn" type="submit">Készlet mentése</button><span role="status"></span></div></form>`);logRenderItemEditor();};
  function logReadItems(){const rows=document.querySelectorAll('.log-item-row');logDraft=Array.from(rows).map((row,n)=>({...logDraft[n],name:row.querySelector('[data-item="name"]').value.trim(),quantity:logNullable(row.querySelector('[data-item="quantity"]').value),unit:row.querySelector('[data-item="unit"]').value.trim()||'db',unit_kg:logNullable(row.querySelector('[data-item="unit_kg"]').value)}));}
  function logRenderItemEditor(){const el=document.querySelector('#logContentsEditor');if(el)el.innerHTML=logDraft.map((i,n)=>`<div class="log-item-row"><label>Megnevezés<input data-item="name" value="${esc(i.name)}" required maxlength="160"></label><label>Mennyiség<input data-item="quantity" type="number" min="0" max="1000000" step="0.001" value="${esc(i.quantity??'')}"></label><label>Egység<input data-item="unit" required maxlength="30" value="${esc(i.unit||'db')}"></label><label>Egységtömeg (kg)<input data-item="unit_kg" type="number" min="0" max="1000000" step="0.001" value="${esc(i.unit_kg??'')}"></label><button type="button" class="secondary" aria-label="Tétel eltávolítása" onclick="logRemoveItem(${n})">×</button></div>`).join('')||'<p class="log-help">Még nincs felvitt tartalmi tétel.</p>';}
  window.logAddItem=()=>{logReadItems();if(logDraft.length>=1000)return notify('Legfeljebb 1000 tartalmi tétel rögzíthető.');logDraft.push({name:'',quantity:1,unit:'db',unit_kg:0});logRenderItemEditor();};
  window.logRemoveItem=i=>{logReadItems();logDraft.splice(i,1);logRenderItemEditor();};
  window.logSaveAsset=async function(event,id){event.preventDefault();const form=event.currentTarget,f=new FormData(form),value=k=>String(f.get(k)||'').trim(),old=logistics.assets.find(x=>x.id===id);logReadItems();const payload={kind:old?.kind||value('kind'),code:value('code'),name:value('name'),category:value('category'),length_cm:logNullable(value('length_cm')),width_cm:logNullable(value('width_cm')),height_cm:logNullable(value('height_cm')),stack_limit:Number(value('stack_limit')||1),max_top_load_kg:logNullable(value('max_top_load_kg')),tare_kg:logNullable(value('tare_kg')),measured_kg:logNullable(value('measured_kg')),contents:logDraft,condition:value('condition'),notes:value('notes')};if(!id)payload.location_id=value('location_id');await logRun(form,async()=>{const query=id?sb.from('logistics_assets').update(payload).eq('id',id).eq('version',old.version):sb.from('logistics_assets').insert(payload);const {data,error}=await query.select('id').maybeSingle();if(error)throw error;if(!data)throw new Error('A készlet időközben megváltozott. Frissítsd a nézetet.');},'A készlet és az adatok mentve.');};
  window.logMarkReviewed=async id=>{const a=logistics.assets.find(x=>x.id===id);if(!a||!confirm('A láda teljes tartalmát ellenőrizted, és egyezik a rögzített készlettel?'))return;await logRun(null,async()=>{const {data,error}=await sb.from('logistics_assets').update({reviewed_at:new Date().toISOString(),source_metadata:{...a.source_metadata,physical_review_pending:false}}).eq('id',id).eq('version',a.version).select('id').maybeSingle();if(error)throw error;if(!data)throw new Error('A készlet időközben megváltozott.');},'A féléves készletellenőrzés rögzítve.');};
  window.logArchiveAsset=async id=>{const a=logistics.assets.find(x=>x.id===id);if(!a||!confirm(a.active?'Archiválod az eszközt? Készlete és előzményei megmaradnak.':'Visszaállítod az eszközt az utolsó helyére?'))return;await logRun(null,async()=>{const {data,error}=await sb.from('logistics_assets').update({active:!a.active}).eq('id',id).eq('version',a.version).select('id').maybeSingle();if(error)throw error;if(!data)throw new Error('A készlet időközben megváltozott.');},a.active?'Az eszköz archiválva.':'Az eszköz visszaállítva.');};
  window.logMoveDialog=function(id=null){if(!canManageLogistics())return;const ids=id?[id]:[...logSelected],assets=logistics.assets.filter(a=>ids.includes(a.id)&&a.active);if(!assets.length)return notify('Válassz legalább egy aktív ládát vagy eszközt.');if(assets.length>200)return notify('Egyszerre legfeljebb 200 egységet mozgass.');const from=assets[0].location_id;if(assets.some(a=>a.location_id!==from))return notify('Egyszerre azonos helyen lévő eszközöket válassz.');logModal('Átrakodás / áthelyezés',`<form id="logMoveForm" onsubmit="logSaveMove(event)"><p><b>Honnan:</b> ${esc(logPath(from))}</p><ul class="log-move-list">${assets.map(a=>`<li>${esc(a.code)} · ${esc(a.name)} <b>${logNumber(a.total_kg)} kg</b></li>`).join('')}</ul><p><b>${assets.length} egység · ${logWeightSummary(assets)} rakomány</b></p><label class="log-field">Célhely / céljármű<select name="destination" required onchange="logMovePreview()"><option value="">Válassz célhelyet…</option>${logPlaceOptions(null,{exclude:from})}</select></label><div id="logMovePreview" class="log-help"></div><label class="log-field">Átadás, átvevő, művelet vagy megjegyzés<textarea name="note" rows="3" maxlength="2000"></textarea></label><p class="log-help">A teljes láda a tartalmával együtt kerül át. A mozgatást a napló rögzíti. A rendszer friss készletverziót és kapacitást ellenőriz.</p><div class="log-buttons"><button class="pill-btn" type="submit">Átrakodás rögzítése</button><span role="status"></span></div></form>`);document.querySelector('#logMoveForm').logMoveData={from,assets:assets.map(a=>({id:a.id,version:a.version,total_kg:a.total_kg}))};};
  window.logMovePreview=()=>{const form=document.querySelector('#logMoveForm'),l=logLoc(form?.elements.destination.value),el=document.querySelector('#logMovePreview');if(!el)return;if(!l||l.kind!=='vehicle'){el.textContent='';return;}const unknown=[...logAssets(l.id),...form.logMoveData.assets].some(a=>a.total_kg===null);if(unknown){el.innerHTML='<p class="log-warning">Ismeretlen tömegű egység van a rakományban. Járműre rakodás előtt a teljes tömeget rögzíteni kell.</p>';return;}const current=logAssets(l.id).reduce((n,a)=>n+Number(a.total_kg),0)+Number(l.people_weight_kg),incoming=form.logMoveData.assets.reduce((n,a)=>n+Number(a.total_kg),0),total=current+incoming;el.innerHTML=`<p>Átrakodás utáni terhelés: <b>${logNumber(total)} kg</b>${l.payload_kg!==null?' / '+logNumber(l.payload_kg)+' kg teherbírás':''}.</p>${l.payload_kg!==null&&total>Number(l.payload_kg)?'<p class="log-warning">Túllépné a teherbírást; a rendszer nem engedi a mozgatást.</p>':''}${l.payload_kg===null?'<p class="log-warning">A céljármű teherbírása még nincs megadva.</p>':''}`;};
  window.logSaveMove=async function(event){event.preventDefault();const form=event.currentTarget,f=new FormData(form),move=form.logMoveData;await logRun(form,async()=>{const {error}=await sb.rpc('hunor_logistics_move',{p_assets:move.assets.map(a=>a.id),p_from:move.from,p_to:f.get('destination'),p_versions:Object.fromEntries(move.assets.map(a=>[a.id,a.version])),p_note:f.get('note')});if(error)throw error;logLocation=f.get('destination');const dest=logLoc(logLocation);logView=['vehicle','site'].includes(dest?.kind)?'transport':'warehouse';},'Az átrakodás rögzítve.');};
  function logArchivedLocations(){if(!canManageLogistics()||!['warehouse','transport'].includes(logView))return '';const kinds=logView==='warehouse'?['rack','bin']:['vehicle','site'];const rows=logistics.locations.filter(l=>!l.active&&kinds.includes(l.kind));return rows.length?`<details class="panel"><summary>Archivált helyek (${rows.length})</summary>${rows.map(l=>`<p class="log-buttons"><span>${esc(logPath(l.id))}</span><button class="secondary" onclick="logRestoreLocation('${l.id}')">Visszaállítás</button></p>`).join('')}</details>`:'';}
  window.logRestoreLocation=async id=>{await logRun(null,async()=>{const {data,error}=await sb.from('logistics_locations').update({active:true}).eq('id',id).eq('updated_at',logLoc(id).updated_at).select('id').maybeSingle();if(error)throw error;if(!data)throw new Error('A hely adatai időközben megváltoztak.');logLocation=id;},'A hely visszaállítva.');};
  window.logExportManifest=()=>{const place=logView==='assets'?null:logLoc(logLocation),rows=logistics.assets.filter(a=>a.active&&(!place||a.location_id===place.id)),cell=v=>{let text=String(v??'');if(/^[\s]*[=+@-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};const csv=[['HUNOR készlet / rakodási lista',place?logPath(place.id):'Teljes készlet',new Date().toLocaleString('hu-HU')]];if(place?.kind==='vehicle'){csv.push(['Jármű',place.registration,logVehicleTypes[place.vehicle_type]],['Sofőr / felelős',place.driver_id?logPerson(place.driver_id):'Nincs megadva'],['Utasok, sofőrrel együtt',place.passenger_ids.map(logPerson).join(', ')],['Teherbírás kg',place.payload_kg],['Utasok és csomagok tömege kg',place.people_weight_kg]);}csv.push([],['Azonosító','Elnevezés','Kategória','Hely','Hossz cm','Szélesség cm','Magasság cm','Üres / saját tömeg kg','Teljes tömeg kg','Állapot','Tartalmi tétel','Mennyiség','Egység','Egységtömeg kg','Angol megnevezés','Gyártó','Gyári szám','Megjegyzés','Hiány','Forráslap','Forrássor']);for(const a of rows){for(const item of a.contents.length?a.contents:[{}])csv.push([a.code,a.name,logCategories[a.category],logPath(a.location_id),a.length_cm,a.width_cm,a.height_cm,a.tare_kg,a.total_kg,logConditions[a.condition],item.name,item.quantity,item.unit,item.unit_kg,item.english_name,item.manufacturer,item.serial_number,item.notes,item.deficit,item.source_sheet,item.source_row]);}const blob=new Blob(['\ufeff'+csv.map(row=>row.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='HUNOR_rakodasi_lista_'+new Date().toISOString().slice(0,10)+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};

    const NEWS_BUCKET='hunor-news';
  const newsCategories={earthquake:'Földrengés',weather:'Időjárás',deployment:'Műveleti esemény',training:'Felkészülés',other:'Egyéb hír'};
  const newsMimeTypes=['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','video/quicktime'];
  let newsPosts=[],newsTotal=0,newsLimit=3,newsError='',newsLoading=null,newsBusy=false,newsShowHidden=false,newsTimer=null;
  let newsDraftMedia=[],newsDraftLinks=[];
  const canEditNews=()=>Boolean(user?.membershipStatus==='approved'&&(user.isAdmin||user.canEditNews));
  function newsSafeUrl(value){try{const u=new URL(String(value||'').trim());return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return '';}}
  function newsMapUrl(query,embed=false){const q=String(query||'').trim();return q?'https://maps.google.com/maps?q='+encodeURIComponent(q)+(embed?'&z=7&output=embed':''):'';}
  async function loadNews(){
    if(newsLoading)return newsLoading;
    const actor=user?.id;
    if(!actor||guest||user.membershipStatus!=='approved'){newsPosts=[];newsError='';return;}
    newsLoading=(async()=>{
      try{
        const {data:permission,error:permissionError}=await sb.from('member_roles').select('can_edit_news').eq('member_id',actor).single();
        if(permissionError)throw permissionError;
        if(user?.id!==actor||guest)return;
        user.canEditNews=Boolean(permission.can_edit_news);if(!canEditNews())newsShowHidden=false;
        let query=sb.from('news_posts').select('*',{count:'exact'}).order('created_at',{ascending:false}).order('id',{ascending:false}).range(0,newsLimit-1);
        if(!newsShowHidden)query=query.eq('active',true);
        const {data,error,count}=await query;if(error)throw error;
        const paths=[...new Set((data||[]).flatMap(p=>(p.media||[]).map(m=>m.path)))];
        let urls=new Map(),failedPaths=new Set();
        if(paths.length){try{urls=await pfSignedUrls(NEWS_BUCKET,paths);for(const path of paths)if(!urls.has(path))failedPaths.add(path);}catch{paths.forEach(p=>failedPaths.add(p));}}
        if(user?.id!==actor||guest||user.membershipStatus!=='approved')return;
        newsPosts=(data||[]).map(post=>({...post,media:(post.media||[]).map(m=>({...m,url:urls.get(m.path)||'',unavailable:failedPaths.has(m.path)}))}));
        newsTotal=count??newsPosts.length;newsError='';
      }catch(error){console.error('A hírfolyam nem tölthető be.',error);if(user?.id===actor){newsPosts=[];newsError='A hírfolyam most nem tölthető be. Próbáld újra.';}}
    })().finally(()=>{newsLoading=null;});
    return newsLoading;
  }
  window.newsFeedSection=function(){return `<section class="news-section" aria-label="Hírfolyam"><div class="news-section-head"><div><div class="eyebrow">HUNOR · HÍREK ÉS ESEMÉNYEK</div><h2>Hírfolyam</h2><p>Friss információk a csapatnak.</p></div><div class="news-tools">${canEditNews()?`<button type="button" class="pill-btn" onclick="openNewsEditor()">＋ Új bejegyzés</button><label class="news-hidden-switch"><input type="checkbox" ${newsShowHidden?'checked':''} onchange="newsToggleHidden(this.checked)"> Rejtett hírek is</label>`:''}<button class="secondary" type="button" onclick="refreshNewsFeed()" aria-label="Hírfolyam frissítése">↻ Frissítés</button></div></div><div id="newsFeedContent">${newsFeedBody()}</div></section>`;};
  function newsFeedBody(){return newsError?`<div class="news-empty" role="status">${esc(newsError)} <button class="text-btn" onclick="refreshNewsFeed()">Újrapróbálás →</button></div>`:newsPosts.length?`${newsPosts.map(newsCard).join('')}${newsTotal>newsPosts.length?`<button class="secondary news-load-more" onclick="newsLoadMore()">További hírek (${newsTotal-newsPosts.length}) ↓</button>`:''}`:`<div class="news-empty">Még nincs közzétett hír.${canEditNews()?' Az Új bejegyzés gombbal teheted közzé az elsőt.':''}</div>`;}
  function nfParagraphs(text){return String(text||'').trim().split(/\n\s*\n/).filter(Boolean).map(p=>`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('');}
  function nfCopy(text){const value=String(text||'').trim();if(!value)return '';if(value.length<=700)return `<div class="nf-prose">${nfParagraphs(value)}</div>`;const cut=value.lastIndexOf(' ',650),preview=value.slice(0,cut>400?cut:650);return `<div class="nf-copy-expand"><div class="nf-preview nf-prose">${nfParagraphs(preview+'…')}</div><details class="nf-details"><summary><span class="nf-read-open">Teljes beszámoló elolvasása</span><span class="nf-read-close">Beszámoló összecsukása</span><span aria-hidden="true">↓</span></summary><div class="nf-prose nf-full-copy">${nfParagraphs(value)}</div></details></div>`;}
  function newsCard(post){
    const icons={earthquake:'◉',weather:'☁',deployment:'⚑',training:'◎',other:'▤'},category=newsCategories[post.category]||'Hír',author=post.author_name||'Csapattag',date=new Date(post.created_at),edited=post.version>1;
    const links=(post.links||[]).filter(l=>newsSafeUrl(l.url)),hasMedia=Boolean(post.media?.length);
    return `<article class="news-card nf-card nf-${esc(post.category||'other')} ${!post.active?'news-card-hidden':''}"><header class="nf-header"><div class="nf-kicker"><span class="nf-category"><span aria-hidden="true">${icons[post.category]||'▤'}</span>${esc(category)}</span>${!post.active?'<span class="nf-hidden">Rejtett bejegyzés</span>':''}${hasMedia?`<span class="nf-attachment-count">${post.media.length} csatolmány</span>`:''}</div><div class="nf-title-row"><h3>${esc(post.title)}</h3>${canEditNews()?`<button type="button" class="secondary nf-edit" onclick="openNewsEditor('${post.id}')"><span aria-hidden="true">✎</span> Szerkesztés</button>`:''}</div><div class="nf-byline"><span class="nf-avatar" aria-hidden="true">${esc(initials(author))}</span><div><b>${esc(author)}</b><div class="nf-dateline"><time datetime="${esc(post.created_at)}">${esc(date.toLocaleString('hu-HU',{timeZone:'Europe/Budapest',year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'}))}</time>${edited?`<span class="nf-edited"> · Szerkesztve ${esc(new Date(post.updated_at).toLocaleString('hu-HU',{timeZone:'Europe/Budapest',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}))} · ${esc(post.editor_name)}</span>`:''}</div></div></div></header><div class="nf-story ${hasMedia&&post.body?'nf-story-split':''}">${post.body?`<div class="nf-copy">${nfCopy(post.body)}</div>`:''}${hasMedia?`<div class="nf-visual"><div class="news-media-grid nf-gallery ${post.media.length===1?'nf-gallery-single':''}">${post.media.map(newsMediaCard).join('')}</div>${post.media.some(m=>m.kind==='image')?'<div class="nf-visual-note">Kép megnyitása teljes méretben a képre kattintva.</div>':''}</div>`:''}</div>${links.length?`<section class="nf-resources"><h4>Hivatkozások és források</h4><div class="news-links nf-links">${links.map(l=>`<a href="${esc(newsSafeUrl(l.url))}" target="_blank" rel="noopener noreferrer"><span class="nf-link-symbol" aria-hidden="true">↗</span><span><b>${esc(l.label||new URL(l.url).hostname)}</b><small>${esc(new URL(l.url).hostname)}</small></span><span class="nf-link-arrow" aria-hidden="true">↗</span></a>`).join('')}</div></section>`:''}${post.map_query?`<section class="news-map nf-location"><div><div><small>AZ ESEMÉNY HELYSZÍNE</small><b>⌖ ${esc(post.map_query)}</b></div><a href="${esc(newsMapUrl(post.map_query))}" target="_blank" rel="noopener noreferrer">Megnyitás térképen ↗</a></div><iframe title="${esc(post.title+' – térkép')}" src="${esc(newsMapUrl(post.map_query,true))}" loading="lazy" decoding="async" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe></section>`:''}</article>`;
  }

  function newsMediaCard(media){return `<figure class="news-media ${media.kind==='video'?'news-video':''}">${media.url?(media.kind==='image'?`<a href="${esc(media.url)}" target="_blank" rel="noopener noreferrer"><img src="${esc(media.url)}" alt="${esc(media.caption||media.name)}" loading="lazy" decoding="async"></a>`:`<video controls playsinline preload="none" src="${esc(media.url)}" aria-label="${esc(media.caption||media.name)}"></video><a class="news-media-open" href="${esc(media.url)}" target="_blank" rel="noopener noreferrer">Videó megnyitása / letöltése ↗</a>`):'<div class="news-media-unavailable">A csatolmány nem tölthető be. Frissítsd a hírfolyamot.</div>'}${media.caption?`<figcaption>${esc(media.caption)}</figcaption>`:''}</figure>`;}
  function renderNewsFeed(){const el=document.querySelector('#newsFeedContent');if(page==='home'&&el)el.innerHTML=newsFeedBody();}
  window.refreshNewsFeed=async()=>{if(newsBusy)return;await loadNews();if(page==='home'){const section=document.querySelector('.news-section');if(section)section.outerHTML=window.newsFeedSection();}};
  window.newsLoadMore=async()=>{newsLimit+=3;await window.refreshNewsFeed();};
  window.newsToggleHidden=async value=>{newsShowHidden=Boolean(value)&&canEditNews();newsLimit=3;await window.refreshNewsFeed();};
  function syncNewsPolling(){if(newsTimer){clearInterval(newsTimer);newsTimer=null;}if(page==='home'&&user?.membershipStatus==='approved'&&!guest)newsTimer=setInterval(async()=>{if(page==='home'&&document.visibilityState==='visible'&&!newsBusy&&!document.querySelector('#overlay.show')){await loadNews();renderNewsFeed();}},60000);}
  function newsReleaseDraft(){for(const m of newsDraftMedia)if(m.previewUrl)URL.revokeObjectURL(m.previewUrl);newsDraftMedia=[];newsDraftLinks=[];}
  const originalNewsCloseModal=window.closeModal;
  window.closeModal=function(){if(document.querySelector('#newsEditorForm')){if(newsBusy)return notify('A feltöltés és mentés folyamatban van. Kérjük, várj.');newsReleaseDraft();}originalNewsCloseModal();};
  window.openNewsEditor=function(id=null){if(!canEditNews())return notify('Hírfolyam-szerkesztő jogosultság szükséges.');if(newsBusy)return;newsReleaseDraft();const post=newsPosts.find(p=>p.id===id)||{id:crypto.randomUUID(),title:'',body:'',category:'other',links:[],media:[],map_query:'',active:true};newsDraftMedia=post.media.map(m=>({...m}));newsDraftLinks=(post.links||[]).map(l=>({...l}));openModal(`<div class="news-editor"><div class="panel-head"><h2>${id?'Hír szerkesztése':'Új hír a csapatnak'}</h2><button type="button" class="secondary" onclick="closeModal()" aria-label="Bezárás">×</button></div><form id="newsEditorForm" onsubmit="saveNewsPost(event)"><label class="news-field">Cím<input name="title" required maxlength="160" value="${esc(post.title)}" placeholder="Pl. Földrengés – friss helyzetjelentés"></label><label class="news-field">Esemény típusa<select name="category">${Object.entries(newsCategories).map(([key,label])=>`<option value="${key}" ${post.category===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="news-field">Szöveges tájékoztató<textarea name="body" rows="8" maxlength="20000" placeholder="Írd le a történteket, a forrást és a csapat számára fontos tudnivalókat…">${esc(post.body)}</textarea></label><section class="news-editor-section"><h3>Képek és videók</h3><p class="news-help">Legfeljebb 12 csatolmány. Kép: JPG, PNG, WebP, GIF, maximum 10 MB. Videó: MP4, WebM, MOV, maximum 50 MB. A MOV lejátszása a böngészőtől függ.</p><label class="secondary news-file-picker">＋ Képek / videók kiválasztása<input type="file" multiple accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,video/quicktime,.mov" onchange="newsAddFiles(this)"></label><div id="newsDraftMedia"></div></section><section class="news-editor-section"><h3>Hivatkozások</h3><div id="newsDraftLinks"></div><button type="button" class="secondary" onclick="newsAddLink()">＋ Hivatkozás</button></section><section class="news-editor-section"><h3>Térkép</h3><label class="news-field">Helynév, cím vagy szélesség, hosszúság<input name="map_query" maxlength="500" value="${esc(post.map_query)}" placeholder="Pl. Budapest vagy 47.4979, 19.0402"></label><button type="button" class="secondary" onclick="newsMapPreview()">Térkép előnézete</button><div id="newsMapPreview"></div><p class="news-help">A térkép a megadott helyet mutatja. Külső eseménytérképhez vagy helyzetjelentéshez a Hivatkozások részt használd.</p></section><div class="news-editor-actions"><button type="submit" class="pill-btn">${id?'Módosítások mentése':'Hír közzététele'}</button>${id?`<button type="button" class="secondary" onclick="newsSetActive('${post.id}',${!post.active})">${post.active?'Elrejtés':'Újra közzéteszem'}</button>`:''}<span id="newsSaveStatus" role="status"></span></div></form></div>`);document.querySelector('#newsEditorForm').newsRecord={id:post.id,version:id?post.version:null,active:post.active};newsRenderDraftMedia();newsRenderDraftLinks();};
  function newsReadCaptions(){document.querySelectorAll('[data-news-caption]').forEach(el=>{const m=newsDraftMedia[Number(el.dataset.newsCaption)];if(m)m.caption=el.value;});}
  function newsRenderDraftMedia(){const el=document.querySelector('#newsDraftMedia');if(!el)return;el.innerHTML=newsDraftMedia.length?`<div class="news-draft-grid">${newsDraftMedia.map((m,i)=>`<div class="news-draft-item">${m.previewUrl||m.url?(m.kind==='image'?`<img src="${esc(m.previewUrl||m.url)}" alt="${esc(m.name)}">`:`<video controls preload="metadata" playsinline src="${esc(m.previewUrl||m.url)}"></video>`):'<div class="news-help">A csatolmány előnézete nem érhető el.</div>'}<b>${esc(m.name)}</b><small>${m.file?'Feltöltésre vár · ':''}${(Number(m.size||m.file?.size||0)/1024/1024).toFixed(1)} MB</small><label class="news-field">Képaláírás / videó leírása<input data-news-caption="${i}" maxlength="500" value="${esc(m.caption||'')}"></label><button type="button" class="secondary" onclick="newsRemoveMedia(${i})">Eltávolítás</button></div>`).join('')}</div>`:'<p class="news-help">Még nincs csatolmány.</p>';}
  window.newsAddFiles=function(input){if(newsBusy)return;const files=Array.from(input.files||[]);if(files.length+newsDraftMedia.length>12){input.value='';return notify('Legfeljebb 12 kép vagy videó csatolható.');}for(const file of files){if(!newsMimeTypes.includes(file.type)||file.size<=0||file.size>(file.type.startsWith('image/')?10:50)*1024*1024){input.value='';return notify('Nem támogatott vagy túl nagy fájl. Kép: maximum 10 MB; videó: maximum 50 MB.');}}newsReadCaptions();for(const file of files)newsDraftMedia.push({file,name:file.name.slice(0,160),kind:file.type.startsWith('image/')?'image':'video',mime:file.type,size:file.size,caption:'',previewUrl:URL.createObjectURL(file)});input.value='';newsRenderDraftMedia();};
  window.newsRemoveMedia=i=>{if(newsBusy)return;newsReadCaptions();const [m]=newsDraftMedia.splice(i,1);if(m?.previewUrl)URL.revokeObjectURL(m.previewUrl);newsRenderDraftMedia();};
  function newsReadLinks(){newsDraftLinks=Array.from(document.querySelectorAll('.news-link-row')).map(row=>({label:row.querySelector('[data-news-link-label]').value.trim(),url:row.querySelector('[data-news-link-url]').value.trim()}));}
  function newsRenderDraftLinks(){const el=document.querySelector('#newsDraftLinks');if(el)el.innerHTML=newsDraftLinks.map((l,i)=>`<div class="news-link-row"><label class="news-field">Megnevezés<input data-news-link-label maxlength="160" value="${esc(l.label)}" placeholder="Pl. hivatalos helyzetjelentés"></label><label class="news-field">Webcím<input data-news-link-url type="url" required maxlength="2000" value="${esc(l.url)}" placeholder="https://…"></label><button type="button" class="secondary" onclick="newsRemoveLink(${i})" aria-label="Hivatkozás eltávolítása">×</button></div>`).join('')||'<p class="news-help">Még nincs hivatkozás.</p>';}
  window.newsAddLink=()=>{if(newsBusy)return;newsReadLinks();if(newsDraftLinks.length>=10)return notify('Legfeljebb 10 hivatkozás adható meg.');newsDraftLinks.push({label:'',url:''});newsRenderDraftLinks();};
  window.newsRemoveLink=i=>{if(newsBusy)return;newsReadLinks();newsDraftLinks.splice(i,1);newsRenderDraftLinks();};
  window.newsMapPreview=()=>{const query=document.querySelector('#newsEditorForm')?.elements.map_query.value.trim(),el=document.querySelector('#newsMapPreview');if(el)el.innerHTML=query?`<iframe title="Térkép előnézete" src="${esc(newsMapUrl(query,true))}" loading="lazy" decoding="async" referrerpolicy="no-referrer-when-downgrade"></iframe>`:'';};
  window.saveNewsPost=async function(event){
    event.preventDefault();if(newsBusy||!canEditNews())return;
    const form=event.target,record=form.newsRecord,actor=user.id,values=new FormData(form);newsReadCaptions();newsReadLinks();
    const links=newsDraftLinks.map(l=>({label:l.label,url:newsSafeUrl(l.url)}));if(links.some(l=>!l.url))return notify('Adj meg érvényes http vagy https webcímet.');
    const title=String(values.get('title')||'').trim();if(!title)return notify('A hír címe kötelező.');
    const original=newsPosts.find(p=>p.id===record.id),uploaded=[];let saved=false;
    const status=form.querySelector('[role="status"]')||form.querySelector('#newsSaveStatus');
    const message=t=>{if(status)status.textContent=t;};
    newsBusy=true;form.querySelectorAll('input,textarea,select,button').forEach(el=>el.disabled=true);
    try{
      const media=[];
      for(let i=0;i<newsDraftMedia.length;i++){
        const item=newsDraftMedia[i];if(user?.id!==actor)throw new Error('A bejelentkezés megváltozott.');
        let path=item.path;
        if(item.file){path=await uploadEducationFile(item.file,pct=>message(`Csatolmány feltöltése: ${i+1}/${newsDraftMedia.length} · ${pct}%`),NEWS_BUCKET,record.id);uploaded.push(path);}
        media.push({path,name:item.name,caption:item.caption||''});
      }
      if(user?.id!==actor)throw new Error('A bejelentkezés megváltozott.');message('Hír mentése…');
      const payload={title,body:String(values.get('body')||'').trim(),category:String(values.get('category')||'other'),links,map_query:String(values.get('map_query')||'').trim(),media,active:record.active};
      const query=record.version?sb.from('news_posts').update(payload).eq('id',record.id).eq('version',record.version):sb.from('news_posts').insert({...payload,id:record.id,author_id:actor});
      const {data,error}=await query.select('id,version').maybeSingle();if(error)throw error;if(!data)throw new Error('A hírt közben módosították. Nyisd meg újra a friss változatot.');saved=true;
      const removed=(original?.media||[]).map(m=>m.path).filter(p=>!media.some(m=>m.path===p));
      if(removed.length){const cleanup=await sb.storage.from(NEWS_BUCKET).remove(removed);if(cleanup.error)console.error('Régi hír-csatolmányok takarítása',cleanup.error);}
      newsBusy=false;closeModal();await window.refreshNewsFeed();notify(record.version?'Hír módosítva.':'Hír közzétéve.');
    }catch(error){
      if(uploaded.length&&!saved){const check=await sb.from('news_posts').select('media').eq('id',record.id).maybeSingle();if(!check.error){const referenced=(check.data?.media||[]).map(m=>m.path),unused=uploaded.filter(p=>!referenced.includes(p));if(unused.length)await sb.storage.from(NEWS_BUCKET).remove(unused);}}
      console.error('Hír mentése',error);message(error.message||'A mentés nem sikerült. Próbáld újra.');notify('A hír mentése nem sikerült.');
    }finally{newsBusy=false;if(form.isConnected)form.querySelectorAll('input,textarea,select,button').forEach(el=>el.disabled=false);}
  };
  window.newsSetActive=async function(id,active){
    if(newsBusy||!canEditNews())return;const post=newsPosts.find(p=>p.id===id);if(!post)return;
    if(!confirm(active?'Újra megjelenjen a hír a csapatnak?':'Elrejted a hírt? A szerkesztőben lévő nem mentett módosítások elvesznek.'))return;
    newsBusy=true;
    try{const {data,error}=await sb.from('news_posts').update({active}).eq('id',id).eq('version',post.version).select('id').maybeSingle();if(error)throw error;if(!data)throw new Error('A hírt közben módosították. Nyisd meg újra.');newsBusy=false;closeModal();await window.refreshNewsFeed();notify(active?'A hír ismét látható.':'A hír elrejtve.');}
    catch(error){tellError(error,'A hír állapota nem módosítható.');}finally{newsBusy=false;}
  };
  function resetNews(){if(newsTimer)clearInterval(newsTimer);newsTimer=null;newsPosts=[];newsTotal=0;newsError='';newsShowHidden=false;newsLimit=3;}

    let personalProfileTab='general';
  const privateProfileFields=['next_of_kin_name','next_of_kin_relationship','next_of_kin_phone','next_of_kin_email','supervisor_name','supervisor_position','supervisor_phone','supervisor_email','birth_place','birth_date','home_address','mothers_name','social_security_number','licence_categories','spoken_languages','language_level','membership_generation','team_component','team_task','duty_position','county','additional_qualifications','tax_identifier','service_passport_expires_on','civilian_passport_expires_on','identity_card_expires_on','driving_licence_expires_on','gender','height_cm','blood_group','service_passport_number','civilian_passport_number','known_conditions','drug_allergies','wears_glasses','regular_medication','shoe_size','tshirt_size','trouser_size','jacket_size','hat_size'];
  function personalSelect(name,label,options,value){return `<div class="field"><label for="private_${name}">${label}</label><select id="private_${name}" name="${name}"><option value="">Nincs megadva</option>${options.map(([v,t])=>`<option value="${esc(v)}" ${String(value??'')===v?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;}
  function personalInput(name,label,value,type='text',extra=''){return `<div class="field"><label for="private_${name}">${label}</label><input id="private_${name}" name="${name}" type="${type}" value="${esc(value??'')}" ${extra}></div>`;}
  function personalTextarea(name,label,value,hint){return `<div class="field private-wide"><label for="private_${name}">${label}</label><textarea id="private_${name}" name="${name}" rows="4" maxlength="4000" placeholder="${esc(hint)}">${esc(value||'')}</textarea></div>`;}
  function personalGeneralFields(p){return personalSelect('gender','Neme',[['male','Férfi'],['female','Nő']],p.gender)+personalInput('height_cm','Magasság (cm)',p.height_cm,'number','min="50" max="250" step="0.1" inputmode="decimal"');}
  function personalProfileTabs(){return `<div class="personal-profile-tabs" role="tablist" aria-label="Profil adatkategóriái">${[['general','Általános adatok'],['contacts','Kapcsolattartók'],['registry','Nyilvántartás'],['health','Egészségügyi adatok'],['documents','Iratok'],['vaccinations','Oltási könyv'],['sizes','Személyes méretek'],['k9','K9 · Kutyák']].map(([k,v])=>`<button type="button" role="tab" id="personal-tab-${k}" aria-controls="personal-panel-${k}" aria-selected="${personalProfileTab===k}" tabindex="${personalProfileTab===k?'0':'-1'}" onclick="setPersonalProfileTab('${k}')" onkeydown="personalProfileTabKey(event,'${k}')">${v}</button>`).join('')}</div>`;}
  function basePersonalExtraPanels(p){return `</div><div id="personal-panel-health" class="personal-profile-panel" role="tabpanel" aria-labelledby="personal-tab-health" ${personalProfileTab!=='health'?'hidden':''}><h2>Egészségügyi adatok</h2><p class="profile-help private-access-note">Ezeket az adatokat csak te, az adminisztrátor és a tagságkezelő láthatja. Ha nincs ismert betegséged vagy gyógyszerérzékenységed, ezt is írd be; az üres mező azt jelenti, hogy nincs megadva.</p><div class="profile-fields">${personalSelect('blood_group','Vércsoport',['A+','A-','B+','B-','AB+','AB-','0+','0-'].map(v=>[v,v]),p.blood_group)}${personalSelect('wears_glasses','Szemüveges-e?',[['true','Igen'],['false','Nem']],p.wears_glasses)}${personalTextarea('known_conditions','Ismert betegségek',p.known_conditions,'Pl. nincs ismert betegség, vagy a betegségek felsorolása')}${personalTextarea('drug_allergies','Gyógyszerérzékenység',p.drug_allergies,'Pl. nincs ismert gyógyszerérzékenység, vagy az érintett hatóanyagok')}${personalTextarea('regular_medication','Rendszeresen szedett gyógyszerek',p.regular_medication,'Pl. nem szedek rendszeresen gyógyszert, vagy név, adag és gyakoriság')}</div></div><div id="personal-panel-documents" class="personal-profile-panel" role="tabpanel" aria-labelledby="personal-tab-documents" ${personalProfileTab!=='documents'?'hidden':''}><h2>Iratok</h2><p class="profile-help private-access-note">Az iratadatokat csak te, az adminisztrátor és a tagságkezelő láthatja.</p><div class="profile-fields">${personalInput('service_passport_number','Szolgálati útlevél száma',p.service_passport_number,'text','maxlength="50" autocomplete="off" spellcheck="false"')}${personalInput('service_passport_expires_on','Szolgálati útlevél lejárata',p.service_passport_expires_on,'date')}${personalInput('civilian_passport_number','Magánútlevél száma',p.civilian_passport_number,'text','maxlength="50" autocomplete="off" spellcheck="false"')}${personalInput('civilian_passport_expires_on','Magánútlevél lejárata',p.civilian_passport_expires_on,'date')}${personalInput('driving_licence_number','Jogosítvány száma',p.driving_licence_number,'text','maxlength="50" autocomplete="off" spellcheck="false"')}${personalInput('driving_licence_expires_on','Jogosítvány lejárata',p.driving_licence_expires_on,'date')}${personalInput('licence_categories','Jogosítvány-kategóriák',p.licence_categories,'text','maxlength="100" placeholder="Pl. B, C, D, E"')}${personalInput('identity_card_number','Személyi igazolvány száma',p.identity_card_number,'text','maxlength="50" autocomplete="off" spellcheck="false"')}${personalInput('identity_card_expires_on','Személyi igazolvány lejárata',p.identity_card_expires_on,'date')}${personalInput('tax_identifier','Adószám / adóazonosító jel',p.tax_identifier,'text','maxlength="40" autocomplete="off" spellcheck="false"')}</div></div><div id="personal-panel-sizes" class="personal-profile-panel" role="tabpanel" aria-labelledby="personal-tab-sizes" ${personalProfileTab!=='sizes'?'hidden':''}><h2>Személyes méretek</h2><p class="profile-help">A felszerelés és ruházat tervezéséhez. A betűs méret mellett számozott méretet is megadhatsz. Ezeket az adatokat te, az adminisztrátor és a tagságkezelő láthatja.</p><div class="profile-fields">${personalInput('shoe_size','Cipőméret (EU)',p.shoe_size,'number','min="15" max="60" step="0.5" inputmode="decimal"')}${['tshirt_size','trouser_size','jacket_size','hat_size'].map((k,i)=>personalInput(k,['Pólóméret','Nadrágméret','Kabátméret','Sapkaméret'][i],p[k],'text','maxlength="20" list="personalSizeSuggestions" placeholder="'+['Pl. L vagy 52','Pl. 52 vagy W34/L32','Pl. XL vagy 54','Pl. 58 cm vagy L'][i]+'"')).join('')}</div><datalist id="personalSizeSuggestions">${['XXS','XS','S','M','L','XL','XXL','3XL','4XL'].map(s=>`<option value="${s}">`).join('')}</datalist></div>`;}
  window.setPersonalProfileTab=function(key){if(!['general','contacts','registry','health','documents','vaccinations','sizes','k9'].includes(key))return;personalProfileTab=key;document.querySelectorAll('.personal-profile-tabs [role=tab]').forEach(el=>{const active=el.id==='personal-tab-'+key;el.setAttribute('aria-selected',String(active));el.tabIndex=active?0:-1;});document.querySelectorAll('.personal-profile-panel').forEach(el=>el.hidden=el.id!=='personal-panel-'+key);};
  window.personalProfileTabKey=function(event,key){const keys=['general','contacts','registry','health','documents','vaccinations','sizes','k9'];let i=keys.indexOf(key);if(event.key==='ArrowRight')i=(i+1)%keys.length;else if(event.key==='ArrowLeft')i=(i+keys.length-1)%keys.length;else if(event.key==='Home')i=0;else if(event.key==='End')i=keys.length-1;else return;event.preventDefault();setPersonalProfileTab(keys[i]);document.querySelector('#personal-tab-'+keys[i])?.focus();};
  document.addEventListener('invalid',event=>{if(event.target.closest?.('#myProfileForm')){const panel=event.target.closest('.personal-profile-panel');if(panel)setPersonalProfileTab(panel.id.replace('personal-panel-',''));}},true);
  window.openPrivateMemberDetails=async function(id){
    if(!user?.isAdmin&&!hpHas('membership_manager'))return notify('Ehhez tagságkezelői jogosultság szükséges.');
    const member=members.find(m=>m.id===id);if(!member)return;
    openModal(`<div class="private-member-details"><div class="modal-head"><h2>Védett profiladatok · ${esc(member.name)}</h2><button class="close" onclick="closeModal()" aria-label="Bezárás">×</button></div><div id="privateMemberDetailsBody" role="status">Betöltés…</div></div>`);
    const body=document.querySelector('#privateMemberDetailsBody');
    try{const {data:p,error}=await sb.from('member_private_details').select('*').eq('member_id',id).maybeSingle();if(error)throw error;if(!body.isConnected)return;if(!p){body.innerHTML=`<p>A tag még nem adott meg kiegészítő profiladatokat.</p><button class="pill-btn" onclick="editPrivateMemberDetails('${id}')">Védett adatok szerkesztése</button>`;return;}
      const val=v=>v===null||v===undefined||v===''?'Nincs megadva':String(v),row=(k,v)=>`<div><dt>${esc(k)}</dt><dd>${esc(val(v))}</dd></div>`,section=(title,rows)=>`<section><h3>${title}</h3><dl>${rows}</dl></section>`;
      body.innerHTML=`<p class="profile-help private-access-note">Csak az érintett tag, az adminisztrátor és a tagságkezelő számára látható. Az adatokat az érintett tag, az adminisztrátor és a tagságkezelő módosíthatja.</p>${section('Általános adatok',row('Neme',p.gender==='male'?'Férfi':p.gender==='female'?'Nő':null)+row('Magasság',p.height_cm===null?null:p.height_cm+' cm'))}${section('Egészségügyi adatok',row('Vércsoport',p.blood_group)+row('Ismert betegségek',p.known_conditions)+row('Gyógyszerérzékenység',p.drug_allergies)+row('Szemüveges-e?',p.wears_glasses===null?null:p.wears_glasses?'Igen':'Nem')+row('Rendszeresen szedett gyógyszerek',p.regular_medication))}${section('Iratok',row('Szolgálati útlevél száma',p.service_passport_number)+row('Szolgálati útlevél lejárata',deDate(p.service_passport_expires_on))+row('Magánútlevél száma',p.civilian_passport_number)+row('Magánútlevél lejárata',deDate(p.civilian_passport_expires_on))+row('Jogosítvány száma',p.driving_licence_number)+row('Jogosítvány lejárata',deDate(p.driving_licence_expires_on))+row('Jogosítvány-kategóriák',p.licence_categories)+row('Személyi igazolvány száma',p.identity_card_number)+row('Személyi igazolvány lejárata',deDate(p.identity_card_expires_on))+row('Adószám / adóazonosító jel',p.tax_identifier))}${section('Személyes méretek',row('Cipőméret (EU)',p.shoe_size)+row('Pólóméret',p.tshirt_size)+row('Nadrágméret',p.trouser_size)+row('Kabátméret',p.jacket_size)+row('Sapkaméret',p.hat_size))}${rcContactReadOnly(p,row,section)}${riReadOnly(p,row,section)}${mdVaccineReadOnly(p)}${k9ReadOnly(p,row,section)}<small>Utoljára mentve: ${esc(new Date(p.updated_at).toLocaleString('hu-HU'))}</small><div style="margin-top:18px"><button class="pill-btn" onclick="editPrivateMemberDetails('${id}')">Védett adatok szerkesztése</button></div>`;
    }catch(error){if(body.isConnected)body.textContent='A védett adatok nem tölthetők be. Ellenőrizd a jogosultságodat, majd próbáld újra.';notify('A védett adatok nem tölthetők be.');}
  };

