  function k9Cards(){return k9DogsDraft.map((dog,i)=>`<section class="k9-dog-card" data-k9-index="${i}"><div class="k9-dog-head"><h3>${i+1}. kutya${dog.name?' · '+esc(dog.name):''}</h3><button type="button" class="secondary" onclick="removeK9Dog(${i})">Eltávolítás</button></div><div class="profile-fields">${k9Input(i,'name','Kutya neve',dog.name,'text','maxlength="120"')}${k9Input(i,'breed','Fajta',dog.breed,'text','maxlength="120"')}<div class="field"><label for="k9_${i}_sex">Neme</label><select id="k9_${i}_sex" data-dog-field="sex"><option value="">Nincs megadva</option><option value="male" ${dog.sex==='male'?'selected':''}>Kan</option><option value="female" ${dog.sex==='female'?'selected':''}>Szuka</option></select></div>${k9Input(i,'birth_date','Születési dátum',dog.birth_date,'date','min="1900-01-01" max="'+new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Budapest'})+'"')}${k9Input(i,'passport_number','Kutya útlevelének száma',dog.passport_number,'text','maxlength="50" autocomplete="off" spellcheck="false"')}${k9Input(i,'chip_number','Mikrochip száma (15 számjegy)',dog.chip_number,'text','maxlength="15" inputmode="numeric" autocomplete="off" spellcheck="false"')}${k9Input(i,'specialisation','Szakterület / keresési feladat',dog.specialisation,'text','maxlength="200" placeholder="Pl. romkutatás, területkutatás"')}${k9Input(i,'qualification','Minősítés / vizsga',dog.qualification,'text','maxlength="200"')}${k9Input(i,'qualification_valid_until','Minősítés érvényessége',dog.qualification_valid_until,'date')}${k9Input(i,'vaccination_date','Utolsó veszettségoltás dátuma',dog.vaccination_date,'date')}${k9Input(i,'next_vaccination_date','Következő veszettségoltás esedékessége',dog.next_vaccination_date,'date')}<div class="field"><label for="k9_${i}_titer_test">Titer teszt</label><select id="k9_${i}_titer_test" data-dog-field="titer_test"><option value="" ${!dog.titer_test?'selected':''}>Nincs megadva</option><option value="yes" ${dog.titer_test==='yes'?'selected':''}>Van</option><option value="no" ${dog.titer_test==='no'?'selected':''}>Nincs</option></select></div><div class="field private-wide"><label for="k9_${i}_notes">Megjegyzés a kutyához</label><textarea id="k9_${i}_notes" data-dog-field="notes" rows="3" maxlength="2000" placeholder="Pl. egészségi tudnivalók, etetés vagy felszerelés…">${esc(dog.notes||'')}</textarea></div></div></section>`).join('')||'<p class="profile-help">Még nincs rögzített kutya. A hozzáadás gombbal készíthetsz adatlapot.</p>';}
  function k9Panel(p){return `<div id="personal-panel-k9" class="personal-profile-panel" role="tabpanel" aria-labelledby="personal-tab-k9" ${personalProfileTab!=='k9'?'hidden':''}><h2>K9 · Kutyák adatai</h2><p class="profile-help private-access-note">Ezeket az adatokat te, az adminisztrátor és a tagságkezelő láthatja.</p><label class="k9-handler-toggle"><input id="isK9Handler" type="checkbox" ${p.is_k9_handler?'checked':''} onchange="toggleK9Handler(this.checked)"> K9-es / kutyavezető vagyok</label><p class="profile-help">Kutyavezetőként legalább egy kutya nevét add meg. Több kutya is rögzíthető, külön adatlapon. A többi mezőt később is kitöltheted.</p><div id="k9DogEditor" ${p.is_k9_handler?'':'hidden'}><div id="k9DogCards">${k9Cards()}</div><button type="button" class="secondary" onclick="addK9Dog()">＋ Kutya hozzáadása</button></div><p id="k9InactiveNote" class="profile-help" ${p.is_k9_handler?'hidden':''}>A K9 jelölés bekapcsolásával megjelennek a kutyaadatlapok. A jelölés kikapcsolása önmagában nem törli a korábban megadott kutyaadatokat.</p></div>`;}
  function personalExtraPanels(p){return basePersonalExtraPanels(p)+rcContactPanel(p)+riRegistryPanel(p)+mdVaccinationPanel(p)+k9Panel(p);}
  function readK9Dogs(){const container=document.querySelector('#k9DogCards');if(!container)return;k9DogsDraft=Array.from(container.querySelectorAll('[data-k9-index]')).map(card=>Object.fromEntries(k9DogFields.map(key=>[key,card.querySelector('[data-dog-field="'+key+'"]')?.value.trim()||''])));}
  window.toggleK9Handler=function(enabled){if(profileSaving)return;document.querySelector('#k9DogEditor').hidden=!enabled;document.querySelector('#k9InactiveNote').hidden=enabled;if(enabled&&k9DogsDraft.length===0)window.addK9Dog();};
  window.addK9Dog=function(){if(profileSaving)return;readK9Dogs();if(k9DogsDraft.length>=10)return notify('Legfeljebb 10 kutyát adhatsz hozzá.');k9DogsDraft.push({});document.querySelector('#k9DogCards').innerHTML=k9Cards();document.querySelector('#k9_'+(k9DogsDraft.length-1)+'_name')?.focus();};
  window.removeK9Dog=function(i){if(profileSaving)return;if(!confirm('Eltávolítod ezt a kutyaadatlapot? A törlés a profil mentésekor véglegesedik.'))return;readK9Dogs();k9DogsDraft.splice(i,1);document.querySelector('#k9DogCards').innerHTML=k9Cards();};
  function collectK9ForSave(){readK9Dogs();const handler=Boolean(document.querySelector('#isK9Handler')?.checked),dogs=k9DogsDraft.filter(d=>k9DogFields.some(k=>d[k]));let message='';if(handler&&!dogs.length)message='K9-es tagként adj meg legalább egy kutyát.';const chips=new Set();for(const d of dogs){if(!d.name){message='Minden megkezdett kutyaadatlaphoz add meg a kutya nevét.';break;}if(d.chip_number&&!/^\d{15}$/.test(d.chip_number)){message='A mikrochip száma 15 számjegyből álljon.';break;}if(d.chip_number&&chips.has(d.chip_number)){message='Ugyanaz a chipszám két kutyánál szerepel.';break;}if(d.chip_number)chips.add(d.chip_number);if(d.vaccination_date&&d.next_vaccination_date&&d.next_vaccination_date<d.vaccination_date){message='A következő oltás dátuma nem előzheti meg az utolsó oltást.';break;}}if(message){setPersonalProfileTab('k9');notify(message);return null;}return {handler,dogs};}
  function k9ReadOnly(p,row,section){if(!p.is_k9_handler&&!p.k9_dogs?.length)return '';return section('K9 · Kutyák',row('Kutyavezető',p.is_k9_handler?'Igen':'Nem aktív K9-jelölés')+(p.k9_dogs||[]).map((d,i)=>`<div class="private-wide k9-readonly"><h4>${i+1}. ${esc(d.name)}</h4><dl>${row('Fajta',d.breed)}${row('Neme',d.sex==='male'?'Kan':d.sex==='female'?'Szuka':null)}${row('Születési dátum',d.birth_date)}${row('Útlevélszám',d.passport_number)}${row('Chipszám',d.chip_number)}${row('Szakterület',d.specialisation)}${row('Minősítés',d.qualification)}${row('Minősítés érvényessége',d.qualification_valid_until)}${row('Utolsó veszettségoltás',d.vaccination_date)}${row('Következő veszettségoltás',d.next_vaccination_date)}${row('Titer teszt',d.titer_test==='yes'?'Van':d.titer_test==='no'?'Nincs':'Nincs megadva')}${row('Megjegyzés',d.notes)}</dl></div>`).join(''));}

    let chatUnreadActor=null,chatUnreadChannel=null,chatUnreadTimer=null,chatUnreadCount=null,chatUnreadGeneration=0,chatReadBusy=false,chatReadLastId=null;
  function renderChatUnreadBadge(){const button=document.querySelector('#navTeamChat');if(!button)return;let badge=button.querySelector('.chat-unread-badge');if(!badge){badge=document.createElement('span');badge.className='badge chat-unread-badge';badge.setAttribute('aria-hidden','true');button.append(badge);}const valid=user?.id===chatUnreadActor&&user?.membershipStatus==='approved'&&!guest,count=valid?chatUnreadCount:null;badge.hidden=count===null||count===0;badge.textContent=count===null?'':String(count);button.setAttribute('aria-label','Csapat chat'+(count>0?', '+count+' olvasatlan üzenet':''));button.title=count>0?count+' olvasatlan üzenet':'Csapat chat';}
  async function refreshChatUnreadCount(){const actor=user?.id;if(!actor||guest||user.membershipStatus!=='approved')return;const generation=++chatUnreadGeneration;try{const {data,error}=await sb.rpc('hunor_chat_unread_count');if(error)throw error;if(user?.id!==actor||chatUnreadActor!==actor||generation!==chatUnreadGeneration)return;chatUnreadCount=Math.max(0,Number(data)||0);renderChatUnreadBadge();}catch(error){if(user?.id===actor){const button=document.querySelector('#navTeamChat');if(button)button.title='Az olvasatlan üzenetek száma most nem frissíthető.';}}}
  function stopChatUnread(){chatUnreadActor=null;chatUnreadCount=null;chatUnreadGeneration++;chatReadLastId=null;if(chatUnreadTimer)clearInterval(chatUnreadTimer);chatUnreadTimer=null;if(chatUnreadChannel){sb.removeChannel(chatUnreadChannel);chatUnreadChannel=null;}renderChatUnreadBadge();}
  function syncChatUnread(){const actor=user?.membershipStatus==='approved'&&!guest?user.id:null;if(!actor){stopChatUnread();return;}if(chatUnreadActor===actor){renderChatUnreadBadge();return;}stopChatUnread();chatUnreadActor=actor;refreshChatUnreadCount();chatUnreadTimer=setInterval(()=>{if(document.visibilityState==='visible'){refreshChatUnreadCount();if(cdIsVisible())refreshVisibleChat();}},30000);chatUnreadChannel=sb.channel('hunor-chat-unread-'+actor).on('postgres_changes',{event:'INSERT',schema:'public',table:'team_chat_messages'},()=>refreshChatUnreadCount()).on('postgres_changes',{event:'DELETE',schema:'public',table:'team_chat_messages'},()=>refreshChatUnreadCount()).on('postgres_changes',{event:'*',schema:'public',table:'team_chat_reads',filter:'member_id=eq.'+actor},()=>refreshChatUnreadCount()).subscribe(status=>{if(status==='SUBSCRIBED')refreshChatUnreadCount();});}
  async function markVisibleChatRead(){if(chatReadBusy||!cdIsVisible()||document.visibilityState!=='visible'||user?.id!==chatUnreadActor||!document.querySelector('#teamChatFeed')||!chatMessages.length)return;const actor=user.id,message=chatMessages[chatMessages.length-1];if(message.id===chatReadLastId)return;chatReadBusy=true;chatUnreadGeneration++;try{const {error}=await sb.rpc('hunor_mark_chat_read',{p_message_id:message.id});if(error)throw error;if(user?.id!==actor||chatUnreadActor!==actor)return;chatReadLastId=message.id;await refreshChatUnreadCount();}catch(error){const label=document.querySelector('#teamChatStatus');if(label)label.textContent='Az olvasottság mentése nem sikerült';}finally{chatReadBusy=false;if(user?.id===actor&&chatMessages[chatMessages.length-1]?.id!==message.id)markVisibleChatRead();}}
  async function refreshVisibleChat(){if(!cdIsVisible()||document.visibilityState!=='visible'||user?.membershipStatus!=='approved')return;const actor=user.id;try{const {data,error}=await sb.from('team_chat_messages').select('id,author_id,content,created_at,profiles(name)').order('created_at',{ascending:false}).order('id',{ascending:false}).limit(100);if(error)throw error;if(user?.id!==actor||!cdIsVisible())return;const next=(data||[]).reverse();if(next.map(m=>m.id).join(',')!==chatMessages.map(m=>m.id).join(',')){chatMessages=next;renderTeamChatMessages();}else markVisibleChatRead();}catch{refreshChatUnreadCount();}}
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){refreshChatUnreadCount();refreshVisibleChat();}});

  const IDLE_LIMIT_MS=5*60*1000;
  let idleActor=null,idleLastActivity=0,idleLastWrite=0,idleLoggingOut=false;
  const idleKey=id=>'hunor_idle_v1_'+id;
  function idleStored(id){try{const v=JSON.parse(localStorage.getItem(idleKey(id)));return typeof v?.lastActivity==='number'?v.lastActivity:null;}catch{return null;}}
  function idleWrite(id,time){try{localStorage.setItem(idleKey(id),JSON.stringify({lastActivity:time}));}catch{}idleLastWrite=Date.now();}
  function idleFreshLogin(id){idleActor=id;idleLastActivity=Date.now();idleWrite(id,idleLastActivity);}
  function idleStop(){pfIdleKey='';idleActor=null;idleLastActivity=0;document.querySelectorAll('.idle-countdown').forEach(el=>el.remove());}
  function idleRender(seconds){const key=(user?.id||'')+'|'+Boolean(user?.isAdmin)+'|'+seconds;if(pfIdleKey===key&&[...document.querySelectorAll('#navLogout,#logout')].every(b=>user?.isAdmin||b.querySelector('.idle-countdown')))return;pfIdleKey=key;
    if(user?.isAdmin&&!guest){document.querySelectorAll('.idle-countdown').forEach(el=>el.remove());for(const id of ['navLogout','logout']){const b=document.getElementById(id);if(b){b.title='Kijelentkezés · adminisztrátorként nincs tétlenségi kilépés';b.setAttribute('aria-label',b.title);}}return;}
    const text=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');
    for(const id of ['navLogout','logout']){const button=document.getElementById(id);if(!button)continue;let badge=button.querySelector('.idle-countdown');if(!badge){badge=document.createElement('span');badge.className='idle-countdown';badge.setAttribute('aria-hidden','true');button.append(badge);}badge.textContent=text;badge.classList.toggle('idle-countdown-warning',seconds<=60);button.title='Kijelentkezés · automatikus kilépés '+text+' múlva, ha nem használod a felületet';button.setAttribute('aria-label',button.title);}
  }
  function idleSync(){
    if(user?.id&&user.isAdmin&&!guest){idleActor=user.id;idleLastActivity=Date.now();if(idleLastActivity-idleLastWrite>=60000)idleWrite(idleActor,idleLastActivity);idleRender(0);return true;}
    if(!user?.id||guest){idleStop();return true;}
    if(idleActor!==user.id){idleActor=user.id;const stored=idleStored(idleActor);idleLastActivity=stored===null?Date.now():stored;if(stored===null)idleWrite(idleActor,idleLastActivity);}
    const shared=idleStored(idleActor);if(shared!==null)idleLastActivity=shared===0?0:Math.max(idleLastActivity,shared);
    const left=Math.max(0,Math.ceil((idleLastActivity+IDLE_LIMIT_MS-Date.now())/1000));idleRender(left);
    if(left===0){if(!idleLoggingOut){idleLoggingOut=true;window.logoutHunor('idle').finally(()=>{idleLoggingOut=false;});}return false;}return true;
  }
  function idleActivity(event){if(event.type==='pointermove'){if(Date.now()-pfActivityAt<250)return;pfActivityAt=Date.now();}
    if(!event.isTrusted||document.visibilityState!=='visible'||!user?.id||guest||idleLoggingOut)return;
    if(!idleSync()||user?.isAdmin)return;
    idleLastActivity=Date.now();if(idleLastActivity-idleLastWrite>=1000)idleWrite(idleActor,idleLastActivity);idleRender(300);
  }
  ['pointerdown','pointermove','keydown','touchstart','wheel','input'].forEach(type=>window.addEventListener(type,idleActivity,{capture:true,passive:true}));
  window.addEventListener('storage',event=>{if(idleActor&&event.key===idleKey(idleActor))idleSync();});
  document.addEventListener('visibilitychange',()=>idleSync());window.addEventListener('pageshow',()=>idleSync());
  setInterval(()=>idleSync(),1000);

