  function exStyles(){if(document.querySelector('#exStyles'))return;const s=document.createElement('style');s.id='exStyles';s.textContent=`.ex-shell{color:#e3ecfa}.ex-toolbar,.ex-tabs,.ex-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:22px}.ex-toolbar select{flex:1;min-width:220px}.ex-shell select,.ex-field input,.ex-field textarea{background:#101f35;color:#e3ecfa;border:1px solid #344b68;border-radius:9px;padding:12px;width:100%;font:inherit}.ex-tabs button{border:1px solid #344b68;background:#13253f;color:#b8cce5;padding:12px;border-radius:10px;cursor:pointer}.ex-tabs button.active{background:#255778;color:white;border-color:#60c5df}.ex-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.ex-card{background:#14263f;border:1px solid #304562;border-radius:16px;padding:24px;margin-bottom:18px}.ex-card h2,.ex-card h3{margin:0 0 16px;color:#f1f6ff}.ex-card p{white-space:pre-wrap;line-height:1.75;color:#c1d0e3}.ex-meta{color:#92accb;font-size:13px;margin:10px 0 18px}.ex-badge{display:inline-block;border:1px solid #507393;border-radius:20px;padding:5px 10px;color:#8fe0ec;font-size:12px}.ex-field{display:block;margin:0 0 18px;color:#b6cce4}.ex-field input,.ex-field textarea,.ex-field select{display:block;margin-top:8px}.ex-form{max-height:70vh;overflow:auto;padding:4px}.ex-alert{border-left:4px solid #f5b35d;padding:16px;background:#26334a;border-radius:8px;margin:18px 0;color:#f8d6a3}.ex-stats{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}.ex-stats span{padding:14px 18px;background:#14263f;border:1px solid #304562;border-radius:10px}.ex-empty{padding:38px;border:1px dashed #486181;border-radius:16px;color:#b6cce4}.ex-critical{border-left:4px solid #ef7b75}.ex-high{border-left:4px solid #f5b35d}@media(max-width:700px){.ex-grid{grid-template-columns:1fr}.ex-card{padding:18px}}`;document.head.append(s);}
