  function articleStyles(){if(document.querySelector('#articleStyles'))return;const s=document.createElement('style');s.id='articleStyles';s.textContent=`.journal{--jbg:#101f34;--jline:#344960;--jmuted:#a4b8d1;color:#e7eef8;margin:24px 0}.journal-head{display:flex;justify-content:space-between;align-items:center;gap:18px;border-top:4px solid #d5414d;border-bottom:1px solid var(--jline);padding:22px 0}.journal-head h1{font-size:38px;letter-spacing:-1.5px;margin:6px 0}.journal-head p{color:var(--jmuted);margin:8px 0}.journal-nav{display:flex;flex-wrap:wrap;gap:8px;padding:18px 0;border-bottom:1px solid var(--jline);margin-bottom:24px}.journal-nav button{padding:9px 13px;background:#172c44;border:1px solid #344960;border-radius:6px;color:#bcd0e7}.journal-nav button.active{background:#385c78;color:#fff;border-color:#75b8d7}.journal-search{margin-bottom:22px}.journal-search input{width:100%;padding:13px;border:1px solid #344960;border-radius:8px}.journal-lead{display:grid;grid-template-columns:minmax(0,2fr) minmax(230px,1fr);gap:26px;margin-bottom:32px}.journal-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.journal-card{background:#14263d;border:1px solid #30455e;border-radius:10px;overflow:hidden;min-width:0}.journal-card .journal-copy{padding:20px}.journal-card h2,.journal-card h3{color:#f1f5fc;line-height:1.2;letter-spacing:-.5px;margin:12px 0}.journal-card h2{font-size:34px}.journal-card h3{font-size:23px}.journal-card p{color:#bdcde1;line-height:1.75;margin:12px 0;font-size:14px}.journal-topic{color:#88cce1;font-size:11px;text-transform:uppercase;letter-spacing:1.2px;font-weight:800}.journal-meta{color:#9db2cb;font-size:12px;margin:14px 0}.journal-title{background:none;border:0;padding:0;text-align:left;color:inherit;font:inherit;font-weight:inherit;line-height:inherit;cursor:pointer}.journal-title:hover{text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:4px}.journal-cover{display:block;width:100%;border:0;padding:0;background:#203c58;color:#c6e5f0;aspect-ratio:16/9;overflow:hidden;cursor:pointer}.journal-cover img{width:100%;height:100%;object-fit:cover;display:block}.journal-placeholder{display:grid;place-content:center;gap:12px;font-size:15px;height:100%;background:linear-gradient(140deg,#284e69,#152a42)}.journal-placeholder strong{font-size:32px;letter-spacing:5px}.journal-latest{border-top:3px solid #78bad3;padding-top:16px}.journal-latest h2{font-size:18px}.journal-latest a{display:block;color:#dce9f7;line-height:1.5;text-decoration:none;border-bottom:1px solid #30455e;padding:15px 0}.journal-latest small{display:block;color:#8fa8c5;margin-bottom:7px}.journal-footer{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-top:18px}.journal-empty{padding:35px;background:#14263d;border:1px dashed #415974;border-radius:10px;color:#b5c9de}.modal:has(.article-reader),.modal:has(.article-editor){width:min(1000px,96vw);max-height:90vh;overflow:auto;background:#122138!important}.article-reader{color:#e6eef8}.article-reader header,.article-reading{max-width:760px;margin:0 auto}.article-reader h1{font-size:clamp(28px,4vw,44px);line-height:1.15;letter-spacing:-1px;margin:18px 0 24px}.article-reader .article-intro{font-size:19px;color:#bfd0e5;line-height:1.7}.article-reading p{font-size:17px;line-height:1.85;white-space:pre-wrap;overflow-wrap:anywhere;margin:24px 0}.article-reader figure{margin:26px 0}.article-reader img,.article-reader video{width:100%;max-height:70vh;object-fit:contain;display:block;background:#091426;border-radius:8px}.article-reader figcaption{color:#a4bad2;font-size:13px;padding:10px 2px}.article-gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.article-gallery figure{margin:0}.article-editor .field label{font-size:12px}.article-editor .field textarea{min-height:100px;line-height:1.65}.article-editor .field textarea[name=content]{min-height:240px}.article-editor-help{color:#a5bbd2;font-size:13px;line-height:1.6}.article-media-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:18px 0}.article-media-tile{background:#1b304a;border:1px solid #3b5270;border-radius:10px;padding:12px;min-width:0}.article-media-tile img,.article-media-tile video{width:100%;height:120px;object-fit:contain;background:#0a1627}.article-media-tile small{display:block;overflow-wrap:anywhere;margin:9px 0;color:#b4c8df}.article-media-tile input{width:100%;padding:8px;margin:8px 0;border:1px solid #3b5270;border-radius:6px}.article-media-tile .secondary{padding:6px;margin:2px}.article-editor .article-save{position:sticky;bottom:0;background:#122138;border-top:1px solid #344960;padding:14px 0}.article-editor .article-save button{width:auto}.resource-card{background:#14263d!important;border-color:#344960!important;color:#e7eef8}.resource-card p{color:#b9cce1!important}.public-item{background:#14263d!important;border-color:#344960!important}.public-body p{color:#b9cce1!important}@media(max-width:900px){.journal-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.journal-lead{grid-template-columns:1fr}.journal-card h2{font-size:29px}}@media(max-width:600px){.journal-grid,.article-gallery{grid-template-columns:1fr}.journal-head{align-items:flex-start;flex-direction:column}.journal-head h1{font-size:30px}.article-media-list{grid-template-columns:1fr 1fr}.journal-card h3{font-size:22px}}`;document.head.append(s);}
  function articleMedia(row){const list=(row.public_media||[]).map(x=>({...x}));if(row.file_path&&!list.some(x=>x.path===row.file_path))list.unshift({path:row.file_path,type:row.resource_type==='video'?'video':'image',name:row.file_name||'',caption:''});return list;}
  async function mapArticleResources(rows){const items=rows.map(row=>({...mapResource(row),topic:row.public_topic||'Hírek',content:row.content||'',featured:row.public_featured,createdBy:row.created_by,createdAt:row.created_at,updatedAt:row.updated_at,media:articleMedia(row)}));const paths=[...new Set(items.flatMap(x=>x.media.map(m=>m.path)))];const urls=new Map();if(paths.length){try{for(const [path,url] of await pfSignedUrls(PUBLIC_MEDIA_BUCKET,paths))urls.set(path,url);}catch{}}for(const x of items){x.media=x.media.map(m=>({...m,src:urls.get(m.path)||''}));x.fileUrl=x.media[0]?.src||'';}return items;}
  function articleCard(x,lead=false){const image=x.media?.find(m=>m.type==='image'&&m.src),hasVideo=x.media?.some(m=>m.type==='video');return `<article class="journal-card"><button class="journal-cover" onclick="openPublicArticle('${x.id}')" aria-label="${esc(x.title)} megnyitása">${image?`<img src="${esc(image.src)}" alt="${esc(image.caption||x.title)}" loading="lazy" decoding="async">`:`<span class="journal-placeholder"><strong>HUNOR</strong><span>${hasVideo?'Videóbeszámoló':esc(x.topic||'Hírek')}</span></span>`}</button><div class="journal-copy"><span class="journal-topic">${esc(x.topic||'Hírek')}</span><${lead?'h2':'h3'}><button class="journal-title" onclick="openPublicArticle('${x.id}')">${esc(x.title)}</button></${lead?'h2':'h3'}><div class="journal-meta">${esc(articleDate(x.createdAt))}${hasVideo?' · Videó':''}${x.media?.length?' · '+x.media.length+' média':''}</div><p>${esc((x.description||x.content||'').slice(0,lead?280:160))}${(x.description||x.content||'').length>(lead?280:160)?'…':''}</p><div class="journal-footer"><button class="secondary" onclick="openPublicArticle('${x.id}')">Elolvasom →</button>${canEditArticle(x)?`<button class="secondary" onclick="openPublicItem('${x.id}')">Szerkesztés</button>`:''}</div></div></article>`;}
  function publicJournal(){articleStyles();const topics=[...new Set(publicItems.map(x=>x.topic||'Hírek'))].sort((a,b)=>a.localeCompare(b,'hu'));return `<section class="journal"><header class="journal-head"><div><div class="eyebrow">HUNOR · NYILVÁNOS HÍREK</div><h1>Hírek a mentőcsapattól</h1><p>Beszámolók, gyakorlatok és történetek a helyszínről.</p></div>${canUploadPublicContent()?'<button class="pill-btn" onclick="openPublicItem()">＋ Új cikk</button>':''}</header><nav class="journal-nav" aria-label="Cikkek témái"><button data-topic="" class="${!journalTopic?'active':''}" onclick="filterPublicTopic('')">Összes</button>${topics.map(t=>`<button data-topic="${esc(t)}" class="${journalTopic===t?'active':''}" onclick="filterPublicTopic(this.dataset.topic)">${esc(t)}</button>`).join('')}</nav><div class="journal-search"><input type="search" aria-label="Keresés a nyilvános cikkekben" placeholder="Keresés címre, témára vagy szövegre…" value="${esc(journalQuery)}" oninput="filterPublicArticles(this.value)"></div><div id="journalResults">${journalResults()}</div></section>`;}
  function journalResults(){const fold=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('hu');const words=fold(journalQuery).split(/\s+/).filter(Boolean),rows=publicItems.filter(x=>(!journalTopic||x.topic===journalTopic)&&words.every(w=>fold([x.title,x.description,x.content,x.topic].join(' ')).includes(w))).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));if(!rows.length)return '<div class="journal-empty">Ebben a témában vagy keresésben még nincs cikk.</div>';const lead=rows.find(x=>x.featured)||rows[0],rest=rows.filter(x=>x.id!==lead.id);return `<div class="journal-lead">${articleCard(lead,true)}<aside class="journal-latest"><h2>Legfrissebb hírek</h2>${rows.slice(0,6).map(x=>`<a href="#" data-article="${x.id}" onclick="event.preventDefault();openPublicArticle(this.dataset.article)"><small>${esc(articleDate(x.createdAt))} · ${esc(x.topic)}</small><b>${esc(x.title)}</b></a>`).join('')}${guestEvents.length?`<h2 style="margin-top:28px">Nyilvános programok</h2>${guestEvents.slice(0,4).map(x=>`<a href="#" onclick="event.preventDefault();openEventDetails('${x.id}')"><small>${esc(x.date)} · ${esc(x.place)}</small>${esc(x.title)}</a>`).join('')}`:''}</aside></div>${rest.length?`<div class="journal-grid">${rest.map(x=>articleCard(x)).join('')}</div>`:''}`;}
  window.filterPublicArticles=q=>{journalQuery=q;const el=document.querySelector('#journalResults');if(el)el.innerHTML=journalResults();};
  window.filterPublicTopic=t=>{journalTopic=t;document.querySelectorAll('.journal-nav [data-topic]').forEach(b=>b.classList.toggle('active',b.dataset.topic===t));window.filterPublicArticles(journalQuery);};
