  window.videoLibraryPage=()=>{articleStyles();return `<section class="journal"><header class="journal-head"><h1>Videóbeszámolók</h1>${canUploadPublicContent()?'<button class="pill-btn" onclick="openPublicItem()">＋ Új cikk / videó</button>':''}</header><div class="journal-grid">${publicItems.filter(x=>x.media?.some(m=>m.type==='video')||x.entryType==='Videó').map(x=>articleCard(x)).join('')||'<div class="journal-empty">Még nincs videóbeszámoló.</div>'}</div></section>`;};
  
  function articleReaderMedia(m){return `<figure>${m.src?m.type==='video'?`<video controls preload="metadata" playsinline src="${esc(m.src)}"></video>`:`<a href="${esc(m.src)}" target="_blank" rel="noopener noreferrer"><img src="${esc(m.src)}" alt="${esc(m.caption||m.name||'Cikk képe')}" loading="lazy" decoding="async"></a>`:'<p class="article-editor-help">A média most nem tölthető be. Nyisd meg újra a cikket.</p>'}${m.caption?`<figcaption>${esc(m.caption)}</figcaption>`:''}</figure>`;}
  window.openPublicArticle=async id=>{articleStyles();const seq=++articleReadSeq;openModal('<div class="article-reader"><div class="modal-head"><h2>Cikk betöltése…</h2><button class="close" onclick="closeModal()">×</button></div></div>');try{const {data,error}=await sb.from('resources').select('*').eq('id',id).eq('visibility','public').single();if(error)throw error;const [x]=await mapArticleResources([data]);if(seq!==articleReadSeq||!document.querySelector('#overlay.show'))return;const paragraphs=(x.content||x.description||'').split(/\n\s*\n/).filter(Boolean);openModal(`<article class="article-reader"><div class="modal-head"><button class="secondary" onclick="closeModal()">← Vissza a hírekhez</button>${canEditArticle(x)?`<button class="secondary" onclick="openPublicItem('${x.id}')">Cikk szerkesztése</button>`:''}<button class="close" onclick="closeModal()" aria-label="Bezárás">×</button></div><header><span class="journal-topic">${esc(x.topic)}</span><h1>${esc(x.title)}</h1><div class="journal-meta">HUNOR · ${esc(articleDate(x.createdAt))}${x.updatedAt&&x.updatedAt!==x.createdAt?' · Módosítva: '+esc(articleDate(x.updatedAt)):''}</div>${x.content&&x.description?`<p class="article-intro">${esc(x.description)}</p>`:''}</header>${x.media?.[0]?articleReaderMedia(x.media[0]):''}<div class="article-reading">${paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}${safeLink(x.url)?`<a class="public-link" href="${esc(safeLink(x.url))}" target="_blank" rel="noopener noreferrer">Kapcsolódó hivatkozás ↗</a>`:''}</div>${x.media.length>1?`<h2 style="margin-top:32px">Képek és videók</h2><div class="article-gallery">${x.media.slice(1).map(articleReaderMedia).join('')}</div>`:''}</article>`);}catch(e){if(seq===articleReadSeq)openModal(`<div class="article-reader"><div class="modal-head"><h2>A cikk nem érhető el</h2><button class="close" onclick="closeModal()">×</button></div><p>${esc(e.message)}</p></div>`);}};
  function clearArticleDraft(){for(const m of articleMediaDraft)if(m.preview)URL.revokeObjectURL(m.preview);articleMediaDraft=[];articleEdit=null;}
  const articleBaseClose=window.closeModal;window.closeModal=function(){if(articleBusy&&user?.id)return;articleReadSeq++;clearArticleDraft();articleBaseClose();};
  window.openPublicItem=async id=>{if(!canUploadPublicContent())return notify('Nyilvános cikkhez sajtós, szerkesztői vagy admin jogosultság szükséges.');if(articleBusy)return;articleStyles();clearArticleDraft();const editorActor=user?.id;let x=null;if(id){const r=await sb.from('resources').select('*').eq('id',id).eq('visibility','public').single();if(r.error)return notify('A cikk nem tölthető be.');[x]=await mapArticleResources([r.data]);if(!canEditArticle(x))return notify('Ezt a cikket nem szerkesztheted.');}if(user?.id!==editorActor||!canUploadPublicContent())return;articleEdit=x||{id:crypto.randomUUID()};articleMediaDraft=(x?.media||[]).map(m=>({...m}));openModal(`<div class="article-editor"><div class="modal-head"><h2>${x?'Cikk szerkesztése':'Új nyilvános cikk'}</h2><button class="close" onclick="closeModal()" aria-label="Bezárás">×</button></div><form id="articleForm"><div class="field"><label for="articleTitle">Cím / esemény neve</label><input id="articleTitle" name="title" required maxlength="200" value="${esc(x?.title||'')}"></div><div class="field"><label for="articleTopic">Téma / rovat</label><input id="articleTopic" name="topic" required maxlength="100" list="articleTopics" value="${esc(x?.topic||'Hírek')}"><datalist id="articleTopics">${[...new Set(['Hírek','Bevetések','Gyakorlatok','Képzések','K9','Csapatélet',...publicItems.map(x=>x.topic)])].filter(Boolean).map(t=>`<option value="${esc(t)}">`).join('')}</datalist></div><div class="field"><label for="articleDescription">Rövid leírás / bevezető</label><textarea id="articleDescription" name="description" maxlength="3000">${esc(x?.description||'')}</textarea></div><div class="field"><label for="articleContent">Cikk teljes szövege</label><textarea id="articleContent" name="content" maxlength="100000" placeholder="A bekezdések között hagyj egy üres sort.">${esc(x?.content||'')}</textarea></div><div class="field"><label for="articleUrl">Kapcsolódó hivatkozás (opcionális)</label><input id="articleUrl" name="url" type="url" value="${esc(x?.url||'')}" placeholder="https://…"></div><label class="article-editor-help"><input name="featured" type="checkbox" ${x?.featured?'checked':''}> Kiemelt cikk a híroldal tetején</label><h3>Képek és videók</h3><p class="article-editor-help">Egyszerre több fájl választható. Legfeljebb 30 csatolmány, fájlonként 50 MB. Az első kép lesz a cikk borítója; a sorrend módosítható. A képaláírás a nyilvános cikkben is megjelenik.</p><label class="field" for="articleFiles">Képek / videók hozzáadása<input id="articleFiles" type="file" multiple accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime,video/webm" onchange="articleAddFiles(this)"></label><div id="articleMediaList" class="article-media-list"></div><div class="article-save"><p id="articleSaveStatus" role="status" aria-live="polite"></p><button class="pill-btn" type="submit">${x?'Módosítások közzététele':'Cikk közzététele'}</button></div></form><p class="article-editor-help">A mentett cikk és csatolmányai a nyilvános oldalon megjelennek.</p></div>`);articleRenderMedia();document.querySelector('#articleForm').onsubmit=savePublicArticle;};
  window.articleAddFiles=input=>{if(articleBusy)return;const files=[...input.files];if(articleMediaDraft.length+files.length>30){input.value='';return notify('Legfeljebb 30 csatolmány adható meg.');}if(files.some(f=>!articleTypes.includes(f.type)||f.size>PUBLIC_MEDIA_FILE_LIMIT)){input.value='';return notify('JPEG, PNG, WebP kép vagy MP4, MOV, WebM videó tölthető fel, fájlonként legfeljebb 50 MB.');}for(const file of files)articleMediaDraft.push({file,name:file.name,type:file.type.startsWith('image/')?'image':'video',caption:'',preview:URL.createObjectURL(file)});input.value='';articleRenderMedia();};
