  function articleRenderMedia(){const el=document.querySelector('#articleMediaList');if(!el)return;el.innerHTML=articleMediaDraft.map((m,i)=>`<div class="article-media-tile">${m.preview||m.src?m.type==='image'?`<img src="${esc(m.preview||m.src)}" alt="${esc(m.name)}">`:`<video src="${esc(m.preview||m.src)}" controls preload="metadata"></video>`:'<p>Média előnézet nem érhető el.</p>'}<small>${i+1}. ${esc(m.name||'Csatolmány')}</small><input aria-label="${i+1}. média képaláírása" maxlength="1000" placeholder="Képaláírás / videó leírása" value="${esc(m.caption||'')}" oninput="articleCaption(${i},this.value)"><button type="button" class="secondary" onclick="articleMoveMedia(${i},-1)" ${i===0?'disabled':''}>Előrébb</button><button type="button" class="secondary" onclick="articleMoveMedia(${i},1)" ${i===articleMediaDraft.length-1?'disabled':''}>Hátrébb</button><button type="button" class="secondary" onclick="articleRemoveMedia(${i})">Eltávolítás</button></div>`).join('')||'<p class="article-editor-help">Még nincs csatolt kép vagy videó.</p>';}
  async function savePublicArticle(event){event.preventDefault();if(articleBusy||!canUploadPublicContent())return;const form=event.currentTarget,f=new FormData(form),value=k=>String(f.get(k)||'').trim(),record=articleEdit,actor=user?.id,media=articleMediaDraft.map(m=>({...m}));if(!value('title')||!value('topic'))return notify('A cím és a téma megadása kötelező.');if(value('url')&&!safeLink(value('url')))return notify('Csak http vagy https hivatkozás használható.');if(!value('description')&&!value('content')&&!media.length&&!value('url'))return notify('Adj meg szöveget, médiát vagy hivatkozást.');const fields=[...form.querySelectorAll('input,textarea,button')],status=document.querySelector('#articleSaveStatus');articleBusy=true;fields.forEach(x=>x.disabled=true);const uploaded=[];try{const savedMedia=[];for(let i=0;i<media.length;i++){const m=media[i];let path=m.path;if(m.file){path=await uploadEducationFile(m.file,pct=>{status.textContent=`Feltöltés: ${i+1}/${media.length} · ${pct}%`;},PUBLIC_MEDIA_BUCKET);uploaded.push(path);}savedMedia.push({path,type:m.type,name:m.name||'',caption:m.caption||''});}status.textContent='Cikk mentése…';if(user?.id!==actor)throw Error('A munkamenet megváltozott. Jelentkezz be újra.');const payload={title:value('title'),public_topic:value('topic'),description:value('description')||null,content:value('content')||null,url:value('url')||null,public_featured:f.has('featured'),public_media:savedMedia,resource_type:'article',visibility:'public',file_path:null,file_name:null};const q=record.createdAt?sb.from('resources').update(payload).eq('id',record.id).eq('updated_at',record.updatedAt):sb.from('resources').insert({...payload,id:record.id,created_by:actor});const {data,error}=await q.select('id').single();if(error)throw error;if(!data)throw Error('A cikk közben megváltozott. Nyisd meg újra.');articleBusy=false;closeModal();await window.setPage('events');notify('A cikket közzétettük.');}catch(e){if(uploaded.length&&user?.id===actor){const check=await sb.from('resources').select('public_media').eq('id',record.id).maybeSingle();if(!check.error){const used=(check.data?.public_media||[]).map(m=>m.path);const unused=uploaded.filter(p=>!used.includes(p));if(unused.length)await sb.storage.from(PUBLIC_MEDIA_BUCKET).remove(unused);}}status.textContent='Nem sikerült menteni: '+(e.code==='PGRST116'?'A cikket közben módosították. Nyisd meg újra, mielőtt szerkeszted.':e.message);articleBusy=false;fields.forEach(x=>x.disabled=false);}}

  let vwPallets=[],vwItems=[],vwHistory=[],vwRack=1,vwSelected=null,vwPicked=null,vwDrag=null,vwBusy=false,vwPoolQuery='',vwRotation=false,vwActor=null;
  const vwPal=id=>vwPallets.find(p=>p.id===id),vwAsset=id=>logistics.assets.find(a=>a.id===id),vwContents=id=>vwItems.filter(i=>i.pallet_id===id),vwOnPallet=id=>vwItems.find(i=>i.asset_id===id);
  const vwWarehouse=()=>logistics.locations.find(l=>l.active&&l.kind==='warehouse');
  function vwAssetPath(a){const item=vwOnPallet(a.id),p=vwPal(item?.pallet_id);return logPath(a.location_id)+(p?' / '+p.code+' · '+p.name:'');}
  const vwOriginalMoveDialog=window.logMoveDialog;
  window.logMoveDialog=id=>{const attached=(id?[id]:[...logSelected]).map(vwOnPallet).find(Boolean);if(attached){closeModal();logView='warehouse';vwSelected=attached.pallet_id;vwPicked={type:'asset',id:attached.asset_id};renderLogistics();notify('A láda raklapon van. A raklap nézetében a Levétel gombbal vedd le, vagy mozgasd az egész raklapot.');return;}vwOriginalMoveDialog(id);};
  function vwInWarehouse(id){let l=logLoc(id);for(let n=0;l&&n<4;n++){if(l.kind==='warehouse')return true;l=logLoc(l.parent_id);}return false;}
  function vwDims(a,rotated=false){return {w:Number(rotated?a.width_cm:a.length_cm),h:Number(rotated?a.length_cm:a.width_cm)};}
  function vwFits(palletId,a,x,y,rotated){const d=vwDims(a,rotated);if(!(d.w>0&&d.h>0)||x<0||y<0||x+d.w>120||y+d.h>80)return false;return !vwContents(palletId).filter(i=>i.asset_id!==a.id).some(i=>{const b=vwAsset(i.asset_id),r=vwDims(b,i.rotated);return x<Number(i.x_cm)+r.w&&Number(i.x_cm)<x+d.w&&y<Number(i.y_cm)+r.h&&Number(i.y_cm)<y+d.h;});}
  function vwAutoFit(palletId,a){const items=vwContents(palletId).filter(i=>i.asset_id!==a.id),xs=[0,...items.map(i=>Number(i.x_cm)+vwDims(vwAsset(i.asset_id),i.rotated).w)],ys=[0,...items.map(i=>Number(i.y_cm)+vwDims(vwAsset(i.asset_id),i.rotated).h)];for(const rotated of [vwRotation,!vwRotation])for(const y of ys.sort((a,b)=>a-b))for(const x of xs.sort((a,b)=>a-b))if(vwFits(palletId,a,x,y,rotated))return {x,y,rotated};return null;}
  function vwPalletWeight(p){const rows=vwContents(p.id).map(i=>vwAsset(i.asset_id)),unknown=p.tare_kg===null||rows.some(a=>a.total_kg===null);return logNumber(rows.reduce((s,a)=>s+Number(a.total_kg||0),Number(p.tare_kg||0)))+' kg'+(unknown?' + hiányzó tömeg':'');}
  function vwStyles(){if(document.querySelector('#vwStyles'))return;const s=document.createElement('style');s.id='vwStyles';s.textContent=`.vw{color:#e8eff8}.vw .panel{background:#13243b;border:1px solid #344961}.vw-hero{display:flex;align-items:center;justify-content:space-between;gap:18px;margin:25px 0}.vw-hero h1{margin:10px 0 14px}.vw-hero p,.vw-help{color:#afc1d8;line-height:1.7}.vw-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:22px 0}.vw-kpis>div{padding:19px;background:#172e47;border:1px solid #3a526a;border-radius:12px}.vw-kpis small{display:block;color:#a9bfd5}.vw-kpis b{display:block;font-size:30px;margin-top:10px}.vw-racks{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin:20px 0}.vw-racks button{padding:18px;text-align:left;background:#172b43;border:1px solid #3a526a;border-radius:10px;color:#dae7f6}.vw-racks button.active{border-color:#78d3dc;box-shadow:inset 0 3px #78d3dc}.vw-racks b,.vw-racks small{display:block;margin:5px 0}.vw-rack-mini{display:grid;grid-template-columns:repeat(15,1fr);gap:3px;margin-top:14px}.vw-rack-mini i{height:7px;background:#35526a}.vw-rack-mini i.filled{background:#4ba4b3}.vw-scroll{overflow-x:auto;padding:12px 4px 20px}.vw-elevation{min-width:1130px;background:linear-gradient(90deg,#192d40,#142437);padding:15px;border-radius:10px;border:1px solid #4b667b}.vw-columns,.vw-level{display:grid;grid-template-columns:46px repeat(15,minmax(0,1fr));gap:7px}.vw-columns{font-size:10px;color:#9fb6ca;text-align:center;padding:0 0 10px}.vw-level{border-bottom:8px solid #c47332;border-left:7px solid #647c8e;border-right:7px solid #647c8e;padding:12px 5px 0;min-height:90px;box-shadow:0 3px #603b23}.vw-level+ .vw-level{margin-top:5px}.vw-level-label{font-size:11px;display:flex;align-items:center;color:#a8bed4}.vw-slot{min-height:76px;background:#0d1c2e;border:1px dashed #415a71;border-radius:4px;padding:5px;display:flex;flex-direction:column;justify-content:flex-end;position:relative;cursor:pointer;color:#8da6bc;font-size:9px;text-align:center}.vw-slot>small{display:block;margin:5px 0}.vw-slot.occupied{border-style:solid;border-color:#648a9e}.vw-slot.selected{outline:2px solid #83dee0}.vw-slot .vw-pallet{cursor:grab}.vw-pallet-deck{height:9px;margin-top:5px;background:repeating-linear-gradient(90deg,#ac8150 0 12%,#624b31 12% 15%);border:1px solid #d1a572;border-radius:2px}.vw-pallet-crates{display:flex;gap:2px;align-items:flex-end;justify-content:center;min-height:25px;flex-wrap:wrap}.vw-tiny-crate{display:inline-block;background:var(--crate);border:1px solid #94a4b5;border-radius:3px;width:20px;height:19px;box-shadow:inset 0 4px #ffffff20}.vw-drop-hover{outline:3px solid #81d9d6!important;background-color:#234856!important}.vw-workgrid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(280px,1fr);gap:20px;margin-top:24px}.vw-floor{display:flex;flex-wrap:wrap;gap:10px;min-height:84px;padding:15px;border:1px dashed #597284;border-radius:10px;background:#102238}.vw-floor .vw-pallet{width:120px;padding:12px;border:1px solid #517080;border-radius:8px;background:#233c50;color:#e8eff8}.vw-floor .vw-pallet.selected{outline:2px solid #80d8db}.vw-pallet-label{display:block;font-size:11px;text-align:center;margin:5px 0}.vw-floor-heading{display:flex;justify-content:space-between;gap:12px;align-items:center}.vw-plan{position:relative;width:100%;aspect-ratio:120/80;border:3px solid #bc9665;border-radius:4px;background:repeating-linear-gradient(0deg,#765d40 0 11%,#a58255 11% 12%,#765d40 12% 24%);margin:20px 0 10px;overflow:hidden;box-shadow:0 7px #342c27}.vw-plan:before{content:'';position:absolute;inset:0;background-image:linear-gradient(#ffffff13 1px,transparent 1px),linear-gradient(90deg,#ffffff13 1px,transparent 1px);background-size:8.3333% 12.5%;pointer-events:none}.vw-plan-crate{position:absolute;background:var(--crate);border:2px solid #c2ccd4;box-shadow:inset 0 6px #ffffff20;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;text-shadow:0 1px 3px #000;font-size:12px;overflow:hidden;border-radius:4px;cursor:grab;padding:3px}.vw-plan-crate.light{color:#10213a;text-shadow:none}.vw-plan-crate.picked{outline:3px solid #89ffff;outline-offset:-5px}.vw-plan-crate small{font-size:10px}.vw-pool{max-height:390px;overflow:auto;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:14px}.vw-pool-card{background:#1a3049;border:1px solid #415a72;border-radius:8px;padding:12px;cursor:grab;color:#e5edf7;text-align:left}.vw-pool-card.picked{outline:2px solid #8bd8dd}.vw-pool-card svg{width:55px;height:40px;float:left;margin-right:10px}.vw-pool-card b,.vw-pool-card small{display:block;margin:4px 0;overflow-wrap:anywhere}.vw-pool-card small{font-size:11px;color:#b7cbe0}.vw-vehicles{display:flex;gap:12px;overflow:auto;margin:15px 0;padding:5px}.vw-vehicle{min-width:190px;max-width:270px;padding:17px;background:#1b344c;border:1px solid #57728a;border-radius:12px;color:#e5eef8;cursor:pointer}.vw-vehicle b,.vw-vehicle small{display:block;margin:8px 0}.vw-targets{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}.vw-targets button{padding:14px;background:#203c52;border:1px dashed #79a8b5;color:#e6f3f8;border-radius:8px}.vw-controls{display:flex;flex-wrap:wrap;gap:10px;align-items:end}.vw-controls label{max-width:120px;font-size:12px;color:#b8cee1}.vw-controls input{width:100%;padding:9px;margin-top:5px}.vw-status{padding:12px;border:1px solid #456277;border-radius:6px;color:#acdce2;line-height:1.5}.vw-error{color:#ffd0b3;border-color:#b47a53}.vw-modal{width:min(900px,94vw)}.modal:has(.vw-modal){width:min(940px,96vw)}.vw-list-row{display:flex;align-items:center;justify-content:space-between;gap:10px;border-bottom:1px solid #3a5066;padding:12px 0}.vw-list-row small{display:block;color:#afc5db}.vw .secondary,.vw-modal .secondary{color:#dce9f7}.vw-pool-search{width:100%;padding:12px;border:1px solid #456078;border-radius:8px}.vw-bottom-note{font-size:12px;color:#a4b7ca;margin-top:16px;line-height:1.7}@media(max-width:850px){.vw-workgrid{grid-template-columns:1fr}.vw-kpis{grid-template-columns:1fr 1fr}.vw-racks{grid-template-columns:1fr}.vw-racks .vw-rack-mini{display:none}.vw-hero{align-items:flex-start;flex-direction:column}}`;document.head.append(s);}
  function vwMini(p,draggable=true){const rows=vwContents(p.id);return `<div class="vw-pallet ${p.id===vwSelected?'selected':''}" ${draggable&&canManageLogistics()?'draggable="true"':''} ondragstart="vwDragStart(event,'pallet','${p.id}')" ondragend="vwDragEnd()" ondragover="vwDragOver(event)" ondragleave="vwDragLeave(event)" ondrop="vwDropOnPallet(event,'${p.id}')" onclick="event.stopPropagation();vwSelectPallet('${p.id}')" role="button" tabindex="0" onkeydown="if(event.key==='Enter')vwSelectPallet('${p.id}')" aria-label="${esc(p.code)} raklap megnyitása" title="${esc(p.code+' · '+p.name+' · '+rows.length+' láda')}"><div class="vw-pallet-crates">${rows.slice(0,6).map(i=>`<span class="vw-tiny-crate" style="--crate:${logCrateColor(vwAsset(i.asset_id))}"></span>`).join('')||'<small>Üres</small>'}</div><div class="vw-pallet-deck"></div><b class="vw-pallet-label">${esc(p.code)}</b></div>`;}
  function vwRackMap(){return `<div class="vw-racks">${[1,2,3].map(n=>{const slots=logistics.locations.filter(l=>l.virtual_rack===n&&l.virtual_level),used=vwPallets.filter(p=>slots.some(s=>s.id===p.location_id)).length;return `<button class="${vwRack===n?'active':''}" onclick="vwSetRack(${n})"><b>${n}. Salgó állvány</b><small>4 szint × 15 hely · ${used} / 60 foglalt</small><div class="vw-rack-mini">${[4,3,2,1].flatMap(level=>Array.from({length:15},(_,c)=>{const slot=slots.find(s=>s.virtual_level===level&&s.virtual_column===c+1);return `<i class="${vwPallets.some(p=>p.location_id===slot?.id)?'filled':''}"></i>`;})).join('')}</div></button>`;}).join('')}</div><section class="panel"><div class="panel-head"><div><h2>${vwRack}. állvány · elölnézet</h2><small class="vw-help">Egy mező egy EUR raklaphely · a 4. szint van legfelül</small></div></div><div class="vw-scroll"><div class="vw-elevation"><div class="vw-columns"><span>Szint</span>${Array.from({length:15},(_,c)=>`<span>${String(c+1).padStart(2,'0')}</span>`).join('')}</div>${[4,3,2,1].map(level=>`<div class="vw-level"><span class="vw-level-label">${level}. szint</span>${Array.from({length:15},(_,c)=>{const slot=logistics.locations.find(l=>l.virtual_rack===vwRack&&l.virtual_level===level&&l.virtual_column===c+1),p=vwPallets.find(p=>p.location_id===slot?.id);if(!slot)return '<div class="vw-slot">Nem elérhető</div>';return `<div class="vw-slot ${p?'occupied':''} ${p?.id===vwSelected?'selected':''}" ondragover="vwDragOver(event)" ondragleave="vwDragLeave(event)" ondrop="vwDrop(event,'slot','${slot.id}')" onclick="vwSlotClick('${slot.id}')" role="button" tabindex="0" onkeydown="if(event.key==='Enter')vwSlotClick('${slot.id}')" aria-label="${esc(slot.code)} ${p?esc(p.code):'üres raklaphely'}">${p?vwMini(p):'<span>＋<br>Raklaphely</span>'}<small>${esc(slot.code)}</small></div>`;}).join('')}</div>`).join('')}</div></div><p class="vw-bottom-note">A raktár elrendezése: 3 állvány, állványonként 60 hely, egy raklapnyi mélység. A polcok terhelhetőségét és szabad magasságát még nem adtuk meg.</p></section>`;}
  function vwVehicleTargets(){const rows=logistics.locations.filter(l=>l.active&&['vehicle','site'].includes(l.kind));return `<section class="panel"><div class="panel-head"><h2>Rakodási célok</h2>${canManageLogistics()?'<div class="log-buttons"><button class="secondary" onclick="logEditLocation(\'vehicle\')">＋ Jármű</button><button class="secondary" onclick="logEditLocation(\'site\')">＋ Helyszín</button></div>':''}</div><p class="vw-help">Húzz ide raklapot vagy ládát. Kattintással a kijelölt rakományt rakodhatod át.</p><div class="vw-vehicles">${rows.map(l=>`<div class="vw-vehicle" role="button" tabindex="0" onclick="vwDestinationClick('${l.id}')" onkeydown="if(event.key==='Enter')vwDestinationClick('${l.id}')" ondragover="vwDragOver(event)" ondragleave="vwDragLeave(event)" ondrop="vwDrop(event,'destination','${l.id}')"><b>${l.kind==='site'?'⚑':'▰'} ${esc(l.name)}</b><small>${esc(l.registration||l.code)}</small><small>${vwPallets.filter(p=>p.location_id===l.id).length} raklap · ${logAssets(l.id).length} láda / eszköz</small><small>${l.kind==='vehicle'?(l.payload_kg===null?'Teherbírás nincs megadva':logNumber(l.payload_kg)+' kg teherbírás'):'Műveleti helyszín'}</small></div>`).join('')||'<p class="vw-help">Még nincs jármű vagy helyszín. A logisztikai adminisztrátor itt adhat hozzá.</p>'}</div></section>`;}
  function vwPool(){const q=logNormalize(vwPoolQuery),rows=logistics.assets.filter(a=>a.active&&!vwOnPallet(a.id)&&vwInWarehouse(a.location_id)&&(!q||logNormalize([a.code,a.name,...(a.contents||[]).map(i=>i.name)].join(' ')).includes(q)));return rows.map(a=>`<button class="vw-pool-card ${vwPicked?.id===a.id?'picked':''}" ${canManageLogistics()?'draggable="true"':''} ondragstart="vwDragStart(event,'asset','${a.id}')" ondragend="vwDragEnd()" onclick="vwPickAsset('${a.id}')">${logCrateGraphic(a)}<b>${esc(a.code)}</b><small>${esc(a.name)}</small><small>${logNumber(a.length_cm)} × ${logNumber(a.width_cm)} cm · ${logNumber(a.total_kg)} kg</small>${a.length_cm===null||a.width_cm===null?'<small class="log-warning">Raklapozáshoz méret szükséges</small>':''}</button>`).join('')||'<p class="vw-help">Nincs raklapozásra váró találat.</p>';}
  function vwPlan(p){const rows=vwContents(p.id);return `<div class="vw-plan" aria-label="${esc(p.code)} felülnézete, 120 × 80 centiméter" ondragover="vwDragOver(event)" ondragleave="vwDragLeave(event)" ondrop="vwPlanDrop(event,'${p.id}')">${rows.map(i=>{const a=vwAsset(i.asset_id),d=vwDims(a,i.rotated);return `<button class="vw-plan-crate ${a.category==='lighting'?'light':''} ${vwPicked?.id===a.id?'picked':''}" style="--crate:${logCrateColor(a)};left:${Number(i.x_cm)/120*100}%;top:${Number(i.y_cm)/80*100}%;width:${d.w/120*100}%;height:${d.h/80*100}%" ${canManageLogistics()?'draggable="true"':''} ondragstart="vwDragStart(event,'asset','${a.id}')" ondragend="vwDragEnd()" onclick="vwPickAsset('${a.id}')" title="${esc(a.code+' · '+a.name)}"><b>${esc(a.code)}</b><small>${d.w} × ${d.h} cm</small></button>`;}).join('')}</div><p class="vw-help" style="text-align:center">← 120 cm → · mélység: 80 cm · egyetlen ládaréteg</p>`;}
  function vwSelectedPanel(){const p=vwPal(vwSelected);if(!p)return '<h2>Raklap szerkesztése</h2><p class="vw-help">Hozz létre egy raklapot, vagy válassz egyet a rakodótéren vagy az állványon. Ezután húzd rá a ládákat.</p>';const rows=vwContents(p.id),a=vwPicked?.type==='asset'?vwAsset(vwPicked.id):null,placed=a?vwOnPallet(a.id):null;return `<div class="panel-head"><div><h2>${esc(p.code)}</h2><small class="vw-help">${esc(p.name)} · ${esc(logPath(p.location_id))}</small></div>${canManageLogistics()?`<button class="secondary" onclick="vwEditPallet('${p.id}')">Adatok</button>`:''}</div><p class="vw-help">${rows.length} láda · ${vwPalletWeight(p)}</p>${vwPlan(p)}${canManageLogistics()?`<div class="vw-controls"><label>X (cm)<input id="vwX" type="number" min="0" max="120" step="0.1" value="${placed?.pallet_id===p.id?placed.x_cm:0}"></label><label>Y (cm)<input id="vwY" type="number" min="0" max="80" step="0.1" value="${placed?.pallet_id===p.id?placed.y_cm:0}"></label><button class="secondary" onclick="vwRotate()">↻ ${vwRotation?'90°':'0°'} · Forgatás</button><button class="pill-btn" onclick="vwPlacePicked(false)">Pozíció mentése</button><button class="secondary" onclick="vwPlacePicked(true)">Szabad helyre teszem</button></div><p class="vw-help">${a?'Kijelölt láda: <b>'+esc(a.code)+'</b>':'Válassz vagy húzz ide egy ládát a listából.'}</p>`:''}${rows.map(i=>{const a=vwAsset(i.asset_id);return `<div class="vw-list-row"><div><b>${esc(a.code)}</b><small>${esc(a.name)}</small></div><div class="log-buttons"><button class="secondary" onclick="logAssetDetail('${a.id}')">Tartalom</button>${canManageLogistics()?`<button class="secondary" onclick="vwUnload('${a.id}','${vwWarehouse()?.id}')">Levétel</button>`:''}</div></div>`;}).join('')}<div class="vw-targets">${canManageLogistics()?`<button onclick="vwMoveDialog('${p.id}')">⇄ Raklap áthelyezése</button>`:''}<button onclick="vwPalletHistory('${p.id}')">◷ Raklap előzményei</button></div>`;}
  function vwPage(){vwStyles();const slots=logistics.locations.filter(l=>l.virtual_level),used=vwPallets.filter(p=>slots.some(s=>s.id===p.location_id)).length,loose=logistics.assets.filter(a=>a.active&&!vwOnPallet(a.id)&&vwInWarehouse(a.location_id)).length,wh=vwWarehouse();if(!vwPal(vwSelected))vwSelected=vwPallets[0]?.id||null;return `<div class="vw"><header class="vw-hero"><div><div class="eyebrow">HUNOR · VIRTUÁLIS RAKTÁR</div><h1>Raklapról polcra. Polcról útra.</h1><p>Fogd meg a ládát, tedd raklapra, majd húzd a raklapot a helyére.</p></div><span class="log-access">${canManageLogistics()?'Logisztikai adminisztrátor':'Megtekintési jogosultság'}</span></header><div class="vw-kpis"><div><small>Polchely</small><b>${slots.length}</b></div><div><small>Foglalt / szabad</small><b>${used} / ${slots.length-used}</b></div><div><small>Nyilvántartott raklap</small><b>${vwPallets.length}</b></div><div><small>Raklapra váró egység</small><b>${loose}</b></div></div>${logGlobalSearchBox()}<nav class="log-tabs">${[['warehouse','▦ Virtuális raktár'],['assets','▣ Ládák és eszközök'],['transport','⇄ Járművek és helyszínek'],['history','◷ Mozgási napló']].map(([id,label])=>`<button class="${logView===id?'active':''}" onclick="logSetView('${id}')">${label}</button>`).join('')}<button onclick="setPage('logistics')">↻ Frissítés</button></nav><div id="vwStatus" class="vw-status" role="status" aria-live="polite">${canManageLogistics()?'Húzással vagy kijelölés után a célhelyre kattintva is pakolhatsz.':'A raktár megtekinthető. Pakoláshoz logisztikai adminisztrátori jogosultság szükséges.'}</div>${logCrateLegend()}${vwRackMap()}<section class="panel" style="margin-top:22px"><div class="vw-floor-heading"><h2>Raktári rakodótér</h2>${canManageLogistics()?'<button class="pill-btn" onclick="vwEditPallet()">＋ Új EUR raklap</button>':''}</div><div class="vw-floor" ondragover="vwDragOver(event)" ondragleave="vwDragLeave(event)" ondrop="vwDrop(event,'destination','${wh?.id}')">${vwPallets.filter(p=>p.location_id===wh?.id).map(p=>vwMini(p)).join('')||'<p class="vw-help">Itt készítheted össze a raklapokat. Húzz ide raklapot a polcról a levételéhez.</p>'}</div></section><div class="vw-workgrid"><section class="panel" id="vwSelectedPanel">${vwSelectedPanel()}</section><section class="panel"><h2>Raklapozásra váró ládák</h2><p class="vw-help">Az importált tárolási besorolások megmaradtak. A valós polchelyet a raklap elhelyezésekor rögzítjük.</p><input class="vw-pool-search" type="search" value="${esc(vwPoolQuery)}" placeholder="Ládakód, név vagy tartalom…" aria-label="Raklapozásra váró ládák keresése" oninput="vwSearchPool(this.value)"><div id="vwPool" class="vw-pool">${vwPool()}</div></section></div>${vwVehicleTargets()}<p class="vw-bottom-note">A méretek alapján nem engedünk túllógást vagy átfedést. Hiányzó méretű és túlméretes egységeket az adatlapjukon lehet rendezni; önállóan továbbra is szállíthatók.</p></div>`;}
  const vwOriginalPage=window.logisticsPage;
  window.logisticsPage=function(){if(logView==='warehouse')return vwPage();vwStyles();const html=vwOriginalPage();if(logView==='transport'){const p=vwPallets.filter(p=>p.location_id===logLocation);return html+`<section class="panel vw"><h2>Az itt lévő raklapok (${p.length})</h2><div class="vw-floor">${p.map(p=>vwMini(p)).join('')||'<p>Még nincs raklap ezen a helyen.</p>'}</div>${vwSelected&&p.some(p=>p.id===vwSelected)?'<div id="vwSelectedPanel">'+vwSelectedPanel()+'</div>':''}${vwVehicleTargets()}</section>`;}return html;};
  function vwStatus(message,error=false){const el=document.querySelector('#vwStatus');if(el){el.textContent=message;el.classList.toggle('vw-error',error);}notify(message);}
  window.vwSetRack=n=>{vwRack=n;renderLogistics();};
  window.vwSelectPallet=id=>{vwSelected=id;vwPicked={type:'pallet',id};renderLogistics();};
  window.vwPickAsset=id=>{if(!canManageLogistics())return window.logAssetDetail(id);vwPicked={type:'asset',id};const placed=vwOnPallet(id);if(placed){vwSelected=placed.pallet_id;vwRotation=placed.rotated;}renderLogistics();};
  window.vwRotate=()=>{vwRotation=!vwRotation;const el=document.querySelector('#vwSelectedPanel');if(el)el.innerHTML=vwSelectedPanel();};
  window.vwSearchPool=q=>{vwPoolQuery=q;const el=document.querySelector('#vwPool');if(el)el.innerHTML=vwPool();};
  window.vwDragStart=(event,type,id)=>{if(!canManageLogistics()||vwBusy){event.preventDefault();return;}vwDrag={type,id};if(type==='asset'&&vwOnPallet(id))vwRotation=vwOnPallet(id).rotated;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',JSON.stringify(vwDrag));event.stopPropagation();};
  window.vwDragEnd=()=>{vwDrag=null;document.querySelectorAll('.vw-drop-hover').forEach(el=>el.classList.remove('vw-drop-hover'));};
  window.vwDragOver=event=>{if(!canManageLogistics()||!vwDrag||vwBusy)return;event.preventDefault();event.stopPropagation();event.dataTransfer.dropEffect='move';event.currentTarget.classList.add('vw-drop-hover');};
  window.vwDragLeave=event=>event.currentTarget.classList.remove('vw-drop-hover');
  window.vwDropOnPallet=async(event,id)=>{event.preventDefault();event.stopPropagation();const item=vwDrag;window.vwDragEnd();if(item?.type!=='asset')return vwStatus('A raklapra ládát húzz.',true);const a=vwAsset(item.id),pos=vwAutoFit(id,a);if(!pos)return vwStatus('Nincs megfelelő szabad hely ezen a raklapon.',true);await vwAttach(id,a.id,pos.x,pos.y,pos.rotated);};
