  function wfNav(){return `<nav class="wf-nav" aria-label="Logisztikai nézetek">${[['warehouse','▦ Raktározás'],['workflow','⇢ Indulás és visszaérkezés'],['transport','⇄ Járművek és helyszínek'],['assets','▣ Ládák és eszközök'],['history','◷ Mozgási napló']].map(([id,label])=>`<button class="${logView===id?'active':''}" onclick="logSetView('${id}')">${label}</button>`).join('')}<button onclick="setPage('logistics')" aria-label="Logisztikai adatok frissítése">↻ Frissítés</button></nav>`;}
  function wfSteps(){return `<div class="wf-steps"><div class="wf-step"><b>01 · Összeállítás</b><small>Raklap kiválasztása, ládák elhelyezése és forgatása 3D-ben.</small></div><div class="wf-step"><b>02 · Raktározás</b><small>A kész raklap egy szabad polchelyre kerül.</small></div><div class="wf-step"><b>03 · Indulás</b><small>A szükséges ládák úthoz, majd szállítási palettára vagy járműre kerülnek.</small></div><div class="wf-step"><b>04 · Visszaérkezés</b><small>A ládák az eredeti összeállításba kerülnek vissza. A teljes raklap újra polcra tehető.</small></div></div>`;}
