  const wfOldRack=vwRackMap;
  vwRackMap=()=>wfOldRack().replace('Egy mező egy EUR raklaphely · a 4. szint van legfelül','Egy mező egy EUR raklaphely · a 4. szint van legfelül').replace('</div><div class="vw-scroll">',`${canManageLogistics()?'<button class="secondary" onclick="wfRackLimits()">Polcszint korlátai</button>':''}</div><div class="vw-scroll">`).replace('A polcok terhelhetőségét és szabad magasságát még nem adtuk meg.','A polcszintek szabad magassága és teherbírása megadható a korlátoknál.');
  vwPage=()=>{vwStyles();wfStyles();if(!vwPal(vwSelected))vwSelected=vwPallets[0]?.id||null;const wh=vwWarehouse(),slots=logistics.locations.filter(l=>l.virtual_level),used=vwPallets.filter(p=>logLoc(p.location_id)?.virtual_level).length,waiting=vwPallets.filter(p=>wfMissing(p.id).length).length;return `<div class="vw"><header class="vw-hero"><div><div class="eyebrow">HUNOR · LOGISZTIKAI KÖZPONT</div><h1>A raktártól a bevetésig.</h1><p>Állandó összeállítások, 3D rakodás és követhető visszaérkezés.</p></div><span class="log-access">${canManageLogistics()?'Logisztikai adminisztrátor':'Megtekintési jogosultság'}</span></header>${wfNav()}<div id="vwStatus" class="vw-status" role="status" aria-live="polite">Válassz raklapot, helyezd el a ládákat, majd tedd a kész összeállítást a polcra.</div>${wfSteps()}<div class="vw-kpis"><div><small>Foglalt polchely</small><b>${used} / ${slots.length}</b></div><div><small>Raktári raklap</small><b>${vwPallets.filter(p=>p.purpose==='storage').length}</b></div><div><small>Visszaérkezésre vár</small><b>${waiting}</b></div><div><small>Aktív út</small><b>${wfMissions.filter(m=>m.status!=='closed').length}</b></div></div>${logGlobalSearchBox()}${logCrateLegend()}${vwRackMap()}<section class="panel" style="margin-top:22px"><div class="vw-floor-heading"><h2>Raktári rakodótér</h2>${canManageLogistics()?'<button class="pill-btn" onclick="vwEditPallet()">＋ Raktári raklap</button>':''}</div><p class="wf-small">A hiányos raklapok itt várnak. A teljes összeállítást húzd egy szabad polchelyre, vagy használd az áthelyezés gombot.</p><div class="vw-floor" ondragover="vwDragOver(event)" ondragleave="vwDragLeave(event)" ondrop="vwDrop(event,'destination','${wh?.id}')">${vwPallets.filter(p=>p.location_id===wh?.id&&p.purpose==='storage').map(p=>vwMini(p)).join('')||'<p class="vw-help">Hozz létre raklapot, vagy vegyél le egyet a polcról.</p>'}</div></section><div class="vw-workgrid"><section class="panel" id="vwSelectedPanel">${vwSelectedPanel()}</section>${wfPoolPanel()}</div>${vwVehicleTargets()}</div>`;};
  function wfMissionCards(){return wfMissions.slice().sort((a,b)=>(a.status==='closed')-(b.status==='closed')||b.created_at.localeCompare(a.created_at)).map(m=>{const lines=wfLines.filter(i=>i.mission_id===m.id),out=lines.filter(i=>!i.returned_at).length;return `<button class="wf-mission-card ${m.id===wfMission?'active':''}" onclick="wfSelectMission('${m.id}')"><span class="wf-badge ${m.status==='closed'?'complete':''}">${m.status==='closed'?'Lezárva':m.status==='active'?'Folyamatban':'Előkészítés'}</span><b>${esc(m.name)}</b><small>${esc(wfKinds[m.kind])}${m.starts_on?' · '+esc(m.starts_on):''}</small><small>${lines.length} láda · ${out} visszaérkezésre vár</small></button>`;}).join('')||'<p class="wf-empty">Még nincs logisztikai út. A gyakorlat, képzés, bevetés vagy bemutató rakománya külön listában követhető.</p>';}
  function wfCheckoutRows(){const q=logNormalize(wfQuery);return logistics.assets.filter(a=>a.active&&vwInWarehouse(a.location_id)&&!wfLine(a.id)&&(!q||logNormalize([a.code,a.name,vwAssetPath(a),...(a.contents||[]).map(i=>i.name)].join(' ')).includes(q))).map(a=>`<label class="wf-pick-row"><input type="checkbox" ${wfChoose.has(a.id)?'checked':''} onchange="wfChooseAsset('${a.id}',this.checked)"><span><b>${esc(a.code)} · ${esc(a.name)}</b><small>${esc(vwAssetPath(a))} · ${logNumber(a.total_kg)} kg</small></span></label>`).join('')||'<p class="wf-small" style="padding:15px">Nincs indítható találat.</p>';}
  function wfLineState(line){if(line.returned_at)return 'Visszaérkezett';const a=vwAsset(line.asset_id),p=vwPal(vwOnPallet(a.id)?.pallet_id),loc=logLoc(a.location_id);return (loc?.kind==='vehicle'?'Járművön':loc?.kind==='site'?'Helyszínen':'Rakodótéren')+(p?' · '+p.code:' · raklap nélkül');}
  function wfMissionContent(){const m=wfMissionRow();if(!m)return '<div class="wf-empty">Válassz vagy hozz létre utat. Ezután kiválaszthatod az induló ládákat.</div>';const lines=wfLines.filter(i=>i.mission_id===m.id),open=lines.filter(i=>!i.returned_at),closed=m.status==='closed';return `<section class="panel"><div class="wf-mission-header"><div><span class="wf-badge">${esc(wfKinds[m.kind])}</span><h2 style="margin:12px 0">${esc(m.name)}</h2><p class="wf-small">${esc([m.starts_on,m.ends_on].filter(Boolean).join(' – '))}${m.event_id?' · Eseményhez kapcsolva':''}</p></div>${canManageLogistics()?`<div class="log-buttons"><button class="secondary" onclick="wfEditMission('${m.id}')">Út adatai</button>${!closed?`<button class="secondary" onclick="wfCloseMission()" ${open.length?'disabled':''}>Út lezárása</button>`:''}</div>`:''}</div>${m.notes?'<p class="wf-small">'+esc(m.notes)+'</p>':''}<div class="wf-pallet-meta"><span>${lines.length} láda összesen</span><span>${open.length} visszaérkezésre vár</span><span>${lines.length-open.length} visszaérkezett</span></div><div class="wf-mission-actions"><button class="secondary" onclick="wfExportMission()">↓ Út rakodási listája</button><button class="secondary" onclick="wfMissionHistory('${m.id}')">◷ Út naplója</button></div>${!closed&&canManageLogistics()?`<details ${!lines.length?'open':''}><summary style="padding:14px 0;cursor:pointer;font-weight:700">＋ Ládák kiválasztása az induláshoz</summary><p class="wf-small">A program leveszi az érintett raklapot a polcról, és csak a kijelölt ládákat veszi le róla. A hiányos raklap a raktárban marad.</p><input class="vw-pool-search" type="search" value="${esc(wfQuery)}" placeholder="Ládakód, név vagy tartalom…" oninput="wfFilterCheckout(this.value)" aria-label="Induló ládák keresése"><div class="wf-picklist" id="wfCheckoutRows">${wfCheckoutRows()}</div><p class="wf-small" id="wfChosenSummary">${wfChoose.size} láda kijelölve${wfChoose.size?' · '+[...wfChoose].map(id=>esc(vwAsset(id)?.code||'')).join(', '):''}</p><button class="pill-btn" id="wfCheckoutButton" onclick="wfCheckout()" ${wfChoose.size?'':'disabled'}>Kijelölt ládák levétele a rakodótérre</button></details>`:''}<h3 style="margin-top:25px">Az út rakománya</h3>${open.length&&canManageLogistics()?'<label class="wf-small"><input type="checkbox" onchange="wfSelectAllReturns(this.checked)"> Minden vissza nem érkezett láda kijelölése</label>':''}<div class="wf-picklist">${lines.map(line=>{const a=vwAsset(line.asset_id),home=vwPal(line.home_pallet_id);return `<div class="wf-pick-row">${!line.returned_at&&canManageLogistics()?`<input type="checkbox" aria-label="${esc(a.code)} kijelölése mozgatáshoz" data-return="${a.id}" ${wfReturn.has(a.id)?'checked':''} onchange="wfReturnAsset('${a.id}',this.checked)">`:'<span style="flex:none">✓</span>'}<span><b>${esc(a.code)} · ${esc(a.name)}</b><small>${esc(wfLineState(line))} · ${esc(logPath(a.location_id))}</small><small>${home?'Eredeti raklap: '+esc(home.code):'Önálló raktári egység'} · ${logNumber(a.total_kg)} kg</small></span><button class="secondary" onclick="logAssetDetail('${a.id}')">Adatlap</button></div>`;}).join('')||'<p class="wf-small" style="padding:15px">Még nincs láda az úthoz rendelve.</p>'}</div>${!closed&&canManageLogistics()?`<div class="wf-mission-actions"><button class="secondary" onclick="wfMoveSelectedLoose()">⇢ Kijelöltek raklap nélkül</button><button class="pill-btn" onclick="wfReturnSelected()">↩ Kijelöltek visszaérkeztek</button></div><p class="wf-small">A visszaérkezés rögzítése az eredeti pozíciókba teszi a ládákat. Egymásra pakolt ládáknál először az alsókat, vagy az egész oszlopot együtt hozd vissza.</p>`:''}</section>`;}
  function wfTransportPallets(){const p=vwPallets.filter(p=>p.purpose==='transport');return `<section class="panel"><div class="vw-floor-heading"><h2>Szállítási paletták</h2>${canManageLogistics()?'<button class="pill-btn" onclick="vwEditPallet(null,\'transport\')">＋ Szállítási paletta</button>':''}</div><p class="wf-small">Válassz célpalettát. A ládák közvetlenül átrakodhatók például a teherautó EUR palettájáról a repülőgép NATO / 463L palettájára.</p><div class="vw-floor">${p.map(p=>vwMini(p)).join('')||'<p class="vw-help">Még nincs szállítási paletta.</p>'}</div></section>`;}
  function wfWorkflowPage(){vwStyles();wfStyles();if(!wfMissionRow())wfMission=wfMissions.find(m=>m.status!=='closed')?.id||wfMissions[0]?.id||null;return `<div class="vw"><header class="vw-hero"><div><div class="eyebrow">HUNOR · INDULÁS ÉS VISSZAÉRKEZÉS</div><h1>Minden láda útja követhető.</h1><p>Kiválasztás → rakodótér → szállítás → vissza az eredeti összeállításba.</p></div>${canManageLogistics()?'<button class="pill-btn" onclick="wfEditMission()">＋ Új út / művelet</button>':''}</header>${wfNav()}<div id="vwStatus" class="vw-status" role="status" aria-live="polite">A hiányos raktári raklapok a ládák visszaérkezéséig nem kerülhetnek polcra.</div><div class="wf-mission-grid" style="margin-top:20px"><aside class="wf-mission-cards">${wfMissionCards()}</aside><div>${wfMissionContent()}</div></div><div style="margin-top:22px">${wfTransportPallets()}</div>${vwPal(vwSelected)?.purpose==='transport'?`<div class="vw-workgrid"><section class="panel" id="vwSelectedPanel">${vwSelectedPanel()}</section>${wfPoolPanel()}</div>`:''}${vwVehicleTargets()}</div>`;}
  window.logSetView=v=>{if(!['warehouse','assets','transport','history','workflow'].includes(v))return;logView=v;logSelected.clear();if(v==='warehouse'&&['site','vehicle'].includes(logLoc(logLocation)?.kind))logLocation=vwWarehouse()?.id;if(v==='transport'&&!['site','vehicle'].includes(logLoc(logLocation)?.kind))logLocation=logistics.locations.find(l=>l.active&&['vehicle','site'].includes(l.kind))?.id||null;renderLogistics();};
  window.logisticsPage=()=>{if(logView==='warehouse')return vwPage();if(logView==='workflow')return wfWorkflowPage();vwStyles();wfStyles();let html=vwOriginalPage().replace(/<nav class="log-tabs">[\s\S]*?<\/nav>/,'');if(logView==='transport'){const pals=vwPallets.filter(p=>p.location_id===logLocation);html+=`<section class="panel vw" style="margin-top:20px"><div class="panel-head"><h2>Az itt lévő paletták</h2>${canManageLogistics()?'<button class="pill-btn" onclick="vwEditPallet(null,\'transport\')">＋ Paletta</button>':''}</div><div class="vw-floor">${pals.map(p=>vwMini(p)).join('')||'<p class="vw-help">Még nincs paletta ezen a helyen.</p>'}</div></section>${vwSelected?`<div class="vw-workgrid vw"><section class="panel" id="vwSelectedPanel">${vwSelectedPanel()}</section>${wfPoolPanel()}</div>`:''}`;}return '<div class="vw">'+wfNav()+'<div id="vwStatus" class="vw-status" role="status" aria-live="polite">Ládák, paletták és járművek nyilvántartása.</div>'+html+'</div>';};
  async function wfRun(action,data,message,options={}){if(vwBusy||logBusy||!canManageLogistics())return false;const actor=user?.id;vwBusy=true;let saved=false;const status=options.form?.querySelector('[role=status]'),button=options.form?.querySelector('[type=submit]');if(button)button.disabled=true;if(status)status.textContent='Mentés…';try{const {data:result,error}=await sb.rpc(action==='warehouse_stage'?'hunor_warehouse_stage':'hunor_logistics_workflow',action==='warehouse_stage'?{p_data:data}:{p_action:action,p_data:data});if(error)throw error;saved=true;if(user?.id!==actor)return false;await loadLogistics();if(user?.id!==actor)return false;if(options.pallet&&result)vwSelected=result;if(options.mission&&result)wfMission=result;if(options.clearChoose)wfChoose.clear();if(options.clearReturn)wfReturn.clear();if(options.close)closeModal();renderLogistics();vwStatus(message);return true;}catch(e){const text=saved?'A módosítás mentve, de a nézet frissítése nem sikerült. Nyisd meg újra a Logisztika fület.':e.message||'A művelet nem menthető.';if(user?.id===actor){if(status)status.textContent=text;vwStatus(text,true);}return false;}finally{vwBusy=false;if(button&&!saved)button.disabled=false;}}
  vwAttach=async(palletId,assetId,x,y,rotated,z=0)=>{const p=vwPal(palletId),a=vwAsset(assetId),src=vwPal(vwOnPallet(assetId)?.pallet_id);if(!p||!a)return;if(!vwFits(palletId,a,x,y,rotated,z))return vwStatus('Ezen a helyen a láda túllóg, ütközik, nincs teljesen alátámasztva, vagy túllépi a réteg-/terhelési korlátot. Ellenőrizd a méreteket és a láda adatlapját.',true);const ok=await wfRun('place',{pallet:p.id,version:p.version,asset:a.id,asset_version:a.version,source_version:src?.version??null,x:wfRound(x),y:wfRound(y),z:wfRound(z),rotated,note:(src?src.code:'Önálló láda')+' → '+p.code+' · '+a.code},'A láda elhelyezése és a 3D pozíció mentve.',{pallet:true});if(ok){vwPicked={type:'asset',id:a.id};vwRotation=rotated;wfDropZ=z;renderLogistics();}};
  window.vwPlacePicked=async automatic=>{if(vwPicked?.type!=='asset'||!vwSelected)return vwStatus('Válassz célpalettát és ládát.',true);const a=vwAsset(vwPicked.id),pos=automatic?vwAutoFit(vwSelected,a):{x:Number(document.querySelector('#vwX')?.value),y:Number(document.querySelector('#vwY')?.value),z:Number(document.querySelector('#vwZ')?.value),rotated:vwRotation};if(!pos)return vwStatus('Nem találtam szabályos szabad helyet. Rendezd át a ládákat, vagy ellenőrizd a rétegkorlátokat.',true);await vwAttach(vwSelected,a.id,pos.x,pos.y,pos.rotated,pos.z);};
  window.vwPickAsset=id=>{if(!canManageLogistics())return window.logAssetDetail(id);vwPicked={type:'asset',id};const i=vwOnPallet(id);if(!vwSelected&&i)vwSelected=i.pallet_id;vwRotation=i?.rotated||false;wfDropZ=i?.pallet_id===vwSelected?Number(i.z_cm):0;renderLogistics();};
  window.vwSelectPallet=id=>{vwSelected=id;vwPicked={type:'pallet',id};wfDropZ=0;renderLogistics();};
  window.vwRotate=()=>{vwRotation=!vwRotation;const x=document.querySelector('#vwX')?.value,y=document.querySelector('#vwY')?.value,z=document.querySelector('#vwZ')?.value,el=document.querySelector('#vwSelectedPanel');if(el){el.innerHTML=vwSelectedPanel();if(document.querySelector('#vwX')){document.querySelector('#vwX').value=x;document.querySelector('#vwY').value=y;document.querySelector('#vwZ').value=z;}}};
  vwMovePallet=async(id,destination)=>{const p=vwPal(id),dest=logLoc(destination);if(!p||!dest)return;if(p.location_id===destination)return;if(dest.virtual_level&&wfMissing(id).length)return vwStatus('A hiányos raklap csak minden láda visszaérkezése után tehető polcra.',true);await wfRun('pallet_move',{pallet:id,version:p.version,destination,...wfMissionData(),note:logPath(p.location_id)+' → '+logPath(destination)},'A paletta és teljes rakománya áthelyezve.',{pallet:true});};
  window.wfPalletStage=id=>vwMovePallet(id,vwWarehouse()?.id);
  vwMoveAsset=async(id,destination)=>{if(wfHome(id)&&!wfLine(id))return window.wfPrepare(id);await wfRun('loose_move',{...wfVersions([id]),destination,note:vwAsset(id).code+' · Raklap nélküli áthelyezés'},'A láda raklap nélkül az új helyre került.');};
  window.vwUnload=(id,destination)=>vwMoveAsset(id,destination);
  window.vwDropOnPallet=async(event,id)=>{event.preventDefault();event.stopPropagation();const drag=vwDrag;window.vwDragEnd();if(drag?.type!=='asset')return vwStatus('A palettára ládát tegyél.',true);const a=vwAsset(drag.id),pos=vwAutoFit(id,a);if(!pos)return vwStatus('Nem találtam szabályos szabad helyet ezen a palettán.',true);await vwAttach(id,a.id,pos.x,pos.y,pos.rotated,pos.z);};
  window.wfPrepare=id=>{wfChoose.add(id);logView='workflow';renderLogistics();vwStatus('Válassz vagy hozz létre utat, majd rögzítsd a kijelölt ládák levételét.');};
  window.wfUnassign=async id=>{if(!confirm('Kiveszed a(z) '+vwAsset(id).code+' ládát az állandó raktári összeállításból? A láda és tartalma megmarad a rakodótéren. Ideiglenes utazáshoz az Útra viszem gombot használd.'))return;await wfRun('unassign',wfVersions([id]),'A láda kikerült az állandó összeállításból; a készlete megmaradt.');};
  window.wfSelectMission=id=>{wfMission=id;wfReturn.clear();renderLogistics();};
  window.wfFilterCheckout=q=>{wfQuery=q;const el=document.querySelector('#wfCheckoutRows');if(el)el.innerHTML=wfCheckoutRows();};
  window.wfChooseAsset=(id,checked)=>{checked?wfChoose.add(id):wfChoose.delete(id);const el=document.querySelector('#wfChosenSummary'),button=document.querySelector('#wfCheckoutButton');if(el)el.textContent=wfChoose.size+' láda kijelölve'+(wfChoose.size?' · '+[...wfChoose].map(id=>vwAsset(id)?.code||'').join(', '):'');if(button)button.disabled=!wfChoose.size;};
  window.wfCheckout=async()=>{if(!wfMissionRow())return vwStatus('Válassz utat.',true);if(!wfChoose.size)return;await wfRun('checkout',{...wfMissionData(),...wfVersions([...wfChoose]),note:'Induló ládák levétele · '+wfMissionRow().name},'A kijelölt ládák az út rakományába és a rakodótérre kerültek. Az eredeti összeállítás megmaradt.',{mission:true,clearChoose:true});};
  window.wfReturnAsset=(id,checked)=>checked?wfReturn.add(id):wfReturn.delete(id);
  window.wfSelectAllReturns=checked=>{wfLines.filter(i=>i.mission_id===wfMission&&!i.returned_at).forEach(i=>checked?wfReturn.add(i.asset_id):wfReturn.delete(i.asset_id));document.querySelectorAll('[data-return]').forEach(el=>el.checked=wfReturn.has(el.dataset.return));};
  window.wfReturnSelected=async()=>{const ids=[...wfReturn].filter(id=>wfLines.some(i=>i.mission_id===wfMission&&i.asset_id===id&&!i.returned_at));if(!ids.length)return vwStatus('Jelöld ki a visszaérkezett ládákat.',true);if(!confirm(ids.length+' láda valóban visszaérkezett a raktárba? A rendszer az eredeti raklapjukra és pozíciójukba teszi vissza őket.'))return;await wfRun('return',{...wfMissionData(),...wfVersions(ids),note:'Visszaérkezés · '+wfMissionRow().name},'A visszaérkezés rögzítve. A ládák az eredeti összeállításukba kerültek.',{mission:true,clearReturn:true});};
  window.wfCloseMission=async()=>{if(!wfMissionRow()||!confirm('Lezárod ezt az utat? Minden ládának vissza kell érkeznie.'))return;await wfRun('mission_close',wfMissionData(),'Az út lezárva.',{mission:true});};
  window.wfEditMission=id=>{if(!canManageLogistics())return;const m=wfMissions.find(x=>x.id===id);openModal(`<div class="log-modal vw-modal"><div class="panel-head"><h2>${m?'Út adatainak szerkesztése':'Új logisztikai út / művelet'}</h2><button class="secondary" onclick="closeModal()">×</button></div><form onsubmit="wfSaveMission(event,${m?`'${m.id}'`:'null'})"><div class="log-form-grid">${logField('name','Út / művelet neve',m?.name||'','text','required maxlength="180"')}<label class="log-field">Típus<select name="kind">${logOptions(wfKinds,m?.kind||'exercise')}</select></label>${logField('starts','Indulás',m?.starts_on||'','date')}${logField('ends','Várható visszaérkezés',m?.ends_on||'','date')}<label class="log-field">Kapcsolódó esemény<select name="event"><option value="">Önálló út</option>${events.map(e=>`<option value="${e.id}" ${e.id===m?.event_id?'selected':''}>${esc(e.title||e.name||'Esemény')}</option>`).join('')}</select></label></div><label class="log-field">Megjegyzés<textarea name="notes" rows="3" maxlength="2000">${esc(m?.notes||'')}</textarea></label><button class="pill-btn" type="submit">${m?'Adatok mentése':'Út létrehozása'}</button><p role="status"></p></form></div>`);};
  window.wfSaveMission=async(event,id)=>{event.preventDefault();const form=event.currentTarget,f=new FormData(form),m=wfMissions.find(x=>x.id===id);await wfRun('mission_save',{mission:id,mission_version:m?.version??null,name:f.get('name'),kind:f.get('kind'),starts:f.get('starts'),ends:f.get('ends'),event:f.get('event'),notes:f.get('notes')},'A logisztikai út adatai mentve.',{form,mission:true,close:true});};
