  window.wfExportMission=()=>{const m=wfMissionRow();if(!m)return;const rows=[['Út','Típus','Ládakód','Láda','Jelenlegi hely','Szállítási paletta','Eredeti raklap','Polchely','X cm','Y cm','Z cm','Ládatömeg kg','Paletta saját tömege kg','Állapot']];wfLines.filter(i=>i.mission_id===m.id).forEach(line=>{const a=vwAsset(line.asset_id),i=vwOnPallet(a.id),p=vwPal(i?.pallet_id),h=vwPal(line.home_pallet_id);rows.push([m.name,wfKinds[m.kind],a.code,a.name,logPath(a.location_id),p?.code||'',h?.code||'',h?.home_slot_id?logPath(h.home_slot_id):'',i?.x_cm??'',i?.y_cm??'',i?.z_cm??'',a.total_kg??'',p?.tare_kg??'',wfLineState(line)]);});const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"',blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='HUNOR-ut-rakodasi-lista.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  window.wfMissionHistory=async id=>{const actor=user?.id;openModal(`<div class="log-modal vw-modal"><div class="panel-head"><h2>Út naplója</h2><button class="secondary" onclick="closeModal()">×</button></div><div id="wfMissionHistory" data-mission="${id}">Betöltés…</div></div>`);const {data,error}=await sb.from('logistics_mission_history').select('action,note,actor_name,created_at,snapshot').eq('mission_id',id).order('created_at',{ascending:false}).limit(100);const el=document.querySelector('#wfMissionHistory');if(user?.id!==actor||el?.dataset.mission!==id)return;const labels={mission_save:'Út adatai',checkout:'Induló ládák levétele',return:'Ládák visszaérkezése',mission_close:'Út lezárása',pallet_move:'Teljes raklap mozgatása'};el.innerHTML=error?'<p>A napló nem tölthető be.</p>':(data||[]).map(h=>`<div class="vw-list-row"><div><b>${esc(labels[h.action]||h.action)}</b><small>${esc(new Date(h.created_at).toLocaleString('hu-HU'))} · ${esc(h.actor_name)}</small><p>${esc(h.note)}</p><small>${(h.snapshot?.assets||[]).map(id=>esc(vwAsset(id)?.code||id)).join(' · ')}</small></div></div>`).join('')||'<p>Még nincs bejegyzés.</p>';};
