  vwVehicleTargets=()=>{const rows=logistics.locations.filter(l=>l.active&&['vehicle','site'].includes(l.kind));return `<section class="panel wl-target-panel" aria-label="Rakodási célok"><div class="panel-head"><div class="wl-target-heading"><span aria-hidden="true">⇢</span><h2>Rakodási célok</h2></div>${canManageLogistics()?'<div class="log-buttons"><button class="secondary" onclick="logEditLocation(\'vehicle\')">＋ Jármű</button><button class="secondary" onclick="logEditLocation(\'site\')">＋ Helyszín</button></div>':''}</div><p class="vw-help">Húzd a raklapot vagy a ládát a célkártyára. Kijelölés után a célra kattintva is átrakodhatsz.</p><div class="wl-target-summary" data-wl-summary>${wlSelectionSummary()}</div>${[['vehicle','Járművek'],['site','Helyszínek']].map(([kind,title])=>{const group=rows.filter(l=>l.kind===kind);return `<h3 class="wl-target-group">${title} · ${group.length}</h3><div class="wl-target-list">${group.map(wlTargetCard).join('')||'<p class="wl-target-empty">Még nincs felvett '+(kind==='vehicle'?'jármű.':'helyszín.')+'</p>'}</div>`;}).join('')}</section>`;};
