  function wlPaintTargets(){document.querySelectorAll('[data-wl-destination]').forEach(el=>{const selected=el.dataset.wlDestination===wlDestination;el.classList.toggle('selected',selected);el.classList.toggle('vw-drop-hover',el.dataset.wlDestination===wlHoverDestination);el.setAttribute('aria-pressed',String(selected));const flag=el.querySelector('[data-wl-selected]');if(flag)flag.hidden=!selected;});document.querySelectorAll('[data-wl-summary]').forEach(el=>el.innerHTML=wlSelectionSummary());}
