  window.wsPickForPallet=id=>{id=id||(vwPicked?.type==='asset'?vwPicked.id:null);if(!id||!canManageLogistics())return;const p=vwPal(vwSelected);if(!p)return vwStatus('A raklapra helyezéshez válassz vagy hozz létre raklapot. A rakodótér addig is használható.',true);if(logLoc(p.location_id)?.virtual_level)return vwStatus('Pakolás előtt vedd le a kiválasztott raklapot a polcról.',true);vwPickAsset(id);document.querySelector('#vwSelectedPanel')?.scrollIntoView({behavior:'smooth',block:'start'});window.wrArmPlacement(p.id);};
