  const wsReturnToPool=wlReturnToPool;
  wlReturnToPool=async id=>{const a=vwAsset(id);if(!a?.floor_staged||vwOnPallet(id))return wsReturnToPool(id);const plan=wlReturnPlan(id),actor=user?.id;wlClearPoolReturn();if(!plan.valid)return vwStatus(plan.reason,true);const text=a.code+' visszakerült a(z) '+plan.label+' várakozó fülbe.';const ok=await wfRun('warehouse_stage',{...wfVersions([id]),to_floor:false,note:a.code+' · Vissza a várakozó ládákhoz'},text);if(!ok||user?.id!==actor)return;vwPoolQuery='';wcPoolFilter=plan.type;if(plan.line)wfMission=plan.line.mission_id;renderLogistics();vwStatus(text);document.querySelector('[data-wl-pool-drop]')?.scrollIntoView({behavior:'smooth',block:'nearest'});};
