  window.wsFloorDragOver=event=>{if(!vwDrag||!canManageLogistics()||vwBusy)return;event.preventDefault();event.stopPropagation();if(vwDrag.type==='asset'){wrClear();const plan=wsShowFloor(vwDrag.id);event.dataTransfer.dropEffect=plan.valid?'move':'none';}else{event.dataTransfer.dropEffect='move';event.currentTarget.classList.add('ws-drop-valid');}};
