    return `<div class="vw lx lx-warehouse">${lxHeader('Raktári áttekintés','Polchelyek, raklapok és előkészített felszerelések egy helyen.')}<div class="lx-overview-stats"><div><span>Foglalt polchely</span><b>${used}<small> / ${slots.length}</small></b></div><div><span>Raktári raklap</span><b>${vwPallets.filter(p=>p.purpose==='storage').length}</b></div><div><span>Visszaérkezésre váró összeállítás</span><b>${vwPallets.filter(p=>wfMissing(p.id).length).length}</b></div></div>${logGlobalSearchBox()}<div class="lx-rack-layout"><div>${vwRackMap()}</div><aside class="panel lx-pallet-summary"><span class="eyebrow">KIVÁLASZTOTT RAKLAP</span>${p?`<h2>${esc(p.code)}</h2><p>${esc(p.name)}</p><dl><dt>Hely</dt><dd>${esc(logPath(p.location_id))}</dd><dt>Ládák</dt><dd>${vwContents(p.id).length} db</dd><dt>Össztömeg</dt><dd>${vwPalletWeight(p)}</dd><dt>Méret</dt><dd>${logNumber(p.length_cm)} × ${logNumber(p.width_cm)} cm</dd></dl><button class="pill-btn" onclick="lxOpenAssembly('${p.id}')">Megnyitás a raklapépítőben →</button>${canManageLogistics()?`<button class="secondary" onclick="vwMoveDialog('${p.id}')">Raklap áthelyezése</button>`:''}`:'<h2>Válassz raklapot</h2><p>Kattints a polcrendszer vagy a rakodótér egyik raklapjára.</p><button class="secondary" onclick="lxOpenAssembly()">Raklapépítő megnyitása</button>'}</aside></div>${lxFloor()}<details class="lx-legend"><summary>Ládatípusok színjelölése</summary>${logCrateLegend()}</details></div>`;
