  deLoadSelf=async function(force=false){const actor=user?.id;if(!actor||guest||user.membershipStatus!=='approved'){deActor=null;deSelf=null;deSequence++;deRequest=null;deRender();return;}if(deActor===actor&&Date.now()-deLoaded<60000&&!force)return;if(deRequest?.actor===actor&&!force)return deRequest.promise;const sequence=++deSequence,promise=(async()=>{const [dates,controls]=await Promise.all([sb.from('member_private_details').select('vaccinations,'+deDocs.map(d=>d[0]).join(',')).eq('member_id',actor).maybeSingle(),sb.from('member_document_controls').select('alertability_locked,passport_override_for,review_note').eq('member_id',actor).maybeSingle()]);if(actor!==user?.id||sequence!==deSequence)return;if(dates.error||controls.error){console.warn('A lejárati adatok nem frissíthetők.');return;}deSelf={...(dates.data||{}),documentControl:controls.data};deActor=actor;deLoaded=Date.now();deRender();mdPaintLocks();})();deRequest={actor,promise};try{await promise;}finally{if(deRequest?.promise===promise)deRequest=null;}};
  deRender=function(){const existing=document.querySelector('#deSelfNotice');if(deActor!==user?.id||user?.membershipStatus!=='approved'||guest||siteLocked&&!user.isAdmin){existing?.remove();return;}const rows=deRows(deSelf,true),lock=mdLocked(deSelf);if(!rows&&!lock){existing?.remove();return;}const expired=mdExpiryItems(deSelf).some(x=>deState(x.value,x.key).tone==='expired'),notice=document.createElement('section');notice.id='deSelfNotice';notice.className='de-notice '+(expired||lock?'de-expired':'de-soon');notice.setAttribute('role','status');notice.innerHTML=`<div class="de-notice-head"><div><b>${lock?'Riaszthatóságod felülvizsgálatra vár':expired?'Lejárt iratod vagy oltásod van':'Közelgő irat- vagy oltáslejárat'}</b><p>${lock?'A szolgálati útlevél miatti korlátozást csak admin vagy tagságkezelő oldhatja fel.':'Ellenőrizd az adatokat a profilodban. Szolgálati útlevélnél 9 hónappal, a többi érvényességnél egy hónappal korábban jelzünk.'}</p></div><button class="secondary" onclick="deOpenDocuments()">Profil megnyitása →</button></div>${rows}`;if(existing&&existing.className===notice.className&&existing.innerHTML===notice.innerHTML)return;existing?.remove();content.prepend(notice);};
  personalInput=function(name,label,value,type='text',extra=''){if(!deDocs.some(([k])=>k===name))return dePersonalInput(name,label,value,type,extra);const state=deState(value,name);return `<div class="field de-date-field de-${state.tone}"><label for="private_${name}">${label}</label><input id="private_${name}" name="${name}" type="date" min="1900-01-01" max="2200-12-31" value="${esc(value||'')}" oninput="dePaintInputs()"><small data-de-state>${state.text}</small></div>`;};
  window.dePaintInputs=()=>document.querySelectorAll('.de-date-field').forEach(field=>{const input=field.querySelector('input'),state=deState(input.value,input.name);field.className='field de-date-field de-'+state.tone;field.querySelector('[data-de-state]').textContent=state.text;});
  const mdBasePermissionPanel=hpPermissionPanel;
  hpPermissionPanel=member=>`<details class="md-fold md-permissions"><summary><span>Szerepkörök és jogosultságok</span><b>${hpGrants(member).filter(r=>r!=='member').length+[member.canUploadEducation,member.canManageLogistics,member.canEditNews,member.canAccessExcon].filter(Boolean).length} extra</b></summary><div class="md-fold-body">${mdBasePermissionPanel(member)}</div></details>`;
  const mdMembersPage=window.membersPage;
  window.membersPage=()=>{const template=document.createElement('template');template.innerHTML=mdMembersPage();template.content.querySelectorAll('.member-card').forEach(card=>{const member=members.find(m=>m.id===card.dataset.memberId),d=member?.documentExpiries||(member?.id===user?.id?deSelf:null);if((mdManage()||member?.id===user?.id)&&d?.service_passport_expires_on&&d.service_passport_expires_on<deToday()){card.classList.add('md-passport-expired');const flag=document.createElement('p');flag.className='md-expired-flag';flag.textContent='Lejárt szolgálati útlevél';card.querySelector('.member-top').after(flag);}if(mdLocked(d))card.querySelectorAll('.alertability-actions button').forEach(b=>{b.disabled=true;b.title='Adminisztrátori vagy tagságkezelői felülvizsgálat szükséges.';});});if(user?.isAdmin){const title=template.content.querySelector('.page-title'),button=document.createElement('button');button.className='secondary';button.textContent='Lejárati e-mailek';button.setAttribute('onclick','mdMailSettings()');title?.append(button);}return template.innerHTML;};
  function mdPaintLocks(){const select=document.querySelector('#myProfileAlertability'),lock=deActor===user?.id&&mdLocked(deSelf);if(!select)return;select.disabled=lock||profileSaving;select.closest('.profile-section')?.querySelector('.md-lock-message')?.remove();if(lock){const hint=document.createElement('p');hint.className='md-lock-message';hint.textContent='A szolgálati útlevél miatt az állapot zárolt. Csak admin vagy tagságkezelő módosíthatja a felülvizsgálatnál.';select.closest('.profile-section')?.append(hint);}}
  const mdSetPage=window.setPage;
