  const mdProfilePage=window.profilePage;
  window.profilePage=()=>{const html=mdProfilePage();if(!mdLocked(myProfile))return html;return html.replace('id="myProfileAlertability" name="alertable"','id="myProfileAlertability" name="alertable" disabled').replace('<section class="profile-section"><h2>Riaszthatóság</h2>','<section class="profile-section"><h2>Riaszthatóság</h2><p class="md-lock-message">A szolgálati útlevél miatt zárolt. Adminisztrátori vagy tagságkezelői felülvizsgálat szükséges.</p>');};
  const mdSetAlertability=window.setMyAlertability;
  // Only the own availability row is used here. Server document restrictions still apply.
  window.setMyAlertability=async value=>mdSetAlertability(value);
  window.selfAlertabilityPanel=()=>user?.membershipStatus==='approved'?'<section class="alertability-reminder"><span class="reminder-symbol" aria-hidden="true">◉</span><div><h2>Saját riaszthatóságod</h2><p>A riasztható / nem riasztható állapotodat itt külön hitelesítés nélkül módosíthatod.</p></div><button type="button" class="pill-btn" onclick="openMyAlertability()">Saját riaszthatóság beállítása →</button></section>':'';
  window.openMyAlertability=async()=>{
    if(user?.membershipStatus!=='approved')return;
    const actor=user.id;
    openModal('<div class="modal-head"><h2>Saját riaszthatóság</h2><button type="button" class="close" onclick="closeModal()" aria-label="Bezárás">×</button></div><p id="selfAlertabilityStatus" role="status" aria-live="polite">Állapot betöltése…</p><div class="alertability-actions"><button type="button" class="pill-btn" id="selfAlertabilityYes" disabled>Riasztható vagyok</button><button type="button" class="secondary" id="selfAlertabilityNo" disabled>Most nem vagyok riasztható</button></div>');
    const status=document.querySelector('#selfAlertabilityStatus'),yes=document.querySelector('#selfAlertabilityYes'),no=document.querySelector('#selfAlertabilityNo');
    const {data,error}=await sb.from('member_alertability').select('is_alertable').eq('member_id',actor).maybeSingle();
    if(user?.id!==actor||!status?.isConnected)return;
    if(error){status.textContent='Nem sikerült betölteni az állapotot. Zárd be az ablakot és próbáld újra.';return;}
    status.textContent='Jelenlegi állapot: '+(data?.is_alertable===true?'Riasztható':data?.is_alertable===false?'Nem riasztható':'Nincs beállítva');
    yes.disabled=false;no.disabled=false;yes.setAttribute('aria-pressed',String(data?.is_alertable===true));no.setAttribute('aria-pressed',String(data?.is_alertable===false));
    const save=async value=>{
      if(user?.id!==actor||yes.disabled)return;
      yes.disabled=true;no.disabled=true;status.textContent='Mentés…';
      try{const saved=await window.setMyAlertability(value);if(saved&&status.isConnected)closeModal();else if(status.isConnected){status.textContent='Az állapot nem módosult. Ellenőrizd a hibaüzenetet; iratok miatti korlátozásnál az admin vagy tagságkezelő tud segíteni.';}}
      catch{if(status.isConnected)status.textContent='A mentés nem sikerült. Próbáld újra.';}
      finally{if(status.isConnected){yes.disabled=false;no.disabled=false;}}
    };
    yes.onclick=()=>save(true);no.onclick=()=>save(false);
  };
  deAfterPrivateSave=async function(id,payload){const actor=user?.id,[dates,availability]=await Promise.all([deReadMembers([id]),sb.from('member_alertability').select('is_alertable').eq('member_id',id).maybeSingle()]);if(user?.id!==actor)return;const member=members.find(m=>m.id===id);if(member){member.documentExpiries=dates.data?.[0]||{...payload,documentControl:member.documentExpiries?.documentControl};member.documentExpiryError=Boolean(dates.error);if(availability.data)member.alertable=availability.data.is_alertable;const card=document.querySelector('[data-member-id="'+id+'"]');if(card){const old=card.querySelector('.de-member'),wasOpen=old?.open;if(old){old.outerHTML=deMemberStatus(member);card.querySelector('.de-member').open=wasOpen;}card.classList.toggle('md-passport-expired',Boolean(payload.service_passport_expires_on&&payload.service_passport_expires_on<deToday()));const state=card.querySelector('.alertability-state');if(state&&member.alertable===false){state.className='alertability-state alertable-no';state.textContent='Nem riasztható';}}}if(id===actor)await deLoadSelf(true);};
  window.mdReviewAlertability=id=>{if(!mdManage())return;const member=members.find(m=>m.id===id);if(!member)return;openModal(`<div class="private-member-details"><div class="modal-head"><h2>Riaszthatóság · ${esc(member.name)}</h2><button class="close" onclick="closeModal()" aria-label="Bezárás">×</button></div><p class="profile-help">A lejárt szolgálati útlevél miatti tiltás feloldásához ellenőrizd a tag iratait. A döntést és az indoklást rögzítjük.</p><form id="mdReviewForm"><label class="field">Állapot<select name="alertable"><option value="false">Nem riasztható</option><option value="true">Riasztható · korlátozás feloldása</option></select></label><label class="field">Felülvizsgálat indoklása<textarea name="note" required minlength="3" maxlength="1000" rows="3" placeholder="Pl. megújított útlevél ellenőrizve"></textarea></label><button class="pill-btn" type="submit">Döntés mentése</button><p role="status" id="mdReviewStatus"></p></form></div>`);document.querySelector('#mdReviewForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,values=Object.fromEntries(new FormData(form)),status=form.querySelector('[role=status]');form.querySelectorAll('input,select,textarea,button').forEach(e=>e.disabled=true);status.textContent='Mentés…';try{const {error}=await sb.rpc('hunor_review_document_alertability',{p_member:id,p_alertable:values.alertable==='true',p_note:values.note.trim()});if(error)throw error;closeModal();await window.setPage('members');notify('A felülvizsgálat mentve.');}catch(e){status.textContent=e.message;form.querySelectorAll('input,select,textarea,button').forEach(e=>e.disabled=false);}};};

  function mdVaccinationCard(v={},i=0){const id=v.id||crypto.randomUUID(),state=deState(v.expires_on);return `<section class="md-vaccination de-${state.tone}" data-vaccine-id="${esc(id)}"><div class="md-vaccine-head"><h3>${i+1}. oltás</h3><button type="button" class="secondary" onclick="mdRemoveVaccine(this)">Eltávolítás</button></div><div class="profile-fields"><label class="field">Oltás neve<input data-vaccine="name" required maxlength="160" value="${esc(v.name||'')}" placeholder="Oltóanyag / oltás neve"></label><label class="field">Beadási dátum<input data-vaccine="given_on" type="date" min="1900-01-01" max="2200-12-31" value="${esc(v.given_on||'')}"></label><label class="field">Érvényesség vége<input data-vaccine="expires_on" type="date" min="1900-01-01" max="2200-12-31" value="${esc(v.expires_on||'')}" oninput="mdVaccineStatus(this)"><small data-vaccine-status>${state.text}</small></label></div></section>`;}
  function mdVaccinationPanel(p){return `<div id="personal-panel-vaccinations" class="personal-profile-panel" role="tabpanel" aria-labelledby="personal-tab-vaccinations" ${personalProfileTab!=='vaccinations'?'hidden':''}><h2>Oltási könyv</h2><p class="profile-help private-access-note">Oltásonként külön név, beadási dátum és érvényesség. Az adatokat csak te, az admin és a tagságkezelő látja. Lejárat előtt egy hónappal figyelmeztetünk. A dátumokat az oltási dokumentum alapján add meg.</p><div id="mdVaccinations">${(p.vaccinations||[]).map(mdVaccinationCard).join('')}</div><button class="secondary" type="button" onclick="mdAddVaccine()">＋ Oltás hozzáadása</button><p class="profile-help">A változtatások a teljes adatlap mentésekor kerülnek rögzítésre.</p></div>`;}
  window.mdAddVaccine=()=>{const list=document.querySelector('#mdVaccinations');if(!list||profileSaving||list.closest('form')?.querySelector('button[type=submit]:disabled'))return;if(list.children.length>=100)return notify('Legfeljebb 100 oltás adható meg.');list.insertAdjacentHTML('beforeend',mdVaccinationCard({},list.children.length));list.lastElementChild.querySelector('input').focus();};
