  function mdVaccineReadOnly(p){return `<section><h3>Oltási könyv</h3>${(p.vaccinations||[]).map(v=>`<div class="de-row de-${deState(v.expires_on).tone}"><b>${esc(v.name)}</b><span>Beadás: ${esc(deDate(v.given_on))}</span><span>Érvényesség: ${esc(deDate(v.expires_on))}</span><small>${deState(v.expires_on).text}</small></div>`).join('')||'<p>Még nincs rögzített oltás.</p>'}</section>`;}

  window.mdMailSettings=async()=>{if(!user?.isAdmin)return;const actor=user.id;openModal(`<div class="private-member-details"><div class="modal-head"><h2>Lejárati e-mailek</h2><button class="close" onclick="closeModal()" aria-label="Bezárás">×</button></div><div id="mdMailBody">Betöltés…</div></div>`);const body=document.querySelector('#mdMailBody'),{data,error}=await sb.rpc('hunor_document_mail_status');if(actor!==user?.id||!body.isConnected)return;if(error){body.textContent=error.message;return;}const labels={pending:'Küldésre vár',sending:'Küldés folyamatban',accepted:'Szolgáltató átvette',failed:'Sikertelen',unknown:'Ellenőrzés szükséges'};body.innerHTML=`<p class="md-mail-state">${data.enabled?'Automatikus küldés bekapcsolva':'Automatikus küldés nincs bekapcsolva'} · ${data.pending} várakozó · ${data.accepted} szolgáltató által átvett · ${data.failed} hibás</p><p class="profile-help">A tag a regisztrált e-mail-címére kap értesítést. A központi összesítő címzettje: hun01.usar@gmail.com. Irat- és adóazonosító szám nem kerül a levélbe. A szolgáltatói átvétel még nem igazolja a postaládába érkezést.</p><details class="md-fold"><summary>Levélküldés beállítása · Resend</summary><div class="md-fold-body"><ol class="md-mail-guide"><li>Hozz létre Resend-fiókot, és igazold a hun01usar.hu küldési domaint a megadott DNS-rekordokkal.</li><li>Készíts csak küldésre jogosult API-kulcsot az ellenőrzött domainhez.</li><li>Add meg itt a feladót és a kulcsot. A kulcs titkosítva, kizárólag a szerveren tárolódik; később nem olvasható vissza.</li></ol><a href="https://resend.com/signup" target="_blank" rel="noopener noreferrer">Resend megnyitása ↗</a><form id="mdMailConfigForm" autocomplete="off"><label class="field">Ellenőrzött feladó<input type="email" name="sender" required value="${esc(data.sender||'')}" placeholder="ertesites@hun01usar.hu" maxlength="254"></label><label class="field">Resend API-kulcs<input type="password" name="key" autocomplete="new-password" ${data.configured?'':'required'} placeholder="${data.configured?'Már beállítva · új kulcs csak cseréhez':'re_…'}"></label><label class="md-mail-toggle"><input type="checkbox" name="enabled" ${data.enabled?'checked':''}> Automatikus értesítések bekapcsolása</label><button type="submit" class="pill-btn">Beállítás mentése</button><p id="mdMailConfigStatus" role="status"></p></form></div></details><h3>Tesztküldés</h3><p class="profile-help">Geletei Gábor regisztrált címére és a központi címre. A teszt nem módosít iratadatot.</p><button class="secondary" onclick="mdQueueGeleteiTest(this)">Geletei Gábor tesztlevelének előkészítése</button><button class="secondary" onclick="mdMailSettings()">Állapot frissítése</button><div>${(data.tests||[]).map(t=>`<div class="de-row"><b>${esc(t.member_name||'Teszt')}</b><span>${esc(t.recipient)}</span><small>${esc(labels[t.state]||t.state)}${t.last_error?' · '+esc(t.last_error):''}</small></div>`).join('')}</div>`;document.querySelector('#mdMailConfigForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,values=Object.fromEntries(new FormData(form)),status=form.querySelector('[role=status]');form.querySelectorAll('input,button').forEach(e=>e.disabled=true);status.textContent='Mentés…';try{const {error}=await sb.rpc('hunor_configure_document_mail',{p_sender:values.sender.trim(),p_api_key:values.key.trim(),p_enabled:values.enabled==='on'});if(error)throw error;form.querySelector('[name=key]').value='';await mdMailSettings();notify('A levélküldési beállítások mentve. A küldési sor ötpercenként dolgozik.');}catch(e){form.querySelector('[name=key]').value='';status.textContent=e.message;form.querySelectorAll('input,button').forEach(e=>e.disabled=false);}};};
  window.mdQueueGeleteiTest=async button=>{if(!user?.isAdmin)return;const targets=members.filter(m=>m.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim()==='geletei gabor');if(targets.length!==1)return notify('Geletei Gábor nem azonosítható egyértelműen a tagnévsorban.');button.disabled=true;const {data,error}=await sb.rpc('hunor_queue_document_test',{p_member:targets[0].id});if(error){button.disabled=false;return tellError(error,'A teszt nem készíthető elő.');}await mdMailSettings();notify(data.configured?'A tesztlevelek küldési sorba kerültek.':'A tesztlevelek előkészítve, a levélküldő beállítására várnak.');};

