  function rcProgress(total){const ranks=[[0,'Újonc'],[100,'Bronz'],[300,'Ezüst'],[600,'Arany'],[1000,'Platina'],[1500,'Elit mentő']],current=ranks.filter(([limit])=>total>=limit).at(-1)||ranks[0],next=ranks.find(([limit])=>limit>total),percent=next?Math.max(0,Math.min(100,(total-current[0])/(next[0]-current[0])*100)):100;return `<div class="rc-progress-head"><b>${current[1]}</b><span>${next?`${next[0]-total} RC a következő rangig · ${next[1]}`:'Elit mentő rang elérve'}</span></div><div class="rc-progress" role="progressbar" aria-label="Haladás a következő RC-ranghoz" aria-valuenow="${Math.round(percent)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${percent}%"></i></div>`;}
