  function ewChecklist(c){if(!c)return '';const labels={unverified:'Igazolásra váró részvétel',pending_roles:'Elbírálandó szerepkör',missing_tasks:'Hiányzó kötelező feladatteljesítés',missing_assessments:'Hiányzó résztvevői értékelés',missing_excon:'Hiányzó EXCON-értékelés',missing_exam:'Hiányzó sikeres vizsga'};return `<div class="ew-checklist ${c.ready?'ready':''}"><h4>${c.ready?'✓ A teljesítési feltételek rendben':'A lezáráshoz még szükséges'}</h4><div>${Object.entries(labels).filter(([key])=>c[key]>0).map(([key,label])=>`<span><b>${c[key]}</b> ${label}</span>`).join('')||'<span>Nincs hiányzó kötelező adat.</span>'}${!c.verified?'<span>Legalább egy igazolt jelenlét szükséges.</span>':''}</div><small>Az önkéntes anonim oktatóértékelés nem lezárási feltétel.</small></div>`;}
