  async function ewRefreshNotices(force=false){if(!EVENT_WORKSPACE_ENABLED||!rcAllowed()){ewNotices=[];ewNoticeActor=null;document.querySelector('#ewNoticePanel')?.remove();document.querySelector('#ewNoticeBadge')?.remove();return;}if(ewNoticeBusy)return;ewNoticeBusy=true;const actor=user.id;try{const rows=await rcCall('event_notifications');if(user?.id!==actor||!rcAllowed())return;ewNotices=rows;ewNoticeActor=actor;let badge=document.querySelector('#ewNoticeBadge');const nav=document.querySelector('#nav [data-page="events"]');if(!badge&&nav){badge=document.createElement('span');badge.id='ewNoticeBadge';badge.className='ew-badge';nav.append(badge);}if(badge){badge.textContent=String(rows.length);badge.hidden=!rows.length;badge.setAttribute('aria-label',rows.length+' személyes eseményjelzés');}if(['home','events'].includes(page)){let panel=document.querySelector('#ewNoticePanel');if(rows.length&&!panel){panel=document.createElement('section');panel.id='ewNoticePanel';panel.className='panel ew-notice-panel';content.querySelector('.page-title')?.after(panel);if(!panel.isConnected)content.prepend(panel);}if(panel){if(rows.length)panel.innerHTML=`<div class="rc-section-head"><h2>Személyes teendőid <span class="ew-badge">${rows.length}</span></h2><small>Az elvégzett feladatok automatikusan eltűnnek.</small></div>${ewNoticeHtml(rows)}`;else panel.remove();}}}catch(e){if(force)notify(e.message);}finally{ewNoticeBusy=false;}}
  window.ewOpenNotice=async index=>{const n=ewNoticeActor===user?.id?ewNotices[index]:null;if(!n)return;if(n.kind==='research_ready'){ewActive=null;await rcOpenTab('research');return;}await ewOpenEvent(n.event_id,n.kind==='missing_assessments'?'assessment':n.kind==='feedback'?'feedback':'summary');};
  window.ewReadNotice=async index=>{const n=ewNoticeActor===user?.id?ewNotices[index]:null;if(!n)return;try{await rcCall('read_event_notification',{event_id:n.event_id,token:n.token});await ewRefreshNotices(true);}catch(e){notify(e.message);}};
  window.ewOpenEvent=async(id,tab='summary')=>{ewTab=tab;if(page!=='events')await window.setPage('events');await window.openEventDetails(id);};
