    if(ewTab==='feedback'){root.innerHTML=`<p class="rc-help">Az önkéntes anonim visszajelzés nem befolyásolja automatikusan az oktatói RC-t. A kitöltési idő az esemény befejezésétől 14 nap. Kis csoportban a teljes anonimitás nem garantálható.</p>${(d.feedback||[]).map(f=>`<article class="ew-person"><div><b>${esc(f.instructor_name)}</b><p>${esc(f.module_title||'Teljes esemény')} · ${f.submitted?'Beküldve':'Kitölthető'}</p><small>Határidő: ${rcDate(f.editable_until)}</small></div><button class="secondary" onclick="rcFeedback('${f.unit_id}','${f.instructor_id}',${f.submitted})">${f.submitted?'Indokolt javítás':'Értékelés kitöltése'}</button></article>`).join('')||'<p>Most nincs számodra kitölthető oktatói visszajelzés.</p>'}`;}
