  function phGuide(){const active=Boolean(wpState.device),ios=phPlatform==='ios',platform=phPlatform?phPhones[phPlatform]:'Válassz telefont';return `<div class="ph-guide-head"><span>${esc(platform)}</span><small>Beállítás erre a készülékre</small></div>${!phPlatform?'<p>Válaszd ki, milyen telefonod van. A hozzá tartozó lépések itt jelennek meg.</p>':`<ol class="ph-steps"><li class="done"><span>1</span><div><b>Telefon kiválasztva</b><p>${esc(platform)}. A választás a profilodban megmarad.</p></div></li><li class="${wpStandalone()?'done':''}"><span>2</span><div><b>HUNOR a főképernyőn</b><p>${ios?'Safariban nyisd meg a <strong>hun01usar.hu</strong> oldalt. Koppints a <strong>Megosztás</strong> gombra → <strong>Hozzáadás a főképernyőhöz</strong> → Hozzáadás. Ha „Megnyitás webalkalmazásként” kapcsolót látsz, hagyd bekapcsolva. Ezután a HUNOR ikonról nyisd meg, és jelentkezz be. iOS 16.4 vagy újabb szükséges.':'Chrome-ban nyisd meg a <strong>hun01usar.hu</strong> oldalt. A <strong>⋮ menü → Hozzáadás a kezdőképernyőhöz / Alkalmazás telepítése</strong> lehetőséggel tedd ki az ikont, majd onnan nyisd meg és jelentkezz be. Androidon támogatott Chrome-böngészőből is engedélyezhető a push.'}</p>${!ios&&phInstallPrompt?'<button type="button" class="secondary" onclick="phInstall()">HUNOR telepítése</button>':''}${wpStandalone()?'<small>✓ A HUNOR most alkalmazásnézetben fut.</small>':ios?'<small>A következő lépés az iPhone főképernyőjén lévő HUNOR ikonból érhető el.</small>':''}</div></li><li class="${active?'done':''}"><span>3</span><div><b>Értesítések engedélyezése</b><p>Koppints az alábbi gombra, majd a telefon kérdésénél válaszd az <strong>Engedélyezés</strong> lehetőséget. Az értesítések bekapcsolását a telefonon neked kell jóváhagynod.</p>${wpSupported()&&Notification.permission==='denied'?`<p class="ph-warning">Az engedély korábban tiltva lett. ${ios?'Beállítások → Értesítések → HUNOR → Értesítések engedélyezése.':'Chrome → ⋮ → Beállítások → Webhelybeállítások → Értesítések; a HUNOR-oldalt engedélyezd. Az Android alkalmazásértesítési engedélyét is ellenőrizd.'}</p>`:''}</div></li><li class="${phTestRun?.status==='received'?'done':''}"><span>4</span><div><b>Automatikus tesztértesítés</b><p>A sikeres bekapcsolás után automatikusan küldünk egy <strong>„Ez nem valódi riasztás”</strong> tesztet erre a készülékre. Nem kell külön tesztgombot keresned. Az átvételi állapotot lent mutatjuk.</p></div></li></ol>`}`;}
  wpPanel=function(){if(!wpPilot())return '';queueMicrotask(()=>wpLoad());return `<section class="wp-panel ph-panel"><div class="wp-head"><div><small>SAJÁT TELEFON · LÉPÉSRŐL LÉPÉSRE</small><h2>Telefonos értesítések</h2></div><span class="wp-device-mark">↗</span></div><fieldset class="ph-phone-picker"><legend>Milyen telefonod van?</legend>${Object.entries(phPhones).map(([value,label])=>`<label class="${phPlatform===value?'selected':''}"><input type="radio" name="wpPhoneChoice" value="${value}" ${phPlatform===value?'checked':''} onchange="phChoosePhone(this.value)"><span>${value==='ios'?'◉':'▣'}</span><b>${label}</b></label>`).join('')}</fieldset><div id="phGuide">${phGuide()}</div><div id="wpDeviceState" role="status" aria-live="polite">Beállítások betöltése…</div><div class="wp-actions"><button type="button" class="pill-btn" id="wpEnable" onclick="wpEnable()">Bekapcsolás és automatikus teszt</button><button type="button" class="secondary" id="wpTest" onclick="wpTest()" disabled>Új teszt erre a készülékre</button><button type="button" class="secondary" id="wpDisable" onclick="wpDisable()" hidden>Kikapcsolás ezen a készüléken</button></div><p id="wpResult" class="profile-help" role="status" aria-live="polite"></p><section class="ph-sound-settings"><h3>Riasztási hang a megnyitott HUNOR-felületen</h3><label><input type="checkbox" id="phSoundOpt" ${phSoundWanted()?'checked':''} onchange="phToggleSound(this.checked)"> Szirénajelzés engedélyezése ezen a készüléken</label><button type="button" class="secondary" onclick="phPreviewSound()">3 másodperces hangpróba</button><p>A hang a megnyitott, aktív HUNOR-felületen, válaszra váró riasztásnál szólhat, és a válaszod mentésekor leáll. A telefon zárolásakor vagy háttérben ezt a böngésző felfüggesztheti. A zárolt képernyő push-hangját a telefon rendszere kezeli; a honlap nem tud folyamatos szirénát vagy el nem tüntethető rendszerértesítést kikényszeríteni.</p><p id="phSoundState" role="status"></p></section><p class="ph-security-note">Éles riasztást csak adminisztrátor küldhet. A saját készüléked próbaértesítése ettől különálló teszt.</p></section>`;};
  function phPaintGuide(){const target=document.querySelector('#phGuide');if(target)target.innerHTML=phGuide();document.querySelectorAll('.ph-phone-picker input').forEach(input=>{input.checked=input.value===phPlatform;input.closest('label')?.classList.toggle('selected',input.checked);});}
  wpPaint=function(){const target=document.querySelector('#wpDeviceState');if(!target)return;const active=Boolean(wpState.device),ready=Boolean(phPlatform)&&phCanEnable();target.textContent=wpState.error||(active?'✓ Ez a készülék regisztrálva: '+wpState.device.device_label:!phPlatform?'Válaszd ki az iPhone vagy az Android lehetőséget.':!phOnPhone()?'Az útmutatót itt is megtekintheted; a bekapcsolást a saját telefonodon végezd el.':(phActualIOS()&&phPlatform!=='ios'||!phActualIOS()&&phPlatform!=='android')?'A készülékednek megfelelő telefont válaszd ki.':phActualIOS()&&!wpStandalone()?'iPhone-on a főképernyőn lévő HUNOR ikonról folytasd.':!wpSupported()?'A push ezen a böngészőn nem támogatott. A választott telefonon, friss Safari / Chrome alkalmazásból folytasd.':'A készülék regisztrálásra kész.');const enable=document.querySelector('#wpEnable');enable.disabled=wpState.busy||!ready;enable.textContent=active?'Beállítás ellenőrzése és teszt':'Bekapcsolás és automatikus teszt';document.querySelector('#wpTest').disabled=wpState.busy||!active;document.querySelector('#wpDisable').hidden=!active;document.querySelector('#wpDisable').disabled=wpState.busy;phPaintGuide();};
  const phOriginalLoad=wpLoad;
  wpLoad=async function(force=false){if(!wpPilot())return;if(phPrefsActor!==user.id){phPlatform='';phTestRun=null;const actor=user.id;try{const platform=await phPreferences();if(user?.id===actor){phPlatform=platform;phPrefsActor=actor;}}catch(e){wpState.error=e.message;}}await phOriginalLoad(force);if(wpPilot()&&phOnPhone()&&!phActualIOS()&&wpSupported()&&!wpStandalone()&&phPlatform==='android'&&Notification.permission==='granted'){try{const reg=await navigator.serviceWorker.getRegistration('/'),sub=await reg?.pushManager.getSubscription();if(sub){const actor=user.id,result=await wpCall('register',{subscription:sub.toJSON(),label:'Android / Chrome'});if(user?.id===actor)wpState.device=result.device;}}catch{}}wpPaint();};
  window.phChoosePhone=async value=>{if(!wpPilot()||!phPhones[value]||wpState.busy)return;const actor=user.id;wpState.busy=true;wpPaint();try{const platform=await phPreferences(value);if(user?.id!==actor)return;phPlatform=platform;phPrefsActor=actor;wpState.error='';}catch(e){if(user?.id===actor)wpState.error=e.message;}finally{if(user?.id===actor){wpState.busy=false;wpPaint();}}};
  window.phInstall=async()=>{if(!phInstallPrompt)return;const event=phInstallPrompt;phInstallPrompt=null;await event.prompt();await event.userChoice;phPaintGuide();};
  window.wpEnable=async()=>{if(!wpPilot()||wpState.busy||!phPlatform||!phCanEnable())return;const actor=user.id;const permissionPromise=Notification.requestPermission();wpState.busy=true;wpState.error='';wpPaint();let registered=false;try{const permission=await permissionPromise;if(permission!=='granted')throw Error('Az értesítési engedélyt nem kaptuk meg. A fenti útmutató szerint engedélyezd a telefon beállításainál.');if(!wpState.publicKey){const config=await wpCall('config');wpState.publicKey=config.publicKey;}const registration=await rxReadyPushRegistration();let subscription=await registration.pushManager.getSubscription();if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:wpKey(wpState.publicKey)});const result=await wpCall('register',{subscription:subscription.toJSON(),label:phPlatform==='ios'?'iPhone / iPad':'Android / Chrome'});if(user?.id!==actor)return;wpState.device=result.device;registered=true;const state=document.querySelector('#wpResult');if(state)state.textContent='A készülék regisztrálva. Az automatikus teszt küldése következik…';}catch(e){if(user?.id===actor)wpState.error=e.message;}finally{if(user?.id===actor){wpState.busy=false;wpPaint();}}if(registered&&user?.id===actor)await phSendTest(true);};
  async function phSendTest(automatic=false){if(!wpPilot()||wpState.busy||!wpState.device)return;const actor=user.id;wpState.busy=true;wpPaint();try{const result=await wpCall('test',{deviceId:wpState.device.id});if(user?.id!==actor)return;phTestRun={id:result.runId,status:phTestReceived.has(result.runId)?'received':result.status};phPaintTestResult();}catch(e){if(user?.id===actor){const target=document.querySelector('#wpResult');if(target)target.textContent=(automatic?'A készülék regisztrálva, de az automatikus teszt még nem sikerült: ':'')+e.message;}}finally{if(user?.id===actor){wpState.busy=false;wpPaint();}}}
  function phPaintTestResult(){const target=document.querySelector('#wpResult');if(!target||!phTestRun)return;target.textContent=phTestRun.status==='received'?'✓ A tesztértesítés megérkezett erre a készülékre. A beállítás elkészült.':phTestRun.status==='accepted'?'A push-szolgáltatás átvette a tesztet. Ellenőrizd a telefon értesítéseit; az átvétel még nem igazolja a készülékre érkezést.':'A teszt eredménye ellenőrzést igényel.';phPaintGuide();}
