  if('serviceWorker'in navigator)navigator.serviceWorker.addEventListener('message',event=>{if(event.data?.type!=='HUNOR_PUSH_TEST_RECEIVED'||!apUuid(event.data.runId))return;phTestReceived.add(event.data.runId);if(phTestReceived.size>20)phTestReceived=new Set([event.data.runId]);if(phTestRun?.id===event.data.runId){phTestRun.status='received';phPaintTestResult();}});
  async function phUnlockAudio(){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('Ezen a böngészőn nincs hangjelzés-támogatás.');if(!phAudio||phAudio.state==='closed')phAudio=new Audio();await phAudio.resume();return phAudio.state==='running';}
  function phStartSiren(){if(phTone||phAudio?.state!=='running')return;const carrier=phAudio.createOscillator(),sweep=phAudio.createOscillator(),modulation=phAudio.createGain(),volume=phAudio.createGain();carrier.type='triangle';carrier.frequency.value=860;sweep.type='sine';sweep.frequency.value=.7;modulation.gain.value=250;volume.gain.value=.065;sweep.connect(modulation);modulation.connect(carrier.frequency);carrier.connect(volume);volume.connect(phAudio.destination);carrier.start();sweep.start();phTone={carrier,sweep,modulation,volume};}
  function phStopSiren(){if(!phTone)return;for(const n of [phTone.carrier,phTone.sweep]){try{n.stop();n.disconnect();}catch{}}phTone.modulation.disconnect();phTone.volume.disconnect();phTone=null;}
  function phHasPending(){return wpPilot()&&apActor===user.id&&apInbox.length>0;}
  function phSyncSiren(){const pending=phHasPending();if(pending&&phSoundWanted()&&document.visibilityState==='visible'&&phAudio?.state==='running')phStartSiren();else if(!phPreviewTimer)phStopSiren();const text=document.querySelector('#phSoundState');if(text)text.textContent=phTone?'A hangjelzés aktív.':phSoundWanted()?'A hangjelzés engedélyezve. Új megnyitáskor koppintás szükséges lehet az indításához.':'A hangjelzés kikapcsolva.';const strip=document.querySelector('#apInbox');if(strip&&phSoundWanted()&&phAudio?.state!=='running'&&!strip.querySelector('[data-ph-arm]')){const button=document.createElement('button');button.type='button';button.className='secondary';button.dataset.phArm='1';button.textContent='Riasztási hang indítása';button.onclick=()=>phArmPending();strip.append(button);}if(!pending)document.querySelector('[data-ph-arm]')?.remove();}
  window.phArmPending=async()=>{try{await phUnlockAudio();phSyncSiren();document.querySelector('[data-ph-arm]')?.remove();}catch(e){notify(e.message);}};
  window.phToggleSound=async enabled=>{if(!wpPilot())return;try{localStorage.setItem(phSoundKey(),enabled?'enabled':'disabled');if(enabled)await phUnlockAudio();else{clearTimeout(phPreviewTimer);phPreviewTimer=null;phStopSiren();}phSyncSiren();}catch(e){notify(e.message);}};
  window.phPreviewSound=async()=>{try{await phUnlockAudio();phStartSiren();clearTimeout(phPreviewTimer);phPreviewTimer=setTimeout(()=>{phPreviewTimer=null;phStopSiren();phSyncSiren();},3000);phSyncSiren();}catch(e){notify(e.message);}};
