  // Public articles are equally visible to members; no map embed or duplicate article data.
  function phNewsPanel(){const rows=publicItems.filter(x=>x.visibility==='public'&&x.entryType==='Cikk').sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||''))).slice(0,3);return `<section class="panel ph-news-panel" aria-label="Nyilvános hírek a csapattagoknak"><header class="panel-head"><div><div class="eyebrow">HUNOR · A NYILVÁNOS OLDAL HÍREI</div><h3>Hírek a mentőcsapattól</h3></div><button class="text-btn" onclick="phOpenNews()">Minden hír →</button></header><div class="ph-news-grid">${rows.length?rows.map(x=>{const image=x.media?.find(m=>m.type==='image'&&m.src);return `<article class="ph-news-card"><button type="button" class="ph-news-link" data-article="${esc(x.id)}" onclick="openPublicArticle(this.dataset.article)">${image?`<img src="${esc(image.src)}" alt="" loading="lazy" decoding="async">`:'<span class="ph-news-placeholder" aria-hidden="true">HUNOR</span>'}<div><small>${esc(x.topic||'Hírek')} · ${esc(x.date||'')}</small><h4>${esc(x.title)}</h4><p>${esc((x.description||x.content||'').slice(0,160))}${(x.description||x.content||'').length>160?'…':''}</p><span>Beszámoló megnyitása →</span></div></button></article>`;}).join(''):'<p class="empty">Hamarosan új nyilvános beszámolókkal jelentkezünk.</p>'}</div></section>`;}
  window.phOpenNews=()=>openModal('<div class="modal-head"><h2>Nyilvános hírek</h2><button class="close" onclick="closeModal()" aria-label="Bezárás">×</button></div>'+publicJournal());
  const phOriginalHome=home;
  home=function(){return phOriginalHome().replace(/<div class="panel map-panel">[\s\S]*?<\/iframe><\/div>/,phNewsPanel());};

  // Seasonal class is removed at Budapest midnight, even while a page remains open.
  const hsExpires=Date.parse('2026-11-03T00:00:00+01:00');
  function hsActive(now=Date.now()){if(document.documentElement.dataset.hunorTheme)return false;return now>=Date.parse('2026-10-14T00:00:00+02:00')&&now<hsExpires;}
  function hsSync(){document.documentElement.classList.toggle('hunor-halloween',hsActive());if(!hsActive())document.querySelectorAll('[data-halloween]').forEach(el=>el.remove());}
  hsSync();if(hsActive())setTimeout(hsSync,Math.max(0,hsExpires-Date.now()));setInterval(hsSync,30000);document.addEventListener('visibilitychange',hsSync);
  const phPreviousSetPage=window.setPage;
  window.setPage=async function(...args){await phPreviousSetPage(...args);hsSync();document.body.classList.toggle('ph-no-alert-admin',!phAdmin());if(!phAdmin())content.querySelectorAll('.event-row[data-event-id]').forEach(row=>{if(events.find(e=>e.id===row.dataset.eventId)?.eventType==='alert')row.querySelectorAll('button').forEach(button=>{if(['Szerkesztés','Törlés'].includes(button.textContent.trim()))button.remove();});});if(hsActive()&&!document.querySelector('[data-halloween]')){const target=page==='landing'?content.querySelector('.landing-copy'):guest?content.querySelector('.journal-head>div'):page==='home'?content.querySelector('.welcome>div'):null;if(target){const badge=document.createElement('div');badge.dataset.halloween='1';badge.className='hs-badge';badge.innerHTML='<span aria-hidden="true">🎃</span> Halloween a HUNOR-portálon';target.prepend(badge);}}if(!wpPilot()){phPlatform='';phPrefsActor=null;phTestRun=null;phStopSiren();}phSyncSiren();};

  function phRcGuide(){return `<section class="panel rc-user-guide"><div class="eyebrow">RESCUE COINS · HASZNÁLATI ÚTMUTATÓ</div><h2>Így használd a Rescue Coins rendszert</h2><p>Az események szervezésének központja az <strong>Események</strong> menü. A Rescue Coins az igazolt teljesítésekből mutatja a pontokat, a rangokat és a szakmai fejlődést.</p><div class="rc-tools"><button class="pill-btn" onclick="setPage('events')">Események megnyitása →</button><button class="secondary" onclick="rcOpenTab('overview')">Saját RC-egyenlegem →</button></div><details open><summary>1. Tagként: jelentkezés és saját eredmények</summary><ol><li>Az Eseményeknél nyisd meg a kiválasztott programot.</li><li>Jelentkezéskor válaszd ki a kívánt szerepkörödet: résztvevő, oktató, gyakorlatvezető, szervező vagy EXCON. Modulonként is lehet eltérő szereped. A szervező hagyja jóvá a választást.</li><li>A programon vegyél részt, és teljesítsd az előírt feladatokat. A tényleges jelenlétet és az eredményeket az arra jogosult oktató vagy vezető igazolja.</li><li>Az admin jóváhagyása után itt, az Áttekintés / Ponttörténet alatt láthatod a jóváírásokat. A Kompetenciáim és Saját értékeléseim részek külön mutatják a szakmai fejlődést.</li></ol><p>A jelentkezés és a riasztás elfogadása önmagában nem ad RC-t. Az RC nem pénz, nem átruházható és nem alkalmassági minősítés.</p></details><details><summary>2. Szervezőként: az esemény előkészítése</summary><ol><li>Új eseményt az admin vagy szerkesztő hozhat létre. Válassz eseménykategóriát és kezdő állapotot. A kategória RC-alapértéke és elszámolási egysége automatikusan megjelenik.</li><li>Az esemény adatlapján, az Eseménymunkaterület → Áttekintés alatt add meg a célokat, a forgatókönyvet, a teljesítési és mérési feltételeket.</li><li>Vedd fel a képzési modulokat, a hozzájuk tartozó kompetenciát és az igazolható napokat / alkalmakat / modulegységeket.</li><li>A Szerepek és jelenlét alatt bíráld el a szerepkörkérelmeket, vagy jelöld ki közvetlenül a tagokat. Az egész eseményre szóló jóváhagyás a már létező egységekre vonatkozik.</li><li>A Feladatok alatt add meg az előírt feladatokat és sikerességi feltételeiket. Kompetenciacél esetén válassz kompetenciát és elérendő szintet.</li></ol><p>Oktatói szerephez az adott témára érvényes, külön oktatói jogosultság szükséges. Az értékelői rendszerjogosultság és az eseményhez való kijelölés is számít.</p></details><details><summary>3. Oktatóként / vezetőként: jelenlét, feladatok és értékelések</summary><ol><li>Igazold a tényleges jelenlétet és, ha szükséges, a vizsga eredményét.</li><li>Feladatonként rögzítsd: teljesítette, nem teljesítette, részben teljesítette vagy nem értékelhető. Adj megjegyzést, mért végrehajtási időt, szükség szerint igazolást.</li><li>Az Értékelések lapon töltsd ki az előírt résztvevői értékelést. Az EXCON és mérések lapon a csapatszintű rubrikák, megfigyelések és T0–T3 mérések érhetők el.</li><li>Véglegesített adatok javításakor indoklást és új változatot rögzíts; az előzmények megmaradnak.</li></ol><p>Az 1–5 skálából számolt értékelési index nem RC. A „nem megfigyelhető” érték nem nulla. Saját magadat nem értékelheted.</p></details><details><summary>4. Az esemény hét állapota és lezárása</summary><ol><li><strong>Tervezet:</strong> csak a szervezők látják.</li><li><strong>Meghirdetve:</strong> jelentkezés nyitva.</li><li><strong>Jelentkezés lezárva:</strong> új jelentkezés nem fogadható.</li><li><strong>Folyamatban:</strong> zajlik a végrehajtás.</li><li><strong>Értékelés alatt:</strong> a végrehajtás után a jelenlét, feladatok és értékelések rendezése.</li><li><strong>Jóváhagyásra vár:</strong> a kötelező feltételek teljesültek; a rendszer az adminnak jelzi a teendőt.</li><li><strong>Lezárva:</strong> admin-jóváhagyás és pontelszámolás megtörtént.</li></ol><p>A lezárási ellenőrzés megmutatja a hiányzó jelenléteket, szerepkör-döntéseket, feladatokat, vizsgákat és értékeléseket. A kötelező feladatnál a részleges teljesítés nem elég; indokolt N/M-felmentést csak admin adhat, és ez nem igazol kompetenciát.</p><p>Adminisztrátorként a <strong>Jóváhagyás és RC-elszámolás</strong> gombbal, indoklással véglegesíthetsz. Ugyanaz a teljesítés nem kap kétszer pontot. Hiba esetén a teljes elszámolás visszavonódik.</p></details><details><summary>5. Pontozás, bónuszok, rangok és kompetenciák</summary><p>Az esemény kategóriája határozza meg az alappontot és az elszámolási egységet. Az aktuális kategória az esemény adatlapján látható. Admin indoklással írhatja felül az eseményszintű alapértéket.</p><ul><li>Csak igazolt részvétel vagy külön jóváhagyott teljesítés számít.</li><li>A jogosult szerepköri bónuszok közül a legmagasabb érvényesül; nem adódnak össze.</li><li>A témaspecifikus oktatói bónuszhoz érvényes oktatói jogosultság kell.</li><li>Az előre meghatározott kompetenciafeladatok igazolt teljesítése a jóváhagyáskor frissítheti a kompetenciaszintet, és a szabály szerinti külön RC-t adhat.</li><li>Tananyag és mentorálás elismeréséhez dokumentált, admin által jóváhagyott teljesítés szükséges.</li><li>A havi, éves és életpálya-pontok, a ranglista és a jelvények az igazolt tranzakciókból frissülnek.</li><li>Hibás pontot az admin indokolt korrekcióval javíthat; az eredeti bejegyzés megmarad.</li></ul><p>A Szabályok és igazolások adminlapján kezelhetők a kategóriák, bónuszszabályok, értékelősablonok és külön RC-jogosultságok.</p></details><details><summary>6. Anonim oktatóértékelés és személyes teendők</summary><p>Igazolt hallgatóként a program befejezését követő 14 napban értékelheted az oktatódat. Az esemény Oktatói visszajelzés lapja vagy az itteni Oktatók értékelése rész vezet a kitöltéshez.</p><p>Ez önkéntes: hiánya nem akadályozza a hallgatói RC-jóváírást, és az oktatói RC-t sem módosítja automatikusan. Összesítéshez legalább 3 különböző válasz szükséges; szöveges vélemények csak ellenőrzés után, legalább 5 válasznál jelenhetnek meg. Kis csoportban a teljes anonimitás nem garantálható. Javításhoz őrizd meg a saját javítási kódodat.</p><p>Az Áttekintés és az Események személyes teendőpanelje jelzi a hiányzó résztvevői értékelést, a kitölthető oktatóértékelést, az admin-jóváhagyást és a kutatónak az elkészült EXCON-adatokat. A teendő teljesítéskor automatikusan eltűnik. Ezek honlapon belüli jelzések.</p></details><details><summary>7. Kutatás, adatkezelés és jogosultságok</summary><p>A részvétel, a feladateredmények, az értékelések, a kompetenciák és az EXCON ugyanahhoz a meglévő eseményhez kapcsolódnak. Nem kell újra bevinni őket külön kutatási eseménybe.</p><p>Kutatói jogosultsággal célmegadáshoz kötött, naplózott, álnevesített export érhető el. A névmegfeleltetéshez külön adatgazdai jogosultság kell; a kutatói jogosultság önmagában nem ad ilyen hozzáférést.</p><p>A pilot adatok és az engedélyezett éles kutatási gyűjtés elkülönülnek. Az éles adatgyűjtéshez előbb az adatkezelési keretet kell rögzíteni és engedélyezni. A saját fejlesztésű skálák nem minősülnek validált mérőeszköznek.</p></details></section>`;}
  const phGuideRender=rcRender;
  rcRender=async function(){if(rcTab==='guide'){const root=document.querySelector('#rcBody');if(root&&rcAllowed())root.innerHTML=phRcGuide();return;}return phGuideRender();};

  // Seasonal decorations carry no application state and disappear with the existing expiry.
  let hsWholeScheduled=false;
  function hsDecorateWholeSite(){
    if(!hsActive())return;
    const root=document.querySelector('#content');
    if(root&&root.children.length&&!root.querySelector(':scope>.hs-season-strip')){
      const strip=document.createElement('div');strip.className='hs-season-strip';strip.dataset.halloween='whole-site';
      strip.innerHTML='<span aria-hidden="true"></span><div><b>Halloween a HUNOR-portálon</b><small>Őszi hangulat · közös csapat, közös küldetés</small></div><i aria-hidden="true"></i>';
      root.prepend(strip);
    }
  }
  const hsWholePreviousSetPage=window.setPage;
  window.setPage=async function(...args){await hsWholePreviousSetPage(...args);hsDecorateWholeSite();};
  const hsWholeObserver=new MutationObserver(()=>{if(hsWholeScheduled||!hsActive())return;hsWholeScheduled=true;requestAnimationFrame(()=>{hsWholeScheduled=false;hsDecorateWholeSite();});});
  const hsWholeContent=document.querySelector('#content');if(hsWholeContent)hsWholeObserver.observe(hsWholeContent,{childList:true});
