  window.phJumpToPhone=()=>document.querySelector('.ph-panel')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});

  const rxRoles={commander:'Parancsnok',deputy_commander:'Parancsnok helyettes',liaison_officer:'Összekötő tiszt',operations_officer:'Műveleti tiszt',safety_officer:'Biztonsági tiszt',it_officer:'IT',logistics_officer:'Logisztika',unit_leader:'Alegységvezető',deputy_unit_leader:'Alegység vezető helyettes',technical_rescuer:'Műszaki mentő',coordination_officer:'Koordinációs tiszt',medical:'Egészségügy',k9:'K9',veterinarian:'Állatorvos'};
  const rxFold=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
  function rxRoleFits(person,key){return Boolean(rxRoles[key]&&rxFold(person.position)===rxFold(rxRoles[key]));}
  const rxMembersPage=window.membersPage;
  window.membersPage=()=>{const template=document.createElement('template');template.innerHTML=rxMembersPage();if(canManageMembers())template.content.querySelectorAll('.member-card').forEach(card=>{const id=card.dataset.memberId;if(!id)return;const state=card.querySelector('.alertability-state'),button=document.createElement('button');button.type='button';button.className='secondary rx-availability';button.textContent='Riaszthatóság módosítása';button.onclick=()=>window.rxEditAvailability(id);button.setAttribute('onclick',`rxEditAvailability('${id}')`);state?.after(button);});return template.innerHTML;};
  window.rxEditAvailability=id=>{if(!canManageMembers())return;window.mdReviewAlertability(id);const member=members.find(m=>m.id===id),form=document.querySelector('#mdReviewForm');if(!form)return;form.querySelector('[name=alertable]').value=member?.alertable===true?'true':'false';form.querySelector('[name=alertable] option[value=true]').textContent='Riasztható';form.querySelector('[name=note]').placeholder='A módosítás rövid indoklása';const intro=document.querySelector('.private-member-details>.profile-help');if(intro)intro.textContent='Adminisztrátor és tagságkezelő módosíthatja a riaszthatóságot. A döntést és az indoklást naplózzuk. Lejárt szolgálati útlevélnél a korlátozás feloldása iratellenőrzést igényel.';};

  let rxBirthdayData=null,rxBirthdayActor=null,rxBirthdayLoading=false;
  const rxToday=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Budapest',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  function rxPaintBirthdays(){document.querySelector('#rxBirthdayBanner')?.remove();if(!wpPilot()||rxBirthdayActor!==user.id||!rxBirthdayData?.celebrants?.length)return;const own=rxBirthdayData.celebrants.some(p=>p.is_me),others=rxBirthdayData.celebrants.filter(p=>!p.is_me);const banner=document.createElement('section');banner.id='rxBirthdayBanner';banner.className='rx-birthday'+(own?' rx-birthday-own':'');banner.setAttribute('role','status');banner.innerHTML=`<span aria-hidden="true">🎂</span><div>${own?'<h2>Boldog születésnapot kíván a HUNOR csapata! Legyen szép napod!</h2>':''}${others.length?`<p>Ma ${others.map(p=>`<strong>${esc(p.name)}</strong>`).join(', ')} ${others.length===1?'születésnapja van':'ünnepli a születésnapját'}. Köszöntsük fel!</p>`:''}</div>`;const strip=content.querySelector(':scope>.hs-season-strip');if(strip)strip.after(banner);else content.prepend(banner);}
  async function rxLoadBirthdays(){if(!wpPilot()){rxBirthdayData=null;rxBirthdayActor=null;document.querySelector('#rxBirthdayBanner')?.remove();return;}if(rxBirthdayActor===user.id&&rxBirthdayData?.day===rxToday()){rxPaintBirthdays();return;}if(rxBirthdayLoading)return;const actor=user.id;rxBirthdayLoading=true;try{const {data,error}=await sb.rpc('hunor_today_birthdays');if(error)throw error;if(user?.id===actor){rxBirthdayData=data;rxBirthdayActor=actor;rxPaintBirthdays();}}catch(e){console.warn('A születésnapi jelzés nem tölthető be.');}finally{rxBirthdayLoading=false;}}
  const rxPreviousSetPage=window.setPage;
  window.setPage=async function(...args){await rxPreviousSetPage(...args);rxLoadBirthdays();rxUpdateLogo();};
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')rxLoadBirthdays();});
  setInterval(()=>{if(document.visibilityState==='visible'&&rxBirthdayData?.day!==rxToday())rxLoadBirthdays();},30000);
  function rxUpdateLogo(){if(document.documentElement.dataset.hunorTheme)return;document.querySelectorAll('img.brand-logo').forEach(img=>{if(hsActive()){if(!img.dataset.rxOriginalLogo)img.dataset.rxOriginalLogo=img.getAttribute('src')||'';if(img.getAttribute('src')!=='/hunor-seasonal-logo-2026.webp')img.src='/hunor-seasonal-logo-2026.webp';img.classList.add('rx-seasonal-logo');}else if(img.dataset.rxOriginalLogo){img.src=img.dataset.rxOriginalLogo;img.classList.remove('rx-seasonal-logo');delete img.dataset.rxOriginalLogo;}});}
  new MutationObserver(rxUpdateLogo).observe(document.documentElement,{attributes:true,attributeFilter:['class']});rxUpdateLogo();

  // Use an actual media element, started directly by the user's gesture on iPhone too.
  let rxSiren=null,rxSirenUnlocked=false,rxSirenStarting=false;
  function rxAudio(){if(!rxSiren){rxSiren=new Audio('/hunor-siren.wav');rxSiren.preload='auto';rxSiren.loop=true;rxSiren.volume=.6;rxSiren.setAttribute('playsinline','');}return rxSiren;}
  function rxPlayAudio(){try{if('audioSession'in navigator)navigator.audioSession.type='playback';}catch{}const media=rxAudio();const promise=media.play();return Promise.resolve(promise).then(()=>{rxSirenUnlocked=true;});}
  phStartSiren=function(){if(rxSirenStarting||rxSiren&&!rxSiren.paused)return;rxSirenStarting=true;rxPlayAudio().catch(()=>{rxSirenUnlocked=false;const status=document.querySelector('#phSoundState');if(status)status.textContent='A böngésző hangengedélyt kér. Koppints a hangpróbára vagy a riasztási hang indítására.';}).finally(()=>rxSirenStarting=false);};
  phStopSiren=function(){if(rxSiren){rxSiren.pause();rxSiren.currentTime=0;}};
  phSyncSiren=function(){const pending=phHasPending(),wanted=phSoundWanted(),visible=document.visibilityState==='visible';if(pending&&wanted&&visible&&rxSirenUnlocked)phStartSiren();else if(!phPreviewTimer)phStopSiren();const playing=Boolean(rxSiren&&!rxSiren.paused),status=document.querySelector('#phSoundState');if(status)status.textContent=playing?'A szirénajelzés szól.':wanted?(rxSirenUnlocked?'A hangjelzés ebben a megnyitásban engedélyezve.':'A hang engedélyezve; indításához koppints a hangpróbára.'):'A hangjelzés kikapcsolva.';const strip=document.querySelector('#apInbox');if(strip&&pending&&wanted&&!rxSirenUnlocked&&!strip.querySelector('[data-ph-arm]')){const b=document.createElement('button');b.type='button';b.dataset.phArm='1';b.className='secondary';b.textContent='Riasztási hang indítása';b.onclick=()=>phArmPending();strip.append(b);}if(!pending||rxSirenUnlocked)document.querySelector('[data-ph-arm]')?.remove();};
  window.phPreviewSound=()=>{if(!wpPilot())return;clearTimeout(phPreviewTimer);phPreviewTimer=setTimeout(()=>{phPreviewTimer=null;phStopSiren();},15000);const play=rxPlayAudio();play.then(()=>{clearTimeout(phPreviewTimer);phPreviewTimer=setTimeout(()=>{phPreviewTimer=null;phStopSiren();phSyncSiren();},3000);phSyncSiren();}).catch(e=>{clearTimeout(phPreviewTimer);phPreviewTimer=null;const status=document.querySelector('#phSoundState');if(status)status.textContent='A hangpróba nem indult: '+(e.name==='NotAllowedError'?'a böngésző letiltotta a lejátszást. Próbáld újra közvetlen koppintással.':'ellenőrizd a készülék médiahangerejét és a kapcsolatot.');});};
  window.phToggleSound=enabled=>{if(!wpPilot())return;if(!enabled){localStorage.setItem(phSoundKey(),'disabled');clearTimeout(phPreviewTimer);phPreviewTimer=null;phStopSiren();phSyncSiren();return;}clearTimeout(phPreviewTimer);phPreviewTimer=setTimeout(()=>{phPreviewTimer=null;phStopSiren();},15000);const play=rxPlayAudio();play.then(()=>{clearTimeout(phPreviewTimer);localStorage.setItem(phSoundKey(),'enabled');phPreviewTimer=setTimeout(()=>{phPreviewTimer=null;phStopSiren();phSyncSiren();},3000);phSyncSiren();}).catch(()=>{clearTimeout(phPreviewTimer);phPreviewTimer=null;localStorage.setItem(phSoundKey(),'disabled');const check=document.querySelector('#phSoundOpt');if(check)check.checked=false;const status=document.querySelector('#phSoundState');if(status)status.textContent='A böngésző nem engedte a hangot. Koppints a hangpróbára, és ellenőrizd a médiahangert.';});};
  window.phArmPending=()=>{phPreviewTimer=setTimeout(()=>{phPreviewTimer=null;phStopSiren();},15000);const play=rxPlayAudio();play.then(()=>{clearTimeout(phPreviewTimer);phPreviewTimer=null;phSyncSiren();}).catch(()=>notify('A hangot a böngésző blokkolta. Próbáld a profil hangpróbájával.'));};
  const rxBaseSendTest=phSendTest;
  const rxTestKey=()=>wpState.device&&user?.id?'hunor_auto_test_20261014d_'+user.id+'_'+wpState.device.id:'';
  phSendTest=async function(automatic=false){const key=rxTestKey(),previousRun=phTestRun?.id;if(key)try{localStorage.setItem(key,String(Date.now()));}catch{}await rxBaseSendTest(automatic);if(key&&(phTestRun?.id===previousRun||!['accepted','received'].includes(phTestRun?.status)))try{localStorage.setItem(key,String(Date.now()-24*60*60*1000+5*60*1000));}catch{}};
  const rxBasePhoneLoad=wpLoad;
