  const sgMessages={STEP_UP_REQUIRED:'A védett adatok megnyitásához külön hitelesítés szükséges.',
    LOCKED:'Három sikertelen próbálkozás után a feloldás 15 percre zárolódik.',
    VERIFICATION_FAILED:'A hitelesítés nem sikerült. Ellenőrizd a kódot vagy a készülékes hitelesítést.',
    INVALID_CODE:'Pontosan 6 számjegyet adj meg.',NO_PASSKEY:'Még nincs beállítva készülékes hitelesítés.',
    SERVICE_UNAVAILABLE:'A biztonsági szolgáltatás nem érhető el. A védett adatokat nem nyitjuk meg.',
    FORBIDDEN:'Ehhez a művelethez nincs jogosultságod.'};
  async function sgApi(action,values={}){
    const actor=user?.id,controller=new AbortController();let sgRequestTimeout;
    const timeout=new Promise((_,reject)=>{sgRequestTimeout=setTimeout(()=>{controller.abort();reject(Object.assign(Error('A hitelesítési szolgáltatás válasza túl sokáig tartott. Ellenőrizd az internetkapcsolatot, majd próbáld újra. A védett adatok zárolva maradnak.'),{code:'SERVICE_UNAVAILABLE'}));},20000);});
    const request=async()=>{
      const {data,error}=await sb.auth.getSession();
      if(error||!actor||actor!==user?.id||!data.session?.access_token)throw Error('Jelentkezz be újra.');
      const response=await fetch('https://embicteneumubwlqqfik.supabase.co/functions/v1/hunor-sensitive-guard',{
        method:'POST',cache:'no-store',credentials:'omit',signal:controller.signal,headers:{Authorization:'Bearer '+data.session.access_token,
        apikey:SUPABASE_PUBLISHABLE_KEY,'Content-Type':'application/json'},body:JSON.stringify({action,...values})});
      const result=await response.json();if(actor!==user?.id)throw Error('A munkamenet megváltozott.');
      if(!response.ok||!result.ok)throw Object.assign(Error(sgMessages[result.error]||'A biztonsági művelet nem sikerült.'),{code:result.error});
      return result;
    };
    try{return await Promise.race([request(),timeout]);}
    catch(error){if(error.code||error.message==='Jelentkezz be újra.'||error.message==='A munkamenet megváltozott.')throw error;throw Object.assign(Error('A hitelesítési szolgáltatást nem sikerült elérni. Ellenőrizd az internetkapcsolatot, majd próbáld újra.'),{code:'SERVICE_UNAVAILABLE'});}
    finally{clearTimeout(sgRequestTimeout);controller.abort();}
  }
