  async function sgBusy(form,work){
    if(form.dataset.sdgBusy==='true')return;
    form.dataset.sdgBusy='true';
    const status=document.querySelector('#sdgStatus'),submit=form.id==='sdgVerifyForm'?form.querySelector('[type="submit"]'):null,label=submit?.textContent;
    const controls=Array.from(form.querySelectorAll('input,button')),previous=controls.map(el=>el.disabled);
    controls.forEach(el=>el.disabled=true);if(submit)submit.textContent='Hitelesítés folyamatban…';
    if(status){status.textContent='Hitelesítés folyamatban…';status.setAttribute('role','status');}
    try{await work();}catch(error){if(status?.isConnected){status.textContent=error.message||'A hitelesítés nem sikerült. Próbáld újra.';status.setAttribute('role','alert');status.scrollIntoView({block:'nearest'});}}
    finally{if(form.isConnected){controls.forEach((el,i)=>el.disabled=previous[i]);if(submit)submit.textContent=label;delete form.dataset.sdgBusy;}}
  }
  window.sdgEnrollTotp=async button=>{
    await sgBusy(button.closest('.sdg-panel'),async()=>{
      for(const f of sgState.totp_factors||[])if(f.status==='unverified')await sb.auth.mfa.unenroll({factorId:f.id});
      const {data,error}=await sb.auth.mfa.enroll({factorType:'totp',friendlyName:'HUNOR védett profil'});if(error)throw Error('A hitelesítő beállítása nem sikerült.');
      sgFactor=data.id;const box=document.querySelector('#sdgEnrollment');
      const source=data.totp.qr_code.startsWith('data:')?data.totp.qr_code:'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(data.totp.qr_code);
      box.innerHTML=`<p>Olvasd be a QR-kódot egy hitelesítő alkalmazással (például Microsoft vagy Google Authenticator), majd add meg az ott látható 6 számjegyet.</p><img class="sdg-qr" src="${esc(source)}" alt="Saját hitelesítő beállításának QR-kódja"><details><summary>Kézi beállítási kulcs</summary><code>${esc(data.totp.secret)}</code></details><p class="profile-help">A kulcsot és a QR-kódot ne oszd meg. Bezárás után itt nem őrizzük meg. Bekapcsoláskor más készülékeiden újra be kell jelentkezned.</p>`;
      document.querySelector('#sdgStatus').textContent='Add meg a hitelesítő alkalmazás kódját.';button.hidden=true;
    });
  };
  window.sdgVerifyTotp=event=>{
    event.preventDefault();const form=event.currentTarget;
    return sgBusy(form,async()=>{
      if(!sgFactor)throw Error('Először állítsd be a hitelesítő alkalmazást.');
      const input=form.elements.code,code=String(input.value).replace(/\s/g,'');
      if(!/^[0-9]{6}$/.test(code))throw Error('Pontosan 6 számjegyet adj meg a hitelesítő alkalmazásból.');
      input.value='';
      const result=await sgApi('totp',{factor_id:sgFactor,code});
      const {error}=await sb.auth.setSession(result.session);if(error)throw Error('A munkamenet frissítése nem sikerült.');
      await sgStatus();sgArm();sgFinish(true);
    });
  };
  const sgFrom64=value=>Uint8Array.from(atob(value.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));
  const sgTo64=value=>btoa(String.fromCharCode(...new Uint8Array(value))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
  function sgCredential(credential){const r=credential.response;
    return {id:credential.id,rawId:sgTo64(credential.rawId),type:credential.type,
      authenticatorAttachment:credential.authenticatorAttachment||undefined,clientExtensionResults:credential.getClientExtensionResults(),
      response:r.attestationObject?{clientDataJSON:sgTo64(r.clientDataJSON),attestationObject:sgTo64(r.attestationObject),transports:r.getTransports?.()||[]}:
      {clientDataJSON:sgTo64(r.clientDataJSON),authenticatorData:sgTo64(r.authenticatorData),signature:sgTo64(r.signature),userHandle:r.userHandle?sgTo64(r.userHandle):undefined}};
  }
  async function sgPasskey(registration){
    if(!window.PublicKeyCredential||!navigator.credentials)throw Error('Ez a böngésző nem támogatja a készülékes hitelesítést.');
    const name=registration?'registration':'authentication',result=await sgApi(name+'-options');
    const options={...result.options,challenge:sgFrom64(result.options.challenge)};
    if(registration){options.user={...options.user,id:sgFrom64(options.user.id)};options.excludeCredentials=options.excludeCredentials?.map(c=>({...c,id:sgFrom64(c.id)}));}
    else options.allowCredentials=options.allowCredentials?.map(c=>({...c,id:sgFrom64(c.id)}));
    let credential;try{credential=await navigator.credentials[registration?'create':'get']({publicKey:options});}
    catch{throw Error('A készülékes hitelesítés megszakadt vagy nem érhető el.');}
    if(!credential)throw Error('A készülék nem adott hitelesítési igazolást.');
    return sgApi(name+'-verify',{challenge_id:result.challenge_id,response:sgCredential(credential)});
  }
