  const sgFrom=sb.from.bind(sb),sgRpc=sb.rpc.bind(sb);
  class SgQuery{
    constructor(table){this.table=table;this.operation='read';this.fields='*';this.ids=[];this.one=false;this.values=null;this.expected=null;}
    select(fields='*'){this.fields=fields;return this;}
    eq(key,value){if(key==='member_id')this.ids=[value];else if(key==='updated_at')this.expected=value;else this.invalid=true;return this;}
    in(key,values){if(key==='member_id')this.ids=values;else this.invalid=true;return this;}
    update(values){this.operation='update';this.values=values;return this;}
    insert(values){this.operation='insert';this.values=values;this.ids=[values.member_id];return this;}
    maybeSingle(){this.one=true;return this;}
    single(){this.one=true;return this;}
    then(resolve,reject){return this.execute().then(resolve,reject);}
    async execute(){try{
      if(this.invalid||!sgFresh())throw Error(sgMessages.STEP_UP_REQUIRED);
      const epoch=sgEpoch,actor=user.id;let result;
      if(this.operation==='read')result=await sgApi('read',{table:this.table,ids:this.ids,fields:this.fields});
      else{
        if(this.table!=='member_private_details'||this.ids.length!==1)throw Error(sgMessages.FORBIDDEN);
        const values={...this.values};delete values.member_id;
        result=await sgApi('write',{payload:{operation:this.operation,member_id:this.ids[0],updated_at:this.expected,values}});
      }
      if(epoch!==sgEpoch||actor!==user?.id||!sgFresh())throw Error(sgMessages.STEP_UP_REQUIRED);
      return {data:this.one?result.rows?.[0]||null:result.rows,error:null};
    }catch(error){return {data:null,error};}}
  }
  sb.from=table=>['member_private_details','member_document_controls'].includes(table)?new SgQuery(table):sgFrom(table);
