 identity:knowledgeIdentity,canUpload:()=>!!knowledgeIdentity()&&canUploadEducation(),
 async list(kind){const actor=knowledgeIdentity();if(!actor)throw Error('Jóváhagyott tagi belépés szükséges.');const {data,error}=await sb.from('resources').select('id,title,description,url,file_path,file_name,created_at').eq('visibility','members').eq('education_category',HunorKnowledgeCore.categories[kind]).eq('resource_type',kind==='links'?'link':'document').order('created_at',{ascending:false}).limit(1000);if(error)throw error;if(actor!==knowledgeIdentity())throw Error('A bejelentkezés közben megváltozott.');return data||[];},
 async openPDF(row){const actor=knowledgeIdentity();if(!actor||!row.file_path||!row.file_path.split('/').includes('knowledge-pdfs'))throw Error('Érvénytelen dokumentum.');const {data,error}=await sb.storage.from(EDUCATION_BUCKET).createSignedUrl(row.file_path,60);if(error)throw error;if(actor!==knowledgeIdentity())throw Error('A bejelentkezés közben megváltozott.');return HunorKnowledgeCore.url(data.signedUrl);},
 async save(kind,values,progress){const actor=knowledgeIdentity();if(!actor||!canUploadEducation())throw Error('Feltöltési jogosultság szükséges.');let path=null;try{if(kind==='pdfs'){await HunorKnowledgeCore.pdf(values.file);if(actor!==knowledgeIdentity())throw Error('Jelentkezz be újra.');const uploadFile=values.file.type?values.file:new File([values.file],values.file.name,{type:'application/pdf'});path=await uploadEducationFile(uploadFile,progress,EDUCATION_BUCKET,'knowledge-pdfs');}if(actor!==knowledgeIdentity())throw Error('A bejelentkezés közben megváltozott.');const {data,error}=await sb.from('resources').insert({title:values.title,description:values.description||null,resource_type:kind==='links'?'link':'document',url:kind==='links'?HunorKnowledgeCore.url(values.url):null,file_path:path,file_name:kind==='pdfs'?values.file.name:null,education_category:HunorKnowledgeCore.categories[kind],visibility:'members',created_by:actor.id}).select('id').single();if(error)throw error;if(!data?.id)throw Error('A szerver nem igazolta a mentést.');}catch(error){if(path&&actor===knowledgeIdentity())await sb.storage.from(EDUCATION_BUCKET).remove([path]);throw error;}}
